WordHunterWoW_QuestEN[80236] = { title = "Orecreg's Doglegs - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80237] = { title = "Earthenworks Weave", description = "Perilous aerial maneuvering awaits you on the course! Death-defying pursuit over a nightmarish landscape of magma awaits!\n\nIf you're up for the challenge, fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80238] = { title = "Ringing Deeps Ramble", description = "All right, rambler! Let's ramble! \n\nAs long as you remember which way is up and which is down, you should be fine on this one.\n\nNow that we've got that straight, you just need to fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80239] = { title = "Chittering Concourse", description = "I offer you aerial journey that offers an excellent view. You'll see countless chittering creatures in a tranquil panorama of subterranean wilderness. \n\nYou know what's more fun? A race! Just fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80240] = { title = "Cataract River Cruise", description = "Scenic river views and majestic waterfalls make this aerial race a delight! \n\nSoar through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80242] = { title = "Taelloch Twist", description = "Don't let the gloomy terrain distract you.\n\nThe mining town has gone through some changes, but the view is spectacular! \n\nIf you're got nerves of steel, fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80243] = { title = "Opportunity Point Amble", description = "The southern part of Ringing Deeps looks a little different from the north.\n\nEast or west, north or south, you'll still need quick reflexes and courage for racing!\n\nAfter you take a little leap skyward, fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80244] = { title = "Earthenworks Weave - Advanced", description = "The earthen below us tirelessly work at the same repetitive jobs day after day.\n\nBut you, you risk your life soaring over molten magma in reckless aerial races!\n\nIf you're up for doing that one more time, fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80245] = { title = "Ringing Deeps Ramble - Advanced", description = "You won't believe this next race. The green vistas! The towering rock spires! The gentle winds!\n\nJust fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80246] = { title = "Chittering Concourse - Advanced", description = "Have you done this before? Have you seen the magnificent wildlife? The tumultuous rivers? The cascading waterfalls?\n\nOh, you just want to race? Okay, that's simple. Just fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80247] = { title = "Cataract River Cruise - Advanced", description = "If you're up for a more difficult race, try finishing faster... and spend less time looking at scenery! \n\nJust fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80248] = { title = "Taelloch Twist - Advanced", description = "Look at them working down there! Do they enjoy watching the races sometimes?\n\nI guess it doesn't matter. You're still going to fly through the checkpoint rings marking the course. Have fun!", objectives = "" }
WordHunterWoW_QuestEN[80249] = { title = "Opportunity Point Amble - Advanced", description = "Hey, I found a pamphlet! It says:\n\n\"Bob and weave through towering rock spires, dive into sunken chasms, and soar through the final stretch to the finish line!\"\n\nI'm sure you know what that really means: fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80250] = { title = "Earthenworks Weave - Reverse", description = "The Earthenworks Weave features magma... and plenty of it! Try not to think about falling and burning to death in a roiling incendiary nightmare.\n\nFocus on flying through the checkpoint rings marking the course instead.", objectives = "" }
WordHunterWoW_QuestEN[80251] = { title = "Ringing Deeps Ramble - Reverse", description = "Does your head hurt? My head hurts. I got a little mixed up flying through the reverse version of this course.\n\nYou won't do that, will you? Of course not! Just fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80252] = { title = "Chittering Concourse - Reverse", description = "Enjoy the magnificent scenery... IN REVERSE! Just make sure you keep an eye out for rock spires along the way.\n\nYou'll also need to fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80253] = { title = "Cataract River Cruise - Reverse", description = "Sure, you can finish quickly, but can you do it... backwards? Not flying backwards. I meant the reverse course! \n\nYou'll still fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80254] = { title = "Taelloch Twist - Reverse", description = "Machine Speakers need to work. Dragonriders need to race! No matter how much their work crews ask us to stop distracting them! \n\nYou just need to fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[80255] = { title = "Opportunity Point Amble - Reverse", description = "I know this course so well, I could probably fly through it backwards. Hey, I bet you could too!\n\nI wouldn't want you to get lost, though. Just fly through the checkpoint rings marking the course.", objectives = "" }
