WordHunterWoW_QuestEN[80310] = { title = "Setting Sun Garrison", description = "Might you be willing to find Anji at the Setting Sun Garrison to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", objectives = "" }
WordHunterWoW_QuestEN[80311] = { title = "Order of the Cloud Serpent", description = "Widing toortles is da best!\n\nBut widing cloud serpents is even better!\n\nThere's some peepos at da Arboweetum who wide cloud serpents and can teach you how!", objectives = "" }
WordHunterWoW_QuestEN[80312] = { title = "Gasping Plea", description = "<A gasping, pathetic-looking fish taken from the corpse of a kobyss flops weakly in your hand. Its beady eye twitches, and you suddenly hear a breathless voice in the recesses of your mind.>\n\nThe water. Take me to the water. Away from these kobyss wretches. Away from the sky.", objectives = "" }
WordHunterWoW_QuestEN[80313] = { title = "Tidal Charms", description = "<When the fish speaks, its lips do not move. You hear its voice in your head.>\n\nNo doubt you have found that your senses cannot be trusted when dealing with the kobyss. A tremendous power, is it not? It is only fair that you show them the power they wield is not theirs alone.\n\nI will show you how to craft a tool to lure and destroy them. You will find their kind carry shards taken from the deep. Bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[80314] = { title = "Voices from the Deep", description = "To deceive the senses of these kobyss is one matter. To know what will captivate them is another. They champ and drool at the thought of devouring your kind. But it is the voices of the deep that transfix them and lower their guard. It's then that you will strike.\n\nSearch their shrines to gain an insight for what these wretches hold sacred. See how they have twisted the bellowing truths that lie below.", objectives = "" }
WordHunterWoW_QuestEN[80315] = { title = "Alluring Offer", description = "It is done. Take this tidal charm, cloak your form in the darkness of the sea, and unmake the kobyss. Their strongest warriors gather and scheme against your kind upon that central island. With the lure, they will not see you for what you are. Use that advantage to become their end.\n\nBut understand, as the kobyss fail to, this is a power you borrow. It belongs to the sea.", objectives = "" }
WordHunterWoW_QuestEN[80316] = { title = "Return to the Sea", description = "I remain weakened by my time so near the searing Light of the surface. I ask that you take me to deeper waters, away from these kobyss, where I can return to my kind.", objectives = "" }
WordHunterWoW_QuestEN[80321] = { title = "Departure", description = "Best if we split up here. I'll guide everyone to safety and see about getting them evacuated.\n\nIn the meantime, you should search for Khadgar. I'm sure he could use your aid as well.\n\nYou'll find another exit further ahead that should lead back to the surface.", objectives = "" }
WordHunterWoW_QuestEN[80334] = { title = "Shattered Spires", description = "With nothing to contain their arcane power, Dalaran's spires are crumbling.\n\nIf we let their energies continue to bleed out unchecked, that power could destabilize and destroy what is left of our forces.\n\nFind Aethas! He will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[80349] = { title = "Time to Return", description = "You'd best be on your way now. That portal should take you back to the village.", objectives = "" }
WordHunterWoW_QuestEN[80378] = { title = "A Light of the Dark", description = "The image of a purple candle, burning with glorious power springs unbidden to your mind as you contemplate the decaying filth before you, followed by a faint whisper echoing through your mind: \"One candle to rule them all, and in its brightness bind them.\"\n\nBring Janky the candlesmith in Gundargaz enough Coagulated Black Blood to forge a most unfortunate candle.", objectives = "" }
WordHunterWoW_QuestEN[80380] = { title = "Cloak and Needle", description = "Once you don your cloak, you will be able to find threads on any enemy.\n\nThe cloak will naturally absorb those threads, permanently increasing your power.\n\nTry collecting a thread from the nearby Infinite Ravagers.", objectives = "" }
WordHunterWoW_QuestEN[80382] = { title = "Eggs in One Basket", description = "<This work order remains unfilled. Aliya Hillhelm would be quite happy if you helped complete the order.>", objectives = "" }
WordHunterWoW_QuestEN[80384] = { title = "A Keg-Stamped Package", description = "<A note, attached to a small and crumpled package, is shoved into your hands by a nondescript figure. Just as quickly, they disappear into the crowd. The letters on the note are scrawled crudely, as if by a dagger dipped in ink.>\n\nHere's yer share of the plunder.\n\nSent the mates to the inn.\n\n<You look around to see if there is anything else on the note. There is a picture of a keg at the bottom.\n\nYou shake the package gently and hear the telltale sound of coins.>", objectives = "" }
WordHunterWoW_QuestEN[80385] = { title = "Last Hurrah: Dragon Isles", description = "You've become quite popular with our allies, {name}!\n\nTo the south the Iskaara Tuskarr need your help with their community feast.\n\nTo the west the Maruuks have requested your aid with their hunts.\n\nTo the north the Obsidian Outcasts request your help reclaiming Dragonbane Keep.\n\nSounds like you have a full day ahead of you! Best of luck.", objectives = "" }
WordHunterWoW_QuestEN[80386] = { title = "Last Hurrah: Zaralek Caverns and Time Rifts", description = "Our allies are once again requesting your aid, {name}.\n\nIn the Zaralek caverns the Dragonscale Expedition needs you to protect their researchers.\n\nWe're also concerned with the Zaqali invasions in the Ohn'ahran Plains and Azure Span.\n\nMeanwhile, the Bronze Dragonflight has asked for you to help them deal with temporal anomalies to the east of Valdrakken.\n\nHurry {name}, time is of the essence.", objectives = "" }
WordHunterWoW_QuestEN[80388] = { title = "Last Hurrah: Emerald Dream", description = "The druids call for aid!\n\nEnergy from the Emerald Dream is spreading across the Dragon Isles, please help them investigate it.\n\nThey also ask you travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom.\n\nSome of the druids also wish for you to plant Dreamseeds in the Emerald Dream.\n\nPlease help them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[80392] = { title = "The Caretaker of Brunwin's Terrace", description = "Greetings, outlander. You must be the problem solver I've heard about! I'm Caretaker Batzvara. I tend to earthen who have gone into stasis, like our friend here.\n\nI often patrol Brunwin's Terrace to honor my fellow earthen with an offering of cinderbrew. Recently, however, I've drawn the attention of a local species of moles. They have a nose for sweets, and greedy claws for all else.\n\nYou look like you can defend yourself. Will you accompany me to pay respect to those who have gone into stasis?", objectives = "" }
WordHunterWoW_QuestEN[80397] = { title = "Sweets Seekers", description = "Earthen cinderbrew is a potent drink. It's dangerous to those who lack our constitution. Even worse, it has a sweet aroma that draws the attention of a vicious species of mole. They'll do anything to get their claws on it!\n\nAs I honor the earthen of Brunwin's Terrace with a sweet libation, my potent potable will draw their attention. If you're anywhere near me, be on your guard, so you can put down any who pop up.", objectives = "" }
WordHunterWoW_QuestEN[80399] = { title = "Rations and Revelations", description = "We found these prisoners fleeing a nearby nerubian military base.\n\nThe circumstances of their escape are... unclear, even to them. As if someone else created the opening they needed to escape.\n\nThey need rest, but we need to find out what happened in there.\n\nFood first. Maybe once they've regained some of their strength, they'll remember something.", objectives = "" }
WordHunterWoW_QuestEN[80400] = { title = "Item Collection [DNT]", description = "Kill Collect", objectives = "" }
WordHunterWoW_QuestEN[80401] = { title = "A Perfect Sponge", description = "Welcome, stalwart colleague, to Shimmermist Falls! It's always damp here--a thriving paradise for green, living things. Unfortunately, it's also the perfect climate for moss to grow on my inert earthen charges. \n\nWe'll need to gather a few supplies for removing the moss. First, we need a sponge to wash their surfaces. It needs to be soft enough to not damage them but strong enough to hold up to an earthen's rough stone skin. \n\nThe caps from the lashrooms down below are perfect!", objectives = "" }
WordHunterWoW_QuestEN[80402] = { title = "Buckets and Blooms", description = "Down among the creeping lashrooms grows an orange flower. When mixed with water, its blooms make a caustic solvent that is perfect for removing moss from earthen skin.\n\nI also left a bucket next to this earthen the last time I was here, which I use to make the solvent. Something seems to have made off with it.\n\nCould I delegate the task of gathering these to you? I'll wait here. The moles from the terrace have given me enough excitement for one day.", objectives = "" }
WordHunterWoW_QuestEN[80404] = { title = "Mossy Earthen", description = "Excellent work gathering everything together. I've mixed the solvent for you. \n\nNow all that's left is to gently clean off our mossy friends down there.", objectives = "" }
WordHunterWoW_QuestEN[80405] = { title = "Too Much Drip", description = "This is Ausgazur. His hand is usually full of a selection of his favorite gems. We don't really know what it's like when we go into stasis, but he wanted to spend his last moments contemplating the natural beauty of Azeroth and her bounty.\n\nI am afraid someone or something has made off with the jewels he usually holds. Let's look around. See if you can find any clues where they may have gone off to.", objectives = "" }
WordHunterWoW_QuestEN[80406] = { title = "Seeking Ausgazur's Gems", description = "So it was kobolds who made off with Ausgazur's gems. I did not realize the Waterworks was under attack. Our timing is lucky for the defenders down below! \n\nWe must get those jewels back! I'll stay here and guard the remaining gems, but I implore you to complete a critical task: go down into the Waterworks and retrieve the rest.", objectives = "" }
WordHunterWoW_QuestEN[80407] = { title = "Glintwick the Gem Grabber", description = "The kobold mentioned Glintwick, did he? It sounds like she's the driving force behind these gem thieves. I'll bet my beard she's got Ausgazur's last gem!\n\nLook for her in the Waterworks and see if she has the final gem. She may also be behind the attack that's happening, so taking her out will help the defenders.", objectives = "" }
WordHunterWoW_QuestEN[80408] = { title = "Shimmermist Falls", description = "West of Gundargaz is another green space - a lovely area with waterfalls and more terraces. My schedule takes me in that direction next, and I would be very glad of your company to help deal with the wildlife there as well. \n\nIf your other duties are not pressing, let us meet there.", objectives = "" }
WordHunterWoW_QuestEN[80434] = { title = "Into the Deeps", description = "Onward and downward it is, then. We'd best follow after Speaker Brinthe and see what state the nerubians have left her home in.\n\nMagni, Dagran, and I will accompany you down in due time. Would you mind roving ahead and making sure there's a warm welcome awaiting us?", objectives = "" }
WordHunterWoW_QuestEN[80442] = { title = "Aid the Sunreavers Onslaught", description = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", objectives = "" }
WordHunterWoW_QuestEN[80443] = { title = "Aid the Kirin Tor Offensive", description = "There will be no victory without bloodshed. Have you brought aid, {class}?", objectives = "" }
WordHunterWoW_QuestEN[80446] = { title = "Looking for Group", description = "There's my favorite champion!\n\nIf you are in need of a mark to hunt, I know a few dungeons worth exploring.", objectives = "" }
WordHunterWoW_QuestEN[80447] = { title = "Looking for More", description = "You think you're tough?\n\nI'll believe it when you take on a real challenge.\n\nDefeat the most powerful foes on Pandaria and we'll see how tough you really are.", objectives = "" }
WordHunterWoW_QuestEN[80448] = { title = "A Fresh Scene", description = "Uh-uh honey, I'm not gonna let you spend all day in stuffy dungeons where no one can see your getup!\n\nPut on your going-out look and let's get you somewhere fresh!", objectives = "" }
WordHunterWoW_QuestEN[80456] = { title = "A Sassy Arathi", description = "I had heard that an Arathi was making trouble in the city. It sounds like he is butting heads with the peacekeepers.\n\nYou've worked with the Arathi before, haven't you? Maybe you'd be able to smooth over any ruffled feathers.", objectives = "" }
WordHunterWoW_QuestEN[80500] = { title = "The Bronzebeard Family", description = "<Moira takes a deep, centering breath.>\n\nWe need to let Brann and my son Dagran know what happened. They're at Dalaran's visitor center.\n\nCould ye go get them for me? Father needs his family right now.", objectives = "" }
WordHunterWoW_QuestEN[80502] = { title = "Don't Cry for Me, Azj-Kahet", description = "<You find a crumpled page of journal paper wrapped around a small key.>\n\nI always suspected Arax'ne was a traditionalist, but I didn't think she'd go this far. I don't know where I'm going, but I just have to get away from her.\n\nTo whoever finds this, it means the worst has come to pass. This key unlocks a chest that contains all my worldly possessions. They are yours.\n\nAll I ask is that you avenge me by slaying Arax'ne.", objectives = "" }
WordHunterWoW_QuestEN[80508] = { title = "Dread in the Den", description = "You kobold friend, yes? Need help. Bad things happening in the Chittering Den. \n\nGlumtooth Gang setting up camp. Cronies of Candle King, want war with earthen.\n\nCan't stop them alone. Meet me at camp.", objectives = "" }
WordHunterWoW_QuestEN[80509] = { title = "A Suit of Slime", description = "Glumtooth Gang no let you into camp looking like that. Need disguise. Make you look like bug, then we walk right in.\n\nFirst, need wax. Plenty here. Take from slime beasts or scrape off hoppers. \n\nThen we stick wax on you. Stick bug bits to wax. Perfect disguise.", objectives = "" }
WordHunterWoW_QuestEN[80510] = { title = "Healing the Headwaters", description = "Glumtooth Gang so wasteful! They leave much scrap in the water. Bad for water. Bad for scrap. Go clean it up.", objectives = "" }
WordHunterWoW_QuestEN[80511] = { title = "Casing the Camp", description = "Now we take you to camp. You see what Boss Whiskerlash do. Put on bug disguise when we close to camp. Let me do talking.", objectives = "" }
WordHunterWoW_QuestEN[80512] = { title = "Beat the Best", description = "If Glumtooth Gang succeed, this earthen first captive of many. We need free him.\n\nHe prize. Every kobold here want fight him. Must earn our place.\n\nYou beat up strong bugs, they think me strong trainer. Then they let you into ring.\n\nMay best bug win.", objectives = "" }
WordHunterWoW_QuestEN[80513] = { title = "Snouty Sabotage", description = "You need good distraction to get earthen out. I need Glumtooth Gang stopped. Have perfect thing for both.\n\nSome fool mix Cinderbrew with candle wax in the Warrens. Candles burn normal at first, then boom. Big boom. Place around camp. Explosions good distraction for escape.\n\nWhile you at it, loosen some bug leashes. Let Glumtooth Gang see how scary bugs are.", objectives = "" }
WordHunterWoW_QuestEN[80514] = { title = "Break out Berrund!", description = "You work good. Now they let you into ring to \"fight\" earthen. You go to ring when ready. Cinder-flash candles could go off any moment.\n\nI head back to camp. Wait for you and earthen there.\n\nYou good one. No get killed.", objectives = "" }
WordHunterWoW_QuestEN[80515] = { title = "Put the Shine On", description = "Hate to admit, but loud earthen right. Boss Whiskerlash have strongest bugs. But everything have weakness.\n\nSpiders afraid of light, and our friend very shiny. If we make him shinier, no spider want to fight.\n\nGlumtooth Gang been capturing candleflies. Free them and rub off some glow dust. We make big earthen big shiny!", objectives = "" }
WordHunterWoW_QuestEN[80516] = { title = "Bump off the Boss", description = "That kobold knows her stuff. Scrit says Boss Whiskerlash has his own cadre of spiders in a cave nearby. Don't worry, I'll lead the charge. \n\nCome on, we've got a boss to take down.", objectives = "" }
WordHunterWoW_QuestEN[80517] = { title = "Back to Where it Began", description = "<Zee-Zee is ready to head back to the Deepforge Golemworks.>", objectives = "" }
WordHunterWoW_QuestEN[80558] = { title = "Nothing Ventured", description = "These niffen have been down here a long time--long enough to build a village and set up trade with the nerubians. Some of them are even able to trade in that big nerubian city!\n\nThe goblins, though? They're from the Venture Company. No wonder General Anub'azal was skeptical of me, if he's used to dealing with them.\n\nWhat are they doing all the way down here? Let's try to learn what led them to this place.", objectives = "" }
WordHunterWoW_QuestEN[80562] = { title = "Blossoming Delight", description = "Few followers of the light would dare to attempt the dish I plan to make. A mix of traditional Imperial spices combined with the forbidden harvest of the nearby fungal blooms.\n\nThis dish will delight the palate and remind one of the adventurous spirit that founded the Hallowfall expedition.\n\nPlease journey to the Mycomancer Cavern nearby and harvest the blooms I require.", objectives = "" }
WordHunterWoW_QuestEN[80563] = { title = "Tool of Attunement", description = "The nerubians must have some means of cleansing themselves after Black Blood exposure. If they did not, they would not have been so successful in their harvesting operation.\n\nIf necessary, I can pick up on the harmony of this world with ease to restore my mind to this reality. But for your sake and Hannan's, we should probably obtain whatever it is they use.\n\nAlthough we can spare the trouble... if you don't mind the threat of forever splitting your consciousness between two realities.", objectives = "" }
WordHunterWoW_QuestEN[80564] = { title = "Field Research", description = "The nerubians are harvesting Black Blood nearby.\n\nIf allowed to persist, the corruption caused by excavating the veins may spread. It will continue until it consumes everything.\n\nI have no intention of sitting and waiting for it to taint the roots. I am trying to learn and understand their methods... so that I may strike at the heart of the operation.\n\nYou're welcome to join me.\n\nIf, of course, you would also prefer your world not to drown in oozing pools of Black Blood.", objectives = "" }
WordHunterWoW_QuestEN[80565] = { title = "Resounding Repercussions", description = "I did not mean for...\n\n<Orweyna's eyes narrow.>\n\nFetch him, {name}. You were exposed to the Black Blood, too. But Hannan took most of it.\n\nHe has entered the Unseeming, his mind shifted to a realm beyond our eyes through exposure to the Black Blood. You may need to join him, however far in he ventured, to retrieve him.\n\nI will activate the nerubian cleansing instrument for when you return.\n\nDo not lose yourself in that altered state.", objectives = "" }
WordHunterWoW_QuestEN[80566] = { title = "Enemies Abound", description = "<Hannan is barely responsive and less corporeal than he should be, lost deeper in the Unseeming than you.>\n\nSome of the canisters exploded... Then the spiders appeared.\n\nKill the--kill the spiders!", objectives = "" }
WordHunterWoW_QuestEN[80567] = { title = "Song of Restoring", description = "<Orweyna looks relieved at the sight of Hannan, but does not seem dissuaded from her task.>\n\nI cannot say I am surprised at what you found in that cave. Nerubians stuck in the Unseeming, trapped in a realm of monsters and madness...\n\nI would pity them, but they sought this out.\n\nYou, however, need to shift back before the influence of the Black Blood becomes too strong on your mind.", objectives = "" }
WordHunterWoW_QuestEN[80568] = { title = "Leave No Trace", description = "I need to go make sure she's all right. What I saw in that cave... If she's more sensitive to this...\n\n<Hannan nearly growls.>\n\nBut she's making a mess out here, drawing attention and leaving a trail leading outsiders right to her! Right to us.\n\nWe're supposed to be subtle. Unseen. Keep to the brush, hide in our other forms as much as possible.\n\nI hate to ask this of you, but can you use my scythe to take care of the evidence while I check on her?", objectives = "" }
WordHunterWoW_QuestEN[80569] = { title = "Harmonious Approach", description = "I know I cannot stop Orweyna from going down there and drawing attention to our presence.\n\nBut... perhaps we could stop word of our presence from spreading.\n\nFind whoever is in charge of this harvest site. And... do what is needed to ensure they can't spread the word.", objectives = "" }
WordHunterWoW_QuestEN[80570] = { title = "Staunch the Flow", description = "Do they even understand what they are doing?\n\n<Orweyna bares her teeth, practically growling.>\n\nDestroy as many of those extractors as you can. Shatter the bulbs, snap the limbs, burn the wreckage.\n\nWe cannot stop them all, not today. But a bit of destruction may temper my rage.", objectives = "" }
WordHunterWoW_QuestEN[80571] = { title = "Decipher the Cacophony", description = "This is far worse than I thought. It's as if they're feeding the corruption. Encouraging it. The dissonance growing louder and louder...\n\n<Orweyna seems shaken, but not deterred.>\n\nI can hardly hear anything else. My head is pounding. I... I need to see how far gone this land truly is.\n\n{name}. Bring me something from the Unseeming.", objectives = "" }
WordHunterWoW_QuestEN[80572] = { title = "Discordant Measures", description = "I cannot stand to look at this any longer. I must act.\n\n{name}. You have survived the Unseeming before. Now we must go there together. I must see it for myself if I am to believe this vile place truly cannot be cleansed.\n\nWe will kill what we can and search for some sliver of hope that we can still restore this land.", objectives = "" }
WordHunterWoW_QuestEN[80576] = { title = "Listener Lost", description = "Blast it all! \n\nBrennok and I were on our way to Shadowvein Point to conduct a recitation ceremony. We were attacked by scorpids. Now the hauler has a scorpid stinger lodged in its gears, and Brennok wandered off.\n\nHe said he was going to stretch his legs while I fixed the hauler, but that was a while ago. I need to get the bot moving again, can you look for him?", objectives = "" }
WordHunterWoW_QuestEN[80577] = { title = "Readying the Recitation", description = "Once a year, Brennok and I take the long road through The Ringing Deeps. \n\nWe stop at each outpost, and Brennok tells the residents a story from their past. One they entrusted to him to remember, even when they forget. \n\nIt's my duty to ready the ceremony site. Would you come with me? I could use the help.", objectives = "" }
WordHunterWoW_QuestEN[80578] = { title = "The Common Costume", description = "I'll slip away after the recitation. It's easy to vanish in a crowd of earthen enjoying a keg of cinderbrew.\n\nHowever, I can't be recognized when I leave town. I don't want anyone to stop me. Or worse, to think I'm abandoning my oath. Better to just disappear.\n\nIf you find me a spare set of Miner's Clothes, I'll be able to get away without being noticed.", objectives = "" }
WordHunterWoW_QuestEN[80592] = { title = "Forge a Pact", description = "Let us renew your Pact.\n\nRemember, you may only enter a Pact with one of the Severed Threads at a time. These contracts are temporary, though, so you will have many opportunities to prove yourself to all three.", objectives = "" }
WordHunterWoW_QuestEN[80593] = { title = "A Sip of Cinder", description = "Now there's one last thing we need. It wouldn't be a proper recitation ceremony without mead. \n\nHowever, Hearthkeeper Zirc tells me the last couple deliveries of cinderbrew haven't arrived. It seems the local flayers in the Rumbling Wastes have a taste for it and raid the shipments.\n\nHere, take a spare keg. See what you can recover from the flayers.", objectives = "" }
WordHunterWoW_QuestEN[80670] = { title = "Eyes of the Weaver", description = "The Weaver's many eyes lurk throughout the city, learning as much as they can about Ansurek's machinations.\n\nStill, intelligence enough will not be sufficient to turn the tide against the Sureki forces. The Weaver requires someone willing to get their hands dirty.\n\nLucky you, I suppose.", objectives = "" }
WordHunterWoW_QuestEN[80671] = { title = "Blade of the General", description = "Even now, General Anub'azal's forces work tirelessly to ensure the security of Azj-Kahet.\n\nAnsurek's reach extends to every corner of her domain. The General seeks to undermine her military authority. If we stretch her resources thin, then we may find new opportunities to strike.", objectives = "" }
WordHunterWoW_QuestEN[80672] = { title = "Hand of the Vizier", description = "The Vizier works even now to spread our conspiracy's influence amongst the well-to-do of Azj-Kahet's elite. Given his position, though, he can offer little in the way of direct support.\n\nThat is where you come in. Your growing reputation precedes you; you can move in ways that the Vizier cannot. Just take care not to get eaten, hrm?", objectives = "" }
WordHunterWoW_QuestEN[80673] = { title = "Runway Scare-a-way", description = "'Lo there.\n\nMe and Mags are generally in charge of clearing the sky in this area during our Lamplighting route. If we don't cull the moths in the area, they start spreading up towards the skydocks and start laying eggs in the machinery of our ships.\n\nUnfortunately we're not as spry as we used to be. Could you lend a helping hand? They're pretty frail so they'll squish easily to any high velocity flight. Or you could just smack 'em the old-fashioned way.", objectives = "" }
WordHunterWoW_QuestEN[80676] = { title = "Defragmenting Memory", description = "My oath is to be a compiler. I collect and tell the stories of our people.\n\n<Brennok sighs.>\n\nIs there wisdom in stories told by someone who never lived them? I've never had an adventure. I was afraid to overwrite the stories entrusted to me.\n\nSo I started transcribing them into a book I hid here. Each time we returned to Shadowvein Point, I added more.\n\nI was going to leave and pass on the book, but scorpids ransacked it. Please, find the missing pages before they stuff them into their nests.", objectives = "" }
WordHunterWoW_QuestEN[80677] = { title = "Torching Lights", description = "No matter how many moths we swat, if we don't take care of the eggs they'll just continue to be a problem. \n\nTake this firearm, use it to torch some of the eggs on the top of the mire's canopy.", objectives = "" }
WordHunterWoW_QuestEN[80678] = { title = "Time Lost", description = "Now that the job's done -- one thing I've always done on this route is muck around for some of the valuables that fall from the docks. As things get moved onto ships small items can fall off. Sometimes people chuck 'em for luck or in rage, and the like.\n\nBut some of those items have memories in 'em. Things so precious that losing it might as well be losing part of your heart. If you could help me look I'd be grateful.", objectives = "" }
WordHunterWoW_QuestEN[80679] = { title = "Stuffed Lynx Toy", description = "That item in your pack looks familiar...", objectives = "" }
WordHunterWoW_QuestEN[80680] = { title = "Tarnished Compass", description = "<The name on the compass from the Stagnant Mire matches one engraved in the epitaph of the community gravestone.>", objectives = "" }
WordHunterWoW_QuestEN[80681] = { title = "Broken Bracelet", description = "What is it you have there?", objectives = "" }
WordHunterWoW_QuestEN[80682] = { title = "One Last Story", description = "Well, it's time. I'll be holding the recitation at the mine entrance. I'll see you there, though don't feel obligated to stay the whole time.\n\nI'll leave my book for Haimaz to find. She'll take care of it.\n\nAfter the ceremony, I would like to say goodbye properly. Meet me by the bridge outside of town. I'll head there after the recitation.", objectives = "" }
WordHunterWoW_QuestEN[80684] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[80685] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[80689] = { title = "Tending to Ausgazur", description = "Assigned tasks complete! I'll check back on these folks on my next scheduled patrol.\n\nThere is one more earthen I must tend to today. He was... he is very special to me.\n\nYou've been an especially considerate colleague, so I'd like for you to see him. Let us travel west a bit, closer to the falls.", objectives = "" }
WordHunterWoW_QuestEN[81469] = { title = "charlie's test quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[81510] = { title = "Ship It!", description = "What a haul! I was able tae give a bit of what we found tae Dagran so he could finish off one of his projects. He should be here any minute. \n\nAh, I can't hold back. Surprise! It's a gift tae help you get around.", objectives = "" }
WordHunterWoW_QuestEN[81514] = { title = "Bountiful Delves", description = "We're going tae need lots of resources to fight off Xal'atath. Lucky for you, we've uncovered a source!\n\nSome delves we've found are \"bountiful\" on account of the baddies there hoardin' more treasure. This treasure can only be unlocked with special keys found throughout Khaz Algar.\n\nKeys and key fragments can be found all about the world. Hunt them down and dive into a bountiful delve!", objectives = "" }
WordHunterWoW_QuestEN[81556] = { title = "Foreign Fog", description = "Pleasure to meet you, adventurer. I wonder if you might be willing to help me with some research?\n\nI'm sure you've noticed the fog beasts that have recently started encroaching upon this area. \n\nPeople see them as a bad omen, they always seem to show up during periods of ecological imbalance. I disagree with this assertion. \n\nStill as an expert in all vapor-based magics, I've been hired to find out where they're coming from so they can be cut off at the source.", objectives = "" }
WordHunterWoW_QuestEN[81557] = { title = "Fog Tags", description = "While I analyze these fog samples, I have another task for you.\n\nMy employers have asked me to figure out where these fog beasts are coming from. I've developed these trackers. If you could, please attach them to an assortment of fog beasts.   \n\nYou'll have to get close, so... be careful. Hopefully they don't mind it too much!", objectives = "" }
WordHunterWoW_QuestEN[81558] = { title = "Unnatural Predators", description = "It would be no use tagging fog beasts to study if they all were to die, would it? \n\nCould you clear out some of the aggressive deepflayers that have flocked to feast on the fog beasts?\n\nThey'll ruin my data if left unchecked, I'm sure of it.", objectives = "" }
WordHunterWoW_QuestEN[81559] = { title = "Fog Follower", description = "With the trackers attached, we should be able to find out where the fog beasts are coming from. The trackers leave a residue in the air. It's invisible to the naked eye, but I can use the mists to reveal it in places where there's a high enough concentration.\n\nTheoretically, this should lead us to the places they most frequent. Maybe a nest! That I'll then have to report to my employer... hm.\n\nAnyway. Let's see what we can find.", objectives = "" }
WordHunterWoW_QuestEN[81560] = { title = "Winter's Presents", description = "I hear Greatfather Winter has put presents for everyone under the tree in Ironforge.\n\nYou should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.", objectives = "" }
WordHunterWoW_QuestEN[81561] = { title = "Winter's Presents", description = "I hear Great-father Winter has put presents for everyone under the tree in Orgrimmar.\n\nYou should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.", objectives = "" }
WordHunterWoW_QuestEN[81564] = { title = "The Story of Noodles", description = "Ah, being here again makes me hungry. Have I ever told you about the time I learned to cook from Sungshin Ironpaw?\n\nPerhaps you can experience it for yourself. Say the word and I will take you to a version of this timeline where you--yes YOU--ran your own noodle stand!\n\nIt all began with the Lin family's secret recipe...", objectives = "" }
WordHunterWoW_QuestEN[81565] = { title = "Another Round of Noodles", description = "Back again for more noodles?\n\nVery well, say the word and I will take you back to a version of history where you ran your own noodle stand.", objectives = "" }
WordHunterWoW_QuestEN[81574] = { title = "Sporadic Growth", description = "Fungal growths are still spreading unchecked from the nearby Mycomancers' cavern. The latest surge has sent all my recruits fleeing in fear.\n\nI urgently need your skills in eliminating one troublesome fungal growth.\n\nTake my Patrol Torch and eradicate Gloomsprout and the surrounding growths that sprouts from it. The torch should handle the smaller stuff, but Gloomsprout will require a more direct approach", objectives = "" }
WordHunterWoW_QuestEN[81595] = { title = "Seasonal Start", description = "We've uncovered loads of new treasures tae find in delves! \n\nThere's no time tae wait. Let's get ye set up with the basics so you can get out there!", objectives = "" }
WordHunterWoW_QuestEN[81596] = { title = "Delve Hunter", description = "A few of our explorer's have come back battered and bruised from delves. They speak of a terrible monster called Zekvir. \n\nPerhaps you've heard of this creature? Allow me to tell you more of what we've learned.", objectives = "" }
WordHunterWoW_QuestEN[81609] = { title = "What About the Children?", description = "Greetings {name}. As I'm sure you're aware, there are many children across Azeroth without families to look after them. Children's week is a time to recognize their plight and give hope to those children. Will you go to them?", objectives = "" }
WordHunterWoW_QuestEN[81610] = { title = "What About the Children?", description = "Greetings {name}. As I'm sure you're aware, there are many children across Azeroth without families to look after them. Children's week is a time to recognize their plight and give hope to those children. Will you go to them?", objectives = "" }
WordHunterWoW_QuestEN[81613] = { title = "Let's Not Worry Her", description = "Right, we better get back to Haimaz before she gets suspicious.\n\nPlease, don't tell her about any of this. Her duty is to guide and guard me in my role as compiler. \n\nIf she knew I was planning to leave... I don't know what she would do.", objectives = "" }
WordHunterWoW_QuestEN[81632] = { title = "Lizard Looters", description = "Despite the punishment of our posting here, life isn't entirely unpleasant. Captain Lancekat left us a generous supply of provisions. \n\nWell, at least she did until recently. A sizable lizard has made off with our camp supplies!\n\nCould you recover our camp supplies and deal with the pilfering thief?", objectives = "" }
WordHunterWoW_QuestEN[81638] = { title = "Home Is Where the Hearthstone Is", description = "", objectives = "" }
WordHunterWoW_QuestEN[81640] = { title = "Tenir and the Order of Night", description = "<A script for an epic stage play. Stage Manager Huberta on the Isle of Dorn may have interest in this.>", objectives = "" }
WordHunterWoW_QuestEN[81651] = { title = "Delver's Guide to Delves", description = "Greetings! Up for going through some delves in the area?", objectives = "" }
WordHunterWoW_QuestEN[81654] = { title = "The Harbinger", description = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger...\n\nLet us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", objectives = "" }
WordHunterWoW_QuestEN[81655] = { title = "Juicy Krolusk Meat", description = "Greetings! I am Kagfritha. I was once a site supervisor for operations in the Rumbling Wastes to the south of here, but time has taken its toll on our enterprise and we had to abandon the area. \n\nIt's high time we got things back in working order down there, but while we were gone some unsavory creatures moved in. I have a plan for dealing with the worst of the bunch, but first we need some bait. \n\nIf you're here to help, go hunt some of those dirt diving krolusks and bring me back their meat.", objectives = "" }
WordHunterWoW_QuestEN[81661] = { title = "To Mourning Rise", description = "Greetings, outlander. My name is Urtago, and I am Caretaker Korgran's apprentice at the Mourning Rise memorial site.\n\nThe mischievous Candlelit Kobolds have overrun Mourning Rise, and we seek assistance. Would you meet me at Fallside Outpost? It is just to the north of here. I will be able to tell you more once you arrive.", objectives = "" }
WordHunterWoW_QuestEN[81667] = { title = "The Upstart", description = "You are the Weaver's \"untethered third party?\" Excellent. You are the perfect catalyst for a coup.\n\nThe City of Threads has sent an upstart here to seize control of Rak-Ahat. \n\nThe arrival of Ren'khat has everything all tangled up. He postures himself as some kind of silk visionary from the city, and he challenges the authority of the Overspinner who refused to relinquish control. \n\nBad for the Overspinner, good for us. Speak with Ren'khat and feed his ambition. Help him against the Overspinner.", objectives = "" }
WordHunterWoW_QuestEN[81668] = { title = "Measure Once, Cut Thrice", description = "I was promised an important, glamorous, enviable position of power when I left the city for Rak-Ahat.\n\nThis warehouse job? Neither important nor enviable. And certainly not glamorous.\n\nGrand Overspinner Antourix has been at this for far too long. She doesn't understand my vision. All she wants are drones that do exactly what she wants, how she wants it.\n\nTake out her most loyal workers. We'll see how tough she is on her own once I take over the dyeworks.", objectives = "" }
WordHunterWoW_QuestEN[81669] = { title = "Sticks and Bones", description = "While the krolusks like to attack from beneath, the Rumbling Waste also plays host to a predator who prefers to swoop down from above. Deepsflayers have built nests on the peaks and ridges around the Waste. \n\nDestroy their nests and show them that the Waste is no welcoming home.", objectives = "" }
WordHunterWoW_QuestEN[81671] = { title = "UNUSED [DNT]", description = "<This is a new hidden message... that doesn't come from the Upstart! This could only come from the Head Cutter's office... maybe she's the one sending the messages after all?>", objectives = "" }
WordHunterWoW_QuestEN[81672] = { title = "In a Pinch", description = "I suppose I should come clean and tell you why I had you gather that meat.\n\nTruth is, there's a horrible beast who lives down in the Wastes. A monster who feeds on the unwary and whose pincers can snap through stone and bone like a knife through warm butter. \n\nIts name is Smaragthr, and the foul thing is the reason I have but one eye and my gems are cracked. I am no match for it, but you... you could enact my vengeance. \n\nKill Smaragthr so the Wastes can be free!", objectives = "" }
WordHunterWoW_QuestEN[81673] = { title = "Honor Your Efforts", description = "Though my rank is humble, I bestow upon you this honor. A tinderbox, signifying your friendship with our expedition and your esteemed status in Hallowfall. \n\nShould you fall in battle, your tinderbox shall be given a place of honor among the other great heroes who died defending this land.\n\nPlease accept this honor.", objectives = "" }
WordHunterWoW_QuestEN[81683] = { title = "Spring Collection", description = "That maggot Ren'khat wants my position, hm? He's welcome to try and take it.\n\nAll the runoff from our operation flows into the spring below Rak-Ahat. Decades of mordants, catalysts, and alchemical concoctions have coalesced into something quite... potent.\n\nDon't fuss about the side effects. Just bring me a good variety of dyestuffs and I'll brew up colors that will have you growing extra pairs of legs.", objectives = "" }
WordHunterWoW_QuestEN[81685] = { title = "Azj-Kahet's Next Top Dyemaster", description = "Ren'khat and the Overspinner are fighting pincer-and-claw. Inside the spinneret. With no witnesses.\n\nWe have a unique opportunity here. If they took one another out... well, with Antourix's favorites dispatched and the whole of Rak-Ahat in disarray, the next best authority would be the caravan coordinator. Me.\n\nI don't love being in the spotlight, but it would be very beneficial to our secret-smuggling operation if those two didn't make it out of the dyeworks.", objectives = "" }
WordHunterWoW_QuestEN[81686] = { title = "Subterfuge in Silk", description = "I'm expecting a shipment of silk. That it hasn't arrived worries me.\n\nMost silk in Azj-Kahet, from the finest veils to the strongest warsilk, comes from Rak-Ahat. It makes the place a convenient nexus of information.\n\nOne of my agents smuggles military secrets woven into the silk itself. Recently, she has reported a power struggle emerging in Rak-Ahat... and even more recently, she has reported nothing at all.\n\nMeet with her and ensure no more delays.", objectives = "" }
WordHunterWoW_QuestEN[81687] = { title = "I Expect You To Dye", description = "I thought playing them against each other would give me some cover, but it's plunged all of Rak-Ahat into chaos! This could jeopardize our whole operation!\n\nYou heard what Antourix said. She already augmented the dyebaths with all of those reagents you collected. I don't know what they'll do, but if she was planning on using them against Ren'khat... there's no reason you couldn't use them to take out both of their goons.\n\nTest out those dyebaths, and clear out the dyeworks!", objectives = "" }
WordHunterWoW_QuestEN[81688] = { title = "That's All", description = "It will be interesting to see how all this unfolds... but knowing the Weaver, I'm sure she has some strings to pull to make it go her way.\n\nThis is the secret I was trying to pass to her when things started heating up. Why don't you deliver it to her, as a sign of a job well done?\n\nI'm sure she'll be pleased to know that she continues to have a set of eyes in Rak-Ahat.", objectives = "" }
WordHunterWoW_QuestEN[81689] = { title = "Orientation: Gundargaz", description = "Our new kobold friends have been moving into Gundargaz. They've also been gathering odds and ends from around the Ringing Deeps.\n\nYou should check in with the Quartermaster! Go have a look at what they've collected. Then we can talk about what we're doing next. \n\nI heard Anduin's around here somewhere. I suspect he has some plans for Hallowfall. We need all the allies we can get against the nerubians.", objectives = "" }
WordHunterWoW_QuestEN[81690] = { title = "The Light at the End of the Tunnel", description = "I've never seen shadows this deep. This... vicious. \n\nIt almost feels like they're reaching for us. \n\n<Faerin shudders.>\n\nWe can't stay here.", objectives = "" }
WordHunterWoW_QuestEN[81692] = { title = "The Flame Within", description = "When sparked, a tinderbox creates a flame that embodies the essence of its bearer's life journey. It is a reflection of your strength and inner spirit.\n\nIn your travels, you have met many who could help us fashion a tinderbox capable of igniting a flame befitting your formidable spirit.\n\nSeek the assistance of Speaker Kuldas in Gundargaz. The earthen's knowledge will help create a more powerful tinderbox.", objectives = "" }
WordHunterWoW_QuestEN[81693] = { title = "Desperately Seeking Skorthuz", description = "Eh? Who are you? Oh that's right, I heard that there were new folk about.\n\nSay, are you heading north? If so, keep an eye out for my friend, Skorthuz, will you? The laggard was due back an hour ago but is nowhere to be seen. I heard he was heading towards the Chittering Den for some awful reason. \n\nIf you see him, tell him to hurry up and get back here or I'm drinking alone!", objectives = "" }
WordHunterWoW_QuestEN[81696] = { title = "Report to the Trading Post (D)", description = "Quest Description", objectives = "" }
WordHunterWoW_QuestEN[81712] = { title = "Lisky Business", description = "Hrandaz is going to have to wait. My beloved Lisky is missing! She went into this cave and hasn't come out. I think whatever's making that terrible stench drew her attention. \n\nPlease, go in and find my Lisky? She hasn't drawn the attention of the horrid creatures inside yet, but it's only a matter of time!", objectives = "" }
WordHunterWoW_QuestEN[81713] = { title = "Oozemodious", description = "I tried to get Lisky back myself, but she ran to the far end of the cave. The whole thing is full of disgusting masses of worms. \n\nAs if they aren't bad enough, down the back there's a creature so vile and slimy and oozy that I ran for my life!\n\nNo, I am not proud of leaving Lisky behind. I was just about to work up the courage to get back in there when you arrived. While you're looking for Lisky, you should dispose of those gross things in there! I'm pretty sure they're multiplying!", objectives = "" }
WordHunterWoW_QuestEN[81714] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81715] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81717] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81718] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81719] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81720] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81721] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81722] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81723] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81724] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81725] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81726] = { title = "Report to the Trading Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[81751] = { title = "Fire and Gemstone", description = "What's this? A tinderbox? \n\nI've heard tell of these Arathi contraptions, but have never held one in my hands. It's smaller than I would have thought...\n\nUpgraded, you say? Ha! We can do that. The next time we're Awakening the Machine, keep an eye out for an Awakened Cog and Ringing Gemstone.", objectives = "" }
WordHunterWoW_QuestEN[81797] = { title = "Targeted Recon", description = "If you've spent much time in Hallowfall, no doubt by now you've run across the foul magic of the kobyss. Reports that their illusions have been evolving are fiercely debated within the Arathi Army.\n\nYour outside perspective is just what I'm looking for. Venture to the Sunless Strand, slay a few of their illusory assassins, and then report your findings. You'll likely find them hiding in the shadows.", objectives = "" }
WordHunterWoW_QuestEN[81798] = { title = "Return to Moira", description = "Speaker Brinthe's impulsiveness is getting the better of her. \n\nYou'd best return to your comrades and let them know of her intentions!", objectives = "" }
WordHunterWoW_QuestEN[81869] = { title = "Can Catch More Fires with Honey", description = "Crafting with flame demands a fuel that burns pure and has sustainable power. Among these, the honey created by Cinderwold bees stands out! A source of elemental fire, organic and untainted.\n\nI've longed for a supply of this honey, yet never had the chance to procure it. \n\nTake my harvesting device and gather a quantity for our purpose. We shall infuse it into your tinderbox. Exercise caution, for some of the earthen revere these bees as sacred creatures.", objectives = "" }
WordHunterWoW_QuestEN[81886] = { title = "For the Alliance", description = "For the first time in our history, the outside world is ours to explore and experience.\n\nAn off-island faction known as the Alliance came to the aid of our kin. Valiant and wise, the stalwart Alliance has extended an open hand to our people.\n\nWill you be among the first to accept and visit their lands, learn their histories and walk amongst their people?\n\nIf that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", objectives = "" }
WordHunterWoW_QuestEN[81887] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who appreciates fine stonework! We have many impressive stone buildings and walls.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "" }
WordHunterWoW_QuestEN[81888] = { title = "For the Horde", description = "For the first time in our history, the outside world is ours to explore and experience.\n\nAn off-island faction known as the Horde came to the aid of our kin. Spiritual and mighty, the honorable Horde has opened their hand to our people.\n\nWill you be among the first to go where no earthen has ever gone? To walk their lands, hear their songs and learn from their people?\n\nIf that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", objectives = "" }
WordHunterWoW_QuestEN[81889] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "" }
WordHunterWoW_QuestEN[81890] = { title = "Unfulfilled Requests", description = "I have heard the citizens of the Silken Ward are having trouble with a group of Ascended called the Pale Weavelashers.\n\nThe new ward is supposed to be a fresh start for citizens of the capital, at least that is the way the Queen tells it. In actuality it is a way for her to tighten her grip on those she distrust. \n\nMeet with my assistant Sum'latha. I sent her there ahead of time to gather information. She can fill you in on any details.", objectives = "" }
WordHunterWoW_QuestEN[81896] = { title = "New and Improved", description = "I've completed the modifications. I must say, this is some of my finest work! \n\nDespite its modest design, a bit of cog grease and elbow dust has transformed it into a device that even the surliest of the flame worshippers could appreciate.\n\nIf any of them want to know how it's done, send them my way.", objectives = "" }
WordHunterWoW_QuestEN[81906] = { title = "Whispers from the Web", description = "Hey! Hey!\n\n<The girl waves her arms to get your attention, a scrap of paper clutched in one hand.> \n\nYou won't believe me, but I found the cutest, fuzziest puppy! With a bell! Around its neck!\n\nIt gave me this to give to you. Take it, I gotta go catch that puppy!\n\n<The missive is written in elegant script, calling you to Azj-Kahet.>", objectives = "" }
WordHunterWoW_QuestEN[81908] = { title = "A Flame in the Dark", description = "Contained within the Underkeep lies a tinderbox, once belonging to the late Aelric Leid.\n\nThis item reeks of powerful, corruptive energy. Its close proximity has leeched out to touch many nerubians.\n\nYour task is to retrieve that box and deliver it to me. To be safe, gather any tinderboxes you may find--we'll destroy them all, just in case.", objectives = "" }
WordHunterWoW_QuestEN[81909] = { title = "Absolute Power", description = "The dark allure of this item surpasses my initial expectations. I can sense a surge of power coursing through me. \n\nWe must delve deeper into its mysteries.\n\nHowever, it is unwise to discuss this matter openly. Follow me inside, where we may deliberate further.", objectives = "" }
WordHunterWoW_QuestEN[81910] = { title = "A Great Responsibility", description = "To witness such corruption is deeply unsettling. \n\nDespite the dark energies intertwined with this tinderbox, there remains a flicker of the Sacred Flame, struggling to escape. I will not destroy that flicker, champion. \n\nYet I dare not hold onto it any longer. \n\nPerhaps your purity of spirit can withstand the darkness it holds. Please, {name}, carry it with you. Protect that small spark of purity, and help it break free of the dark magic that ensnares it.", objectives = "" }
WordHunterWoW_QuestEN[81912] = { title = "Flight Training 102", description = "Dunnae think I had nae noticed those rooks spittin' lightnin'. Sure beats tossin' hammers. But it won't mean nothin' if the Stormriders can't hit what they're fightin'.\n\nLet's test their aim. Got some gnomish contraptions here that'll project easy targets for practice. Take Shraubendre back out there an' show them how it's done!", objectives = "" }
WordHunterWoW_QuestEN[81913] = { title = "Flight Training 103", description = "These recruits seem tae be up for a challenge. Let's find them somethin' with a little bite!\n\nI saw a poor giant just off shore bein' pestered by a swarm of flying devils. Let's see if these rooks can shoot the wings off 'em an' provide some relief.\n\nYou and Shraubendre are settin' a good example for the rest. Keep it up!", objectives = "" }
WordHunterWoW_QuestEN[81914] = { title = "Dhar Oztan", description = "I love the stormrooks. Taking care of them was my directive, so they're all I've ever known. But even so, there are questions about them that even I don't have answers to.\n\nBaelgrim--Stormward Baelgrim--he was the expert. I'd pester him about them at every opportunity. And he shared what he could.\n\nHe told me once about summoning rooks at Dhar Oztan. It's an old Stormrider outpost that predates the Stormperch. If you want to know more about stormrooks, that's where we need to go.", objectives = "" }
WordHunterWoW_QuestEN[81915] = { title = "Home to Roost", description = "You've already done us a great service here, {name}. We will carry on by the example you have set.\n\nYou should return to Dhar Oztan and see to these new Stormriders you've recruited. They will undoubtedly benefit from the same diligence you have shown here.\n\nAnd, you can get away from these two and their posturing. I envy you, {name}...", objectives = "" }
WordHunterWoW_QuestEN[81928] = { title = "The Voice of the People", description = "As you might have heard, things haven't gone as intended for the citizens of the Silken Ward. The Pale Weavelashers have been keeping a tight grasp on the citizens. \n\nI wasn't able to find much before an Ascended kicked me out for snooping around. You are a fresh face, go around the Silken Ward and speak to the citizens, see if you can find a way to help them.\n\nAlso seek out Alchemist Talbax. I heard his name spoken a few times. He could be a useful contact.", objectives = "" }
WordHunterWoW_QuestEN[81929] = { title = "Here's the Plan", description = "{name}, the time has come to deal with the nerubian army. General Zev'kall is massing a sizeable force to the east. He intends to breach the wall and invade Hallowfall. There isn't much time.\n\nWe do not have the strength for an all-out assault. To that end, the Weaver has sent Gazlowe here to assist us. I'm willing to do what it takes to save my people.\n\nAnd as fate would have it, I have a personal matter to attend to while we are there.", objectives = "" }
WordHunterWoW_QuestEN[81930] = { title = "The War Within", description = "People are experiencing visions of a \"Radiant Song\" all across Azeroth. We have reason to believe it's a warning of some kind.\n\nMeet me in Silithus. Perhaps Azeroth's Speaker can shed some light on what this warning might mean.", objectives = "" }
WordHunterWoW_QuestEN[81945] = { title = "To Arathi's End", description = "We will regroup on the outskirts of Arathi's End to the east.\n\nTheir forces are nearly ready and there isn't much time, {name}.", objectives = "" }
WordHunterWoW_QuestEN[81950] = { title = "BOOM Treats!", description = "If we're gonna stop this invasion, we need to take out their big guns. In this case, big guns equals ballistae.\n\nRemember how I had ya pick up them Betelsnax? Yeah, I didn't do that for no good reason. See, the nerubians here have their beetles haul their bombs. And those haulers love them some snacks. I mean, who doesn't?\n\nYou place the snacks next to a ballista, then a bomb beetle walks up, and BOOM!", objectives = "" }
WordHunterWoW_QuestEN[81959] = { title = "Collecting a Concoction", description = "The Pale Weavelashers did indeed throw my alchemical supply down the cliffside. The potions will give the citizens of the Silken Ward the edge they need to rise up.\n\nI need someone to go down the Whispering Cliffs and collect any bottles that haven't broken open. I would go myself but the kobyss have made the area a hunting ground and I'm no fighter.\n\nThis would be a simple task for one such as yourself, eh?", objectives = "" }
WordHunterWoW_QuestEN[81962] = { title = "A Nudge in the Right Direction", description = "Wonderful, wonderful! Now that we have recovered my Brightshade Potions, I want you to go around the Silken Ward and show them off!\n\nThis will draw the ire of the Pale Weavelashers, I'm sure, but I want to show the populace that we don't need to live under their thumb. With a little aggressive motivation we can strike out on our own.\n\nYes, yes, this will do! Go around the Silken Ward and kill Pale Weavelashers. My potions will provide an extra kick the citizens will certainly love.", objectives = "" }
WordHunterWoW_QuestEN[81963] = { title = "The Fruits of Our Labor", description = "You put on quite the show, yes? The orders are already coming in. The citizens can't wait to get their mandibles on the potions.\n\nI have one final task for you. I want you to take these latest orders and deliver them. You will accept, yes? \n\nThe citizens are stirring. Now is the time to show the Pale Weavelashers what we can do. If any try and stop you, you know what to do.", objectives = "" }
WordHunterWoW_QuestEN[81964] = { title = "The Blacksmith's Fate", description = "While we're here, I must find out what happened to my old friend, Ryton Blackholme. He was Hallowfall's finest blacksmith--and he was taken in a surprise nerubian attack. I could not save him.\n\nI searched for him, but found nothing except for his bloodied helm. I'd given up hope. But recently, I heard rumor about a blacksmith from a survivor who'd been pulled down off the Aegis Wall.\n\nCould it be Ryton? Will you help me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[81965] = { title = "Invasion Disruption", description = "While we cannot eliminate the nerubian threat here, we can disrupt their invasion plans.\n\nThere are any number of opportunities to accomplish our goal. Let's see what kind of damage we can do.", objectives = "" }
WordHunterWoW_QuestEN[81966] = { title = "Slept Like a Rock", description = "Champion, Da's awake. Please return to Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[81969] = { title = "An End to the End", description = "I want to honor my friend. But first, we need to deal the killing blow to this Light-forsaken place.\n\nIt's known that General Zev'kall has been overseeing the creation of a monstrosity... a void-corrupted, malformed nerubian. The scouting report pinpointed the location at the top of the canyon.\n\nWe're going to deprive him of his horrific pet. That should put an end to his plans to invade Hallowfall. At least for a little while longer.", objectives = "" }
WordHunterWoW_QuestEN[81976] = { title = "Bazaar, Isn't It?", description = "", objectives = "" }
WordHunterWoW_QuestEN[81984] = { title = "Push Back the Dark", description = "Now that you're done with the level up campaign, you can help test the max level faction feature for Hallowfall, Push Back the Dark!\n\nOnce you accept my gossip, you will be teleported to a farm in desperate need of help. It is falling to the darkness, and could use your help putting this to rights again. Relight the keyflames and help the farmers... if you dare!\n\n(Accepting the gossip will level you to 80 and teleport you.)", objectives = "" }
WordHunterWoW_QuestEN[81990] = { title = "The Light's Call", description = "Attention, residents of Hallowfall!\n\nUrgent assistance is needed to reclaim the shadowed outskirts.\n\nAs darkness grips countless family farms, your aid is needed to ignite the sacred flame and restore safety to our lands.", objectives = "" }
WordHunterWoW_QuestEN[81993] = { title = "The Stormrider's Bond", description = "This beauty is no ordinary gryphon. It's got the storm within it. I've been trying all day tae calm it down.\n\nIt reminds me of an ol' Wildhammer myth. Stormrooks, they were called. Only able to be bonded by gryphon riders of great renown.\n\nIf we can show ye got the spirit of the storm, maybe it'll open up tae ye. Try proving yerself in battle.", objectives = "" }
WordHunterWoW_QuestEN[81994] = { title = "A Sacred Connection", description = "Aye, the stormrook is beginning to take a liking to us. But the bond between rider and gryphon is forged over many trials.\n\nYe may have the spirit of the storm, but let's show how ye mastered it. Time to really prove yer mettle in battle.", objectives = "" }
WordHunterWoW_QuestEN[81999] = { title = "New Home, New Candle!", description = "Janky hears there are giant fire bees on surface.\n\nFire bees make fire beeswax, yes? What if make candle from fire bee wax? What that be like?\n\nJanky must know!", objectives = "" }
WordHunterWoW_QuestEN[82007] = { title = "Tale of Tails", description = "The newborn lynx have wandered off again!\n\nThose rascally cats are always up to mischief, darting off without a care. With Peevish missing and only Vesper and I to hold this position, your assistance would be a boon!\n\nI reckon those pesky felines are somewhere nearby. See if you can bring them back.\n\nI would use a light and search the cave, the spider-infested area to the south, and the coast to the north.", objectives = "" }
WordHunterWoW_QuestEN[82080] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you are timed and have a LOT more braziers to hit.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[82087] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nStand near the bonfire and you'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers, then come back here... for your next lesson.", objectives = "" }
WordHunterWoW_QuestEN[82105] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nAs you approach the bonfire you'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers then come back here... for your next lesson.", objectives = "" }
WordHunterWoW_QuestEN[82109] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[82121] = { title = "Demand Satisfaction", description = "We have worked together for some time now, {name}. I hope you have come to respect my vision as it pertains to the art of warfare. There are, as ever, rules that must be followed. Lines that must not be crossed.\n\nZev'kall has to die, and I have to be the one to do it. Every day that Ascended ruffian tramples upon the ideals of war tarnishes the legacy of our kingdom.\n\nPlease, do this last thing for me. Travel to the enemy stronghold and plant this flag on its steps. We will do this the correct way.", objectives = "" }
WordHunterWoW_QuestEN[82122] = { title = "Duel of the Fates", description = "I am no hapless rube, {name}. I do not expect Zev'kall to honor the nature of this challenge in even the most nominal sense.\n\nWe are in the enemy's fortress, and we are surrounded by his teeming sycophants. There will be interference.\n\nI have two orders for you, soldier. First, you will ward off any malcontents who wish to interrupt the duel. Second and more importantly, you will bring neither sword nor spell to bear against Zev'kall himself.\n\nHe will fall by my claws.", objectives = "" }
WordHunterWoW_QuestEN[82123] = { title = "The General's Conviction", description = "<Anub'azal retches roughly. Ichor spews from his disjointed maw.>\n\nMy cohort's obligation to the Severed Threads yet remains. You would do well to report what happened here to the Weaver. Vexing as she is, she will have some idea of how to proceed from here.", objectives = "" }
WordHunterWoW_QuestEN[82124] = { title = "The Beginning of the End", description = "Queen Ansurek has been busy since the assassination attempt. Her grip is tightening on Azj-Kahet and her ever loyal nobles attend to her darkest whims. \n\nOn behest of the Queen, her two most loyal nobles Skeinspinner Takazj and Anub'arash, have locked down the Umbral Bazaar. \n\nTakazj's insufferable propaganda machinations and Anub'arash's increased military presence have painted a clear picture, ascend or die.\n\nI need you to go to the Umbral Bazaar and disrupt their hold.", objectives = "" }
WordHunterWoW_QuestEN[82125] = { title = "A Spy Like Us", description = "Distressing news comes from the Burrows, a sinister plan is unfolding in the gutters below. Citizens of the ward have been disappearing at an alarming rate. \n\nSkeinspinner Takazj and Anub'arash have all the subtlety of a hammer. I doubt it is their work. This is the hand of someone more subtle.\n\nI have a contact in the Burrows. His name is Gut'usul. Meet with him in the Burrows and find out what is going on down below.", objectives = "" }
WordHunterWoW_QuestEN[82126] = { title = "Defense of the People", description = "The Vizier no doubt filled you in on some of the details. Citizens in the Burrows are missing, that much you know. \n\nBut whispers on the wind tell a bigger story. Our citizens are being taken to the Transformatory and never returned!\n\nWe must stop this at all costs. More have been taken but it's not too late for them yet. They are still being kept in the Burrows. Find them and free them.", objectives = "" }
WordHunterWoW_QuestEN[82127] = { title = "Make Them Prey", description = "These abductors are rounding up citizens and no one in the Burrows can stop them. I think it is about time somebody did something. \n\nThey stalk the Burrows thinking they are unseen but I can see them, we can all see them. It's just nobody here can oppose them. That is where you come in.\n\nHunt these abductors down and show them who is really the prey.", objectives = "" }
WordHunterWoW_QuestEN[82130] = { title = "A Shot at the Top", description = "While you have been out, I've been keeping busy as well. \n\nYour exploits in the Burrows drew the attention of someone much higher up. A strange being wrapped in bandages, with a scent like despair.\n\nFortunately, this unusual monster is paying a visit all the way down in the Burrows to find out why their abductors are missing. Now is our chance to strike, and take down this whole operation.", objectives = "" }
WordHunterWoW_QuestEN[82141] = { title = "To Kill a Queen", description = "Tightening her grip on the citizens is something I expected of the Queen but forcefully ascending the population of the Burrows is too far. \n\nQueen Ansurek has fallen far greater than I ever expected. I can't sit idly by and watch her lead our people to ruin.\n\nThe time is now. We must kill Queen Ansurek and lead the people to a brighter future. Otherwise who knows how far she will fall.", objectives = "" }
WordHunterWoW_QuestEN[82143] = { title = "The Path of Dissonance", description = "Hannan is correct only in that my presence here is not... strictly allowed.\n\nBut this corruption echoes in my mind, like a disruptive chord in the otherwise pure song of the world. Like a cry for help.\n\nI must heed that call. I must follow the dissonance to its source and find the heart of it, so that I may discover how to cleanse it.\n\nJoin me.", objectives = "" }
WordHunterWoW_QuestEN[82144] = { title = "On the Road", description = "This is the only road to the elevator, he should have been here by now. \n\nUnless... he didn't take the road! He wouldn't want to be seen. \n\nHe has no idea how dangerous the deeps can be. We have to find him!", objectives = "" }
WordHunterWoW_QuestEN[82153] = { title = "Embassies and Envoys", description = "We sailed for what seemed like an eternity. I must admit there were times when I worried we would arrive too late.\n\nBut seeing all of you, united and strong, has rekindled my hope.\n\nBefore we begin planning, we must set up a base of operations here in Dornogal.", objectives = "" }
WordHunterWoW_QuestEN[82195] = { title = "Rust and Redemption", description = "As you approach, a rusty lever catches your eye, stubbornly stuck in its place. \n\n\"This thing hasn't moved in ages,\" you muse, as you feel the rough metal resist your touch. \n\nGlancing around, you note the oily sheen on the plantlike Crawlers. \"Perhaps a bit of natural lubricant would do the trick,\" you ponder, realizing that these flora foes might yield what you need to ease the lever's grip.", objectives = "" }
WordHunterWoW_QuestEN[82213] = { title = "A Batty Request", description = "I'll gather a selection of our major trade goods before we head out for the meet up, but I could use some help in gathering some additional items. \n\nLately we've been struggling with collecting the best bat meat in Hallowfall. Could you gather some before you come to Dunelle's Kindness?", objectives = "" }
WordHunterWoW_QuestEN[82214] = { title = "Does Anyone Like Wasps?", description = "We haven't been able to gather resources from this area due to hornets moving in. \n\nWe just haven't been able to spare the resources from the wall to deal with them. If you can, we'd all appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[82215] = { title = "Regular Fiber", description = "There is a plant fiber that grows in Rumshackle and The Fangs that makes for an excellent rope. Because of the hornets, we haven't been able to collect it in a long time and are running very low in our supplies.\n\nWhile you are in the area, could you collect some?", objectives = "" }
WordHunterWoW_QuestEN[82216] = { title = "Economical Request", description = "I hear you've come from the surface? Did you meet the earthen?\n\nWe used to trade with them, but after the Day of Darkness we struggled to send envoys. Those we sent never made it back. Honestly, we thought that they had perished.\n\nI'm going to try reaching out again. I'd like for you to write a letter of recommendation, in case we did something to offend them.", objectives = "" }
WordHunterWoW_QuestEN[82217] = { title = "Underground Economics", description = "After the Day of Darkness, we haven't seen or heard from the earthen. I don't know why.\n\nWe used to be on good terms. I'd even have considered Merrix a friend, albeit an odd one. \n\nWe need this to go well.", objectives = "" }
WordHunterWoW_QuestEN[82219] = { title = "Spice Up Your Life", description = "Flames blessing to you, {name}.\n\nTrade has been going well now the Ringing Deeps are safe once again and things have, relatively, calmed down. Despite that, our General still won't breathe easily. She's wound tight and it's not healthy. An unhealthy general leads to an unhealthy army. \n\nSo a day with the family. Can you pick some herbs for the meal? You'll want the big ones, don't bother with the small ones.", objectives = "" }
WordHunterWoW_QuestEN[82220] = { title = "Eagle Eye, Eagle Die", description = "The eagles out by the undersea have bathed in the light of Beledar, and it makes them particularly tasty.\n\nCould you get a few eagle fillets? Take this harpoon with you, they can be feisty.", objectives = "" }
WordHunterWoW_QuestEN[82221] = { title = "Full Dress", description = "A traditional Arathi family meal involves displaying the various medals, awards, and mementos of the family. Given my mother's illustrious career, it's taking quite a while. \n\nWould you mind helping with some of the decorations?", objectives = "" }
WordHunterWoW_QuestEN[82222] = { title = "Cooking With Style", description = "Sorry my daughter roped you into this. I'm sure you had better things to be doing. \n\nShe has terrible manners. I'll have to have words with whoever raised her.\n\n<The general's mouth twitches in a quick smirk.>\n\nStill, you are here. Would you like to join us for the more enjoyable activity? We're about to start cooking.", objectives = "" }
WordHunterWoW_QuestEN[82223] = { title = "A Home Cooked Meal", description = "Home-cooked stew. There is nothing like it in the world. \n\nI grant you, it might not be as tasty as the stew from the Empires Edge Inn. But it was cooked by family. That's what makes it great.\n\nJoin us. You have more than earned the right.", objectives = "" }
WordHunterWoW_QuestEN[82224] = { title = "Check on the Compiler", description = "That's everything up here. Would you check on Brennok? Recitations can be stressful, I'm sure he'd appreciate the help.", objectives = "" }
WordHunterWoW_QuestEN[82226] = { title = "Papers? Please!", description = "Hey pal, what's it gonna take to get you to leave me alone? \n\nHow about a trip? A POWER trip...\n\nI told Boss Sparkshot that I would man the worksite's...er, resort's! Yeah, that I would man the resort's front desk for a bit.\n\nCare to take my place? It's just your usual paper-pushing busy work. Check credentials, keep an eye out for corporate sabotage, call in the occasional air strike, etcetera, etcetera...\n\n<Garv has already fallen back asleep.>", objectives = "" }
WordHunterWoW_QuestEN[82229] = { title = "An Uncommon Request", description = "{name}, welcome to Bel'ameth. I wonder -- do you have time for a small favor?\n\nEarlier today, a young kaldorei named Kelestra came to see me. She sought permission to bury her family in a barrow den. An uncommon request, but I gave her my blessing and directed her to the Barrows of Reverie. \n\nShe looked... melancholy. After she left, it struck me that she might be the last of her family still alive. If you have the time, could you check on her?", objectives = "" }
WordHunterWoW_QuestEN[82236] = { title = "Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[82248] = { title = "Advance to Faerin", description = "I have a little morsel all wrapped up from a corner of my web. Shall I share it with you? It's sure to mean your doom, little {race}.\n\nVery well... I can smell your eager impatience. I've sent that little green blob of a goblin you call Gazlowe off to the northeast. He tells me the queen and high general are marshalling their elite shock troops. No doubt they are readying to invade Hallowfall.\n\nScurry off to your Lamplighter friend. I'm certain she will want to smash everything in sight.", objectives = "" }
WordHunterWoW_QuestEN[82268] = { title = "The Sorrowful Journey Home", description = "I intend to burn Ryton's breastplate and Sir Ashrealm's tinderbox at Mereldar. I would be honored if you would join me.\n\nWould you carry the breastplate there?", objectives = "" }
WordHunterWoW_QuestEN[82284] = { title = "Remembrance for the Fallen", description = "It is our custom to pay homage to the fallen by burning whatever we can recover of their belongings. Usually, it is their tinderboxes as those are easier to carry. We then return those items to the flame.\n\nWhile we were able to retrieve Sir Ashrealm's tinderbox, Ryton's breastplate will serve to honor his memory.\n\nYou have placed your life in danger not only for me, but also for Hallowfall. I would be honored if you would assist me this one last time in remembering our fallen.", objectives = "" }
WordHunterWoW_QuestEN[82296] = { title = "The Power of Creation", description = "", objectives = "" }
WordHunterWoW_QuestEN[82334] = { title = "DO NOT USE", description = "", objectives = "" }
WordHunterWoW_QuestEN[82335] = { title = "Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[82336] = { title = "[DNT] Supplies Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[82337] = { title = "Test Quest - First time Rewards (DNT)", description = "This quest should give the following rewards for first time completions / additional completions on the account\n\nCurrencies:\nDragon Isles Supplies: 100/25\nSoul Ash: 10/100\n\nRep Currencies:\nValdrakken Accord Rep: 100/25\nMaruuk Centaur Rep: 10/100\n\nItems:\nDraconium Ore: 100/25\nHochenblume: 10/100\n(DNT)", objectives = "" }
WordHunterWoW_QuestEN[82338] = { title = "Absent Errand", description = "Do you remember the logbook you discovered in Zev'kall's office? It contained critical information about Zev'kall's misuse of our people. I gave it to my assistant, Anub'okki, to bring to the historians in the Skeins.\n\nBut I have not heard back from Anub'okki. I suspect foul play. See if anyone in the Skeins will admit to having seen him!", objectives = "" }
WordHunterWoW_QuestEN[82339] = { title = "An Honorless Kill", description = "If it will get you out of here sooner, I will tell you what I saw.\n\nI did not see what happened to Anub'okki. But I can tell you that corpses are dumped into Pillar-nest Xesh to be forgotten about. The cleanup crew dragged Anub'okki out of here not long ago. \n\nIf you hurry, you may be able to examine the remains before they are gone.", objectives = "" }
WordHunterWoW_QuestEN[82340] = { title = "Loss of Limb", description = "Happy greetings! I am Mr. Sunflower, and this is my tea room and therapy space. It is a safe place for everyone!\n\nI wonder if you might be willing to help a patient of mine. Vi'azl is deathly afraid of creatures with fewer limbs. I think it has grown into a deep phobia of dismemberment. I'm trying to get to the bottom of this diagnosis. \n\nWould you speak to him, and demonstrate that you, who do not have eight limbs, are not so terrifying after all?", objectives = "" }
