WordHunterWoW_QuestEN[82509] = { title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", objectives = "" }
WordHunterWoW_QuestEN[82510] = { title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", objectives = "" }
WordHunterWoW_QuestEN[82511] = { title = "Worldsoul: Awakening Machine", description = "The earthen tell me of this \"Awakening Machine\" that is part of their life cycle.\n\nIt imbues them with energy, once a gift of the titans but now from the Worldsoul.\n\n<Faerin smiles faintly and nods knowingly.>\n\nThey hold it in high reverence--as we do Beledar. \n\nI will fight to defend it with the same fervor as I would defend our own star! \n\nAid me, {name}. We can't let them down.", objectives = "" }
WordHunterWoW_QuestEN[82512] = { title = "Worldsoul: World Boss", description = "Hallowfall is not the only land beset by enemies. \n\nGreat monsters wander all of Khaz Algar--savage beasts and intelligent fiends alike. They murder Arathi, earthen, and adventurers in equal measure from innocent farmers to great warriors. \n\nI know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", objectives = "" }
WordHunterWoW_QuestEN[82516] = { title = "Worldsoul: Forging a Pact", description = "I've heard some reports of the goings on in Azj-Kahet. Nerubians have killed my people mercilessly since we arrived... it is very difficult to imagine them as allies.\n\nBut... I understand feeling... different from the rest of your people. Perhaps these nerubians who have interest in us are also... different. \n\n<Faerin sighs.> \n\nNo matter the cost... I can't bear to not give them a chance. Are they not also inhabitants of Khaz Algar?\n\nSee what aid you can bring them, my friend.", objectives = "" }
WordHunterWoW_QuestEN[82539] = { title = "Radiant Echoes", description = "<A missive finds its way to you.>\n\n{name}, please come to Dalaran at once. Strange phenomena are appearing all across Azeroth. We believe they may be connected to the Radiant Song. I'd like you to investigate.", objectives = "" }
WordHunterWoW_QuestEN[82540] = { title = "Memories of Adventures Past", description = "It seems that Azeroth has grown... agitated? Something must have happened when Magni tried to commune with her. \n\nPast events have now come to life once more. I believe they're Azeroth's memories.\n\nMemories they may be, these Radiant Echoes are all too real and could cause serious danger if left unattended. I ask that you investigate one of them and help however you can.", objectives = "" }
WordHunterWoW_QuestEN[82544] = { title = "The War Within (80) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[82550] = { title = "The War Within (70-79) E", description = "", objectives = "" }
