WordHunterWoW_QuestEN[82627] = { title = "DNT REUSE ME", description = "Baron Braunpyke and his brother have been working on removing our lingering kobyss problem from near the veneration grounds.\n\nMeet with them there and see what help you can offer.", objectives = "" }
WordHunterWoW_QuestEN[82628] = { title = "The Brothers Braunpyke", description = "Baron Braunpyke and his brother have been working on removing our lingering kobyss problem from near the Veneration Grounds.\n\nMeet with them there and see what help you can offer.", objectives = "" }
WordHunterWoW_QuestEN[82629] = { title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", objectives = "" }
WordHunterWoW_QuestEN[82638] = { title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", objectives = "" }
WordHunterWoW_QuestEN[82639] = { title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", objectives = "" }
WordHunterWoW_QuestEN[82659] = { title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", objectives = "" }
WordHunterWoW_QuestEN[82672] = { title = "Another Timely Invitation", description = "The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris!\n\nThere are all sorts of new activities to partake in that honor and remember what has transpired over the years.\n\nHead to Tanaris and join in the festivities.", objectives = "" }
WordHunterWoW_QuestEN[82676] = { title = "Broken Masquerade", description = "I cannot remember how I arrived at this swamp, but it was great luck that I did. As I wandered, I spotted Lady Katrana Prestor entering a strange toothy cave. Now, what would a noblewoman be doing in such a ghoulish place?\n\nFollowing her closely, I found a great clutch of black dragon eggs within the lair. Such evidence is clear. Katrana is Lady Onyxia! \n\nI beg of you, aid me in defeating this vile dragon once and for all.", objectives = "" }
WordHunterWoW_QuestEN[82678] = { title = "Archives: The First Disc", description = "I am pleased to report progress has been made restoring the titan Vault of Memory in the Archive. I have the mainframe up and running--but part of its internal mechanism has failed over time.\n\nGetting parts for it will be a challenge, which is why we need your help. Come with me to the Vault of Memory. We can discuss what we need with Dagran.", objectives = "" }
WordHunterWoW_QuestEN[82679] = { title = "Archives: Seeking History", description = "We're still processing the data in the Archive and restoring what we can. But... the discs we've recovered so far in the Archive itself are unusable.\n\nFinding more of these discs are a priority. We must reclaim our memories.\n\nReturn what you find to Dagran. He is assisting me in rebuilding the Archive.", objectives = "" }
WordHunterWoW_QuestEN[82680] = { title = "Birdman of the Three Shields", description = "Are you here to watch the mosswools? No? \n\nThat's too bad. I find the elemental creatures on our isle fascinating. I'm not the only one. \n\nAn old friend of mine named Olbarig resides out on the Three Shields. He studies the wild cloudrooks there.\n\nBut come to think of it, I haven't heard from him in awhile. Maybe someone should check on him. Hm. Would you mind?", objectives = "" }
WordHunterWoW_QuestEN[82681] = { title = "Cloudrook Down", description = "You see that flock in the distance? Wild cloudrooks. \n\nThey've lived on these islands peacefully for ages. But recent events have stirred other elementals from the earth and sea. One of the cloudrooks was attacked, and it was... disincorporated.\n\nNow the flock circles endlessly. Surely they will tire soon. If they get too tired...\n\nPerhaps if we cleared the hostile elementals from this island, they will return and take their rest.", objectives = "" }
WordHunterWoW_QuestEN[82682] = { title = "Elemental Hors D'Oeuvres", description = "The cloudrooks cannot possibly circle forever, and I cannot bear more of them being lost. But maybe they'd roost if we tempted them with their favorite food?\n\nThe eels that swim in these waters carry a small electrical charge not unlike the mosswool favored by their faster, stronger cousins the stormrooks. I once reasoned that cloudrooks might enjoy the eels for similar reasons. \n\nAnd I confess... I've been feeding them the eels ever since. \n\nGather some up and give it a go.", objectives = "" }
WordHunterWoW_QuestEN[82689] = { title = "Only Darkness", description = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!", objectives = "" }
WordHunterWoW_QuestEN[82690] = { title = "Lingering Shadows", description = "When we faced Xal'atath's forces in Hallowfall, I sensed something dark just beneath the surface. Something that was not her, but it still troubles me.\n\nI have learned that running into every situation myself is not always the best tactic. Sometimes, a leader must stand back to see the field.\n\nSo, I send you.\n\nGo to Hallowfall, and uncover what you can about this mysterious force. I don't want to be caught blind again.", objectives = "" }
WordHunterWoW_QuestEN[82691] = { title = "No Breathing Room", description = "We all followed Orweyna to these surface caves because we believed in what we were doing. But this... We did not bargain for so many injuries, so much dogged searching.\n\nFor now, we just need a little breathing room. Slay the creatures out there that are harming us, and we can get the space to address the real issue.", objectives = "" }
WordHunterWoW_QuestEN[82692] = { title = "Price of a Mission", description = "I don't know what prompted you to come here, but we could use your help. \n\nWe came to investigate signs of the Black Blood in this area, but the creatures overwhelmed us. Several of us are still out in the field.\n\nYou are hale and hearty. Go find my people so they can return.\n\nAnd, if you have the strength, take a closer look at the strange flowers that grow from the blood that seeps beneath the ground. They may hold a clue as to how we can fight against its corruption.", objectives = "" }
WordHunterWoW_QuestEN[82693] = { title = "Standing in the Way", description = "Some of these creatures are stronger than others. When we were able to act together and fresh to the fight, these creatures were no threat. Now our injuries and separation leave us vulnerable. \n\nMy people are resilient, but we are not immortal.\n\nThere is one beast larger than all the others. That beast is making it difficult for the haranir to return and recover.\n\nSlay it, so they can be safe.", objectives = "" }
WordHunterWoW_QuestEN[82694] = { title = "Together, Alone", description = "I am not blind. I know that they are tired and weary. But we are so close to figuring out what we can do about the Black Blood.\n\nThe importance of what we uncover goes beyond Hallowfall, or the nerubian kingdom. There is so much more work if we are to find a solution.\n\nFor now, let us withdraw and recover. Somewhere away from these creatures.", objectives = "" }
WordHunterWoW_QuestEN[82695] = { title = "The Voice", description = "Here is where I must focus. I can hear the voice of my goddess, and she must be near.\n\nI will enter a meditation to ask what I must do. How can I continue this mission alone? How can I go on without the others?\n\nStay close. I don't know what may lurk or threaten while I am concentrating.", objectives = "" }
WordHunterWoW_QuestEN[82696] = { title = "Ringing in the Deeps", description = "My vision was clear to me. I need to continue this work.\n\nI need to find out how we can stop the Black Blood from spreading, before it's too late for your people, and for mine.\n\nMeet me in the Ringing Deeps. I will be in a form that allows me to hide and to listen without anyone noticing.", objectives = "" }
WordHunterWoW_QuestEN[82697] = { title = "Good Help These Days", description = "Seeing you here is a welcome surprise!\n\nThere's something big happening over at Opportunity Point, but it's hard to know what without getting closer to the people working there. \n\nI know Haxle's involved. We'll need his paperwork if we want to be able to ask around without trouble. \n\nHe's headed down to Opportunity Point. \n\nGo, follow him, and see if he's got anything on him we can use. Don't worry about the mess-- I know you're discreet when you need to be.\n\nAnd... also not, when you need to be.", objectives = "" }
WordHunterWoW_QuestEN[82698] = { title = "Haywired and Hostile", description = "I saw many machines nearby, and all of them seem to make dreadful noises. I cannot hear the one that I heard in the vision, though, at least not clearly.\n\nDestroy the excess ones. They are only in the way.\n\nWhile you are quieting the scene, I will hunt and scout.", objectives = "" }
WordHunterWoW_QuestEN[82699] = { title = "Hey, What's Going On?", description = "Time to do some networking. \n\nThere's a bunch of goblins outside of Opportunity Point, over there in the Abyssal Excavation. I heard some of them grumbling as they started their shift.\n\nLet's see what some friendly words shake loose.\n\nWhile you're out there, check out the used fuel drums. They wouldn't let me look inside the full drums, but they just drop the used ones around the work site.", objectives = "" }
WordHunterWoW_QuestEN[82700] = { title = "Built to Blast", description = "We've got an intel problem, but we've also got a clank problem.\n\nIf you look over there, there's a big, haywire mech that's just going crazy. There's no way anyone's going to uncover anything while that's out in the field.\n\nWe should do something about that.", objectives = "" }
WordHunterWoW_QuestEN[82701] = { title = "Bat Versus World", description = "When I scouted, I heard and saw things that I don't understand. \n\nPerhaps if I describe it to you and the goblins, you will know what it means.", objectives = "" }
WordHunterWoW_QuestEN[82702] = { title = "Found Friends", description = "So Gallywix has chosen to show his ugly face here, and it looks like he's got himself organized.\n\nWe should report this to Alleria. See how she wants to handle it.", objectives = "" }
WordHunterWoW_QuestEN[82706] = { title = "Delves: Worldwide Research", description = "It's been all quiet recently. I've nae heard of any issues. \n\nThis seems like a good opportunity for exploration, eh? I'm at yer disposal! We can go wherever it is ye want tae go!", objectives = "" }
WordHunterWoW_QuestEN[82739] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[82740] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[82747] = { title = "Crossroads Plaza", description = "Hello, outlander. Do you want to know about news from outside the city?\n\nThe Crossroads is a key place for earthen to exchange information and goods, no matter their allegiances or edicts.\n\nMy friend Bondaz unofficially maintains the square. He would be delighted to see you in person. I'm sure he has already heard a hundred different stories of how you and the outlanders made it to our isle.", objectives = "" }
WordHunterWoW_QuestEN[82748] = { title = "Deephaul Ravine", description = "We've received reports of troubles in the earthen depths. Explore the Deephaul Ravine and the resources available, then report to Ruffious.", objectives = "" }
WordHunterWoW_QuestEN[82762] = { title = "Keeping a Close Tabard", description = "Wow!\n\nThat's a super nifty tabard! And it's all yours to customize however you want.\n\nKessa should be able to help you bring your designs to life.\n\nGo ahead and pay her a visit to get started!", objectives = "" }
WordHunterWoW_QuestEN[82768] = { title = "Cloud Fishing", description = "Now that we have the eels, we can try to lure the cloudrooks back to land. \n\nHead over to the neighboring island. Get as close as you can and make an offering to the rooks. \n\nWith luck, they'll cease their circling and come down for a nourishing meal.", objectives = "" }
WordHunterWoW_QuestEN[82771] = { title = "Heritage of the Earthen", description = "The time has come to give back to the Archives. \n\nAll earthen wanderers are invited to share their experiences for the preservation of what has come before and the betterment of those who will come after. \n\nThis knowledge and experience of the wider world of Azeroth is a priceless treasure, and the practice of sharing it is key to our earthen heritage.", objectives = "" }
WordHunterWoW_QuestEN[82773] = { title = "A Functional Favor", description = "I am seeking my mentor, Foreman Arbauch. He is... missing. Under other circumstances, I would send for a search party from Gundargaz, but there is no time.\n\nI suspect he passed through here, but the only lead I have is DelGizmo. He wants the local fog beasts removed. Reluctance. But if he has seen Arbauch, I must learn what he knows.\n\nThe lurkers to the south carry powerful Galvanic Glands. They have enough charge to disperse even the thickest fog. Retrieve some. Compensation assured.", objectives = "" }
WordHunterWoW_QuestEN[82774] = { title = "Antifogmatic", description = "Machine speakers have no love for fog beasts. Where there is fog, rust is sure to follow. Still, I'd prefer not to harm them. Arbauch always said it was bad luck.\n\nTake this device. The glands you collected should provide enough power to disperse the fog without hurting the fog beasts within.\n\nCaution. Fog beasts are skittish, but other creatures may also lurk.", objectives = "" }
WordHunterWoW_QuestEN[82775] = { title = "Quickchange Artist", description = "You seem to have the programming of a great actor within you, {name}!\n\nI know it because I have that fire myself--no matter what the rest of these so-called \"actors\" say.\n\nI'm very impressed with how fast you change costumes. I am a master of the quickchange artist's ways myself, you know.\n\nYou're very close to figuring it out. You just need a few pointers from an expert--like me!", objectives = "" }
WordHunterWoW_QuestEN[82778] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "" }
WordHunterWoW_QuestEN[82781] = { title = "Attention-Getter", description = "My, {name}, it seems you have drawn the attention of a particular audience member.\n\nThis fan letter was mistakenly included in my fan mail. I'm not surprised. Sorting my copious fan mail must be a difficult chore...\n\nHere, take it. It belongs to you, of course.\n\nI'm sure this is very new for you. I have a few pieces of wisdom for greeting eager fans, if you would like to hear it...", objectives = "" }
WordHunterWoW_QuestEN[82782] = { title = "Authenticity in Dress", description = "You've done very well as an actor on stage, {name}.\n\nBut as an actor in a troupe, there are other directives we must carry out. One directive is to preserve our costumes for use in future plays. Many costumes we use more than once.\n\nI think we can trust you with using and preserving the troupes' costumes, don't you think? It would mean you could practice with us more frequently...", objectives = "" }
WordHunterWoW_QuestEN[82783] = { title = "Chromie's Codex", description = "Hello there! I could really use your help. \n\nYou see, my codex has gotten a bit jumbled in all my travels lately, and I have to give a time tour back to the gates of Ahn'Qiraj in an hour. \n\nI need you to jump in with me to sort out any... inconsistencies. Then it should be right as rain and all the visitors here will have a fun, not-super-dangerous tour!", objectives = "" }
WordHunterWoW_QuestEN[82784] = { title = "Resonant Performance", description = "{name}, I have learned a lot from watching you perform. You change your nature so easily. In one play, I have seen you change from enemy to friend, from anger to sorrow... It's like watching mercury flow.\n\nWith you on our stage, I feel we complete our plays to the letter of our directives with the highest satisfaction for our audience.\n\nIf you have a moment, I would like to thank you for your support.", objectives = "" }
WordHunterWoW_QuestEN[82785] = { title = "Ghosts in the Machine", description = "There's a substation directly below us? Perhaps that is where Arbauch went to hide it... Disregard, we must investigate.\n\nWith luck, Arbauch may still be here. The entrance should be to the north, near the pool of water from the burst pipe. Please, come with me. He may need our help.\n\nI will explain everything once he is located.", objectives = "" }
WordHunterWoW_QuestEN[82786] = { title = "Duty of Care", description = "The golem is unstable. I doubt it can travel far. We will track it, but haste failed me once already. Arbauch showed true devotion to the machines--we will follow his example. Repairs must come first.\n\nMachine systems are delicate. We must activate the backup before the failure can cascade. Exterminate any pests you find as well. Even the smallest creature can ruin delicate machinery.\n\nI am damaged. I will send my cogwalker with you to relay instructions.", objectives = "" }
WordHunterWoW_QuestEN[82792] = { title = "All Ore Nothing", description = "Outlander. Your aid is requested. \n\nThe earthen here have said you would be of help. \n\nOur fellow earthen at the Opalcreg have not reported their quota for the past day. There must be something causing a disruption.  \n\nWould you pay Foreman Alvegar a visit?", objectives = "" }
WordHunterWoW_QuestEN[82796] = { title = "Third Mine Blind", description = "I got cut off from the rest of the crew. We did not expect to be attacked by nerubians. Though I can't imagine the rest quitting.\n\nOur duty is too important to give up just yet. \n\nBarging right into the mine could cause the nerubians to frenzy and hurt the others. So, I found a third way to get in earlier. Though undetected will still be tough. \n\nFollow me.", objectives = "" }
WordHunterWoW_QuestEN[82797] = { title = "Hit Rock Bottom", description = "A long way down to be sure, but I am certain that you can make it. \n\nIf you doubt yourself, I made some parachutes to help you stick the landing. \n\nOnce you get to the bottom of the cave, look for Cenderragg. She's the most senior of the group and probably has the best idea on how to rescue the team.", objectives = "" }
WordHunterWoW_QuestEN[82798] = { title = "An Opal of Mine", description = "I'll be direct with you. We have a goal here and those opals are the center of it. \n\nNo one will leave until we get the job done, the opals are too important. If you could gather enough ore, we could convince them to leave.  \n\nBut be careful, those nerubians are dangerous.", objectives = "" }
WordHunterWoW_QuestEN[82799] = { title = "Web Beats Rock", description = "So, Foreman Alvegar sent you? That explains it.\n\nThe situation is not great. This place is crawling with nerubians and they're showing us no mercy. They forced us to mine and took our hard-earned opals. \n\nWhen you disobey, they web you up. \n\nI was barely able to escape them when they came. The others... Well, that's where you come in.\n\nWith you here distracting them, I can go rally the webbed earthen.", objectives = "" }
WordHunterWoW_QuestEN[82800] = { title = "A Sedimental Moment", description = "Some have started to evacuate, but there's a stubborn few that just won't let go. \n\nCould you say something? \n\nMaybe an outsider's perspective will get them moving.", objectives = "" }
WordHunterWoW_QuestEN[82801] = { title = "Beetlejeweled", description = "To make sure no other earthen gets harmed we're going to have to eliminate their leader. \n\nYou know the saying, rid yourself of the foreman and the whole line collapses. \n\nEither way, to get to safety we're going to have to go through them.", objectives = "" }
WordHunterWoW_QuestEN[82809] = { title = "Gryphons of a Feather", description = "Hey there! I notice ye got a stormrook that's lookin' rather unhappy. Let's see what we can do to cheer 'em up.", objectives = "" }
WordHunterWoW_QuestEN[82810] = { title = "Time Found", description = "Yer back!\n\nIf you're up for it, there's more things in the muck to be found. Might have to dig a bit deeper this time.", objectives = "" }
WordHunterWoW_QuestEN[82813] = { title = "Time Borrowed", description = "Ah, now there's my good friend! Me and Mags are still here, looking for memories. Got a moment to spare for help?", objectives = "" }
WordHunterWoW_QuestEN[82814] = { title = "Decommissioning Darkness", description = "Decommissioning a machine is a rare necessity. It must be done with care and regret.\n\nWe put much of ourselves into our work. To destroy it is to destroy a part of ourselves. In doing so, we admit our failure to protect the Titans' work.  But where stone rebels against stone, we must stand firm.\n\nImperative: Destroy it. Recover Arbauch's memory gem.", objectives = "" }
WordHunterWoW_QuestEN[82815] = { title = "Sturdy Locket", description = "What do you have there?", objectives = "" }
WordHunterWoW_QuestEN[82817] = { title = "Disturbance Detected: Blackrock Depths", description = "The Timewalkers claim that they detected a time-displaced object in Blackrock Depths.\n\nWhile that fight may have ended in our defeat, the Dark Iron clan knows what's at stake should history change. We could lose the current dwarven alliance and all the good it has brought.\n\nRecover the object and protect our current peace.", objectives = "" }
WordHunterWoW_QuestEN[82832] = { title = "Wooden Figure", description = "Got a cat problem?", objectives = "" }
WordHunterWoW_QuestEN[82835] = { title = "Calcified Journal", description = "Are you looking for someone?", objectives = "" }
WordHunterWoW_QuestEN[82836] = { title = "Zero Out Xerosh", description = "{name}, the nerubians all seem to be taking orders from that siegelord south of here. If we can defeat her, that may turn the tide of this attack.\n\nWithout a leader organizing the attack, the Arathi may be able to drive back the nerubians, especially if Faerin is able to light this dawntower she spoke of.\n\nBut the longer we delay, the greater damage to the Arathi airships. Go quickly!", objectives = "" }
WordHunterWoW_QuestEN[82842] = { title = "Test Quest - Combined First time Rewards (DNT)", description = "This quest should give the following rewards for first / additional completions on the act\n\nDragon Isles Supplies (stupid complex setup): \nFirst Time : 101,025 + 9075  bonus\nAdditional: 101,025\n\nValdrakken Rep (Simple setup with flags):\nFist time: 25 + 75 bonus\nAdditional: 25\n\nMaruuk Centaur (simple setup with modifier only)\nFirst time completion: 25 + 75 bonus\nAdditional Completion: 25 \n\nDragonscale (modifier + combine)\nFirst Time: 25 + 100 bonus\nAdditional: 25\n\n(DNT)", objectives = "" }
WordHunterWoW_QuestEN[82843] = { title = "Something Earthy", description = "Ah, another one of you lot, eh? Well, if you want to eat, you need to help.\n\nPick me a fresh taro, will you?", objectives = "" }
WordHunterWoW_QuestEN[82844] = { title = "Something Not Ruined", description = "Alright, I'll come with you. Show you how to do this properly. If I'm up, we might as well stock up on taro. Can't rely on adventurers to do delicate work, I suppose.", objectives = "" }
WordHunterWoW_QuestEN[82845] = { title = "Ivory Tinderbox", description = "What brought you to the Priory, outsider?", objectives = "" }
WordHunterWoW_QuestEN[82846] = { title = "Dented Spearhead", description = "We meet again. How can I help you?", objectives = "" }
WordHunterWoW_QuestEN[82847] = { title = "Enough Garlic", description = "Normally, this would do. I'm not so picky. But you're a guest. So we'll need some garlic.\n\nI found some growing on a hill not far off. Shouldn't be there. But it is.\n\nToo bad hydras found it, too.\n\nYou have weapons and such, right?", objectives = "" }
WordHunterWoW_QuestEN[82848] = { title = "Sous", description = "Alright, now help me finish this.", objectives = "" }
WordHunterWoW_QuestEN[82849] = { title = "Filigreed Cleric", description = "Got a request from the kitchen?", objectives = "" }
WordHunterWoW_QuestEN[82894] = { title = "The Price of Hope", description = "{name}, good to see you. I am about to make a trip to the local infirmary. \n\nWould you care to join me?", objectives = "" }
WordHunterWoW_QuestEN[82895] = { title = "The Weight of Duty", description = "I am now the caretaker of Mourning Rise.\n\nAt last, I feel the weight of this new responsibility on my shoulders. It is a great honor, but one I must prepare myself for.\n\nPlease, help me complete one final task, and then I will be ready.\n\nMeet me back at Fallside Outpost.", objectives = "" }
WordHunterWoW_QuestEN[82916] = { title = "When Fungi Bloom", description = "Greetings! \n\nPerhaps you can help me with some busy work? I have so many orders that I have miscalculated several units of Mycobloom. To be honest, a bit more than several.\n\nWill you be kind and gather the rest for me?", objectives = "" }
WordHunterWoW_QuestEN[82946] = { title = "Rollin' Down in the Deeps", description = "Got a big task for you, yes? \n\nFetch things, all waxy. Bring 'em quick, yeah? Much to trade for good finds. \n\nGet snufflin', friend!", objectives = "" }
WordHunterWoW_QuestEN[82952] = { title = "An Opportunity to Relax", description = "Hey, you! Yeah, you'll do. You wanna make some coin? We's tryin' to drum up business at our exclusive resort. Maybe ye heard of it? Opportunity Point Spa and Resort! \n\nBoss sent me up to Gundargaz to pass out this stack of flyers, but my trike blew a gasket and I'll be stuck here for a bit repairing her. How's about you head up there and pass them out for me? Look for the tired and weary types.", objectives = "" }
WordHunterWoW_QuestEN[82953] = { title = "A Cordial Invitation", description = "It is clear to me now that my time as the Vizier is drawing to a close. The nature of my service to Azj-Kahet must change. To that end, I have one final task to ask of you, {name}.\n\nYou have done a great deal of work in the City of Threads since your arrival. No doubt your reputation now precedes you. Seek out our allies within the city and ask them to congregate in the Umbral Bazaar. I have a message prepared for them all.", objectives = "" }
WordHunterWoW_QuestEN[82954] = { title = "Knives in the Dark", description = "No doubt you recall the assassin that sought to end me when last we met on this spot. If it weren't for your intervention, I would not be here now. Make no mistake, if my role in all of this has been compromised, that assassin will not be the last.\n\nIf I am to make my last great stand, then I will need your help in ensuring my safety until the final hour. Scour the city for more of those skulking threats, and do what you must to ensure they will not interrupt my speech.", objectives = "" }
WordHunterWoW_QuestEN[82955] = { title = "The Vizier's Resolve", description = "The stage is set, and the players are gathered. It is time for me to step out of the shadows.\n\nThank you for standing with me thus far, {name}. Whatever comes next, I am grateful to have met you.", objectives = "" }
WordHunterWoW_QuestEN[82956] = { title = "To Opportunity Point", description = "Glad that's out of the way. Now my boss can stop breathing down my neck!\n\nI got some repairs to do on my ride, but you should go to Opportunity Point and check it out! I'll even give you a free drink voucher to our fine establishment. \n\nGo talk to Griz Finglebur and he'll get you sorted.", objectives = "" }
WordHunterWoW_QuestEN[82958] = { title = "Little Blessings", description = "You there!\n\nI am running low on Blessing Blossoms, and new supplies will not be delivered to me before I run out.\n\nCan I trust you to gather these herbs for me?", objectives = "" }
WordHunterWoW_QuestEN[82959] = { title = "Hillhelm Family: Lost Diary", description = "<This diary seems to belong to Aliya Hillhelm. It would be best not to read it and simply return it to her.>", objectives = "" }
WordHunterWoW_QuestEN[82960] = { title = "Hillhelm Family: Lily's Locket", description = "<This locket must be important to someone. Maybe Aliya Hillhelm can shed some light on it.>", objectives = "" }
WordHunterWoW_QuestEN[82961] = { title = "Hillhelm Family: The Chicken", description = "<This wayward chicken should probably be returned to Aliya Hillhelm at the Hillhelm Stead.>", objectives = "" }
WordHunterWoW_QuestEN[82962] = { title = "A Handful of Luredrops", description = "You, yes you.\n\nEver heard of the Luredrop? It is a rare carnivorous plant that eats insects. Now we do not have insects here, but I do wish I had a few samples. You let me know if you find any, or better, just bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[82963] = { title = "Hillhelm Family: Lil Piggy", description = "<This Lil Piggy should probably be returned to Aliya Hillhelm at the Hillhelm Stead.>", objectives = "" }
WordHunterWoW_QuestEN[82964] = { title = "Hillhelm Family: Uncle's Eye", description = "<A glass eye. It's quite a valuable item. Perhaps Aliya Hillhelm might know who has lost it.>", objectives = "" }
WordHunterWoW_QuestEN[82965] = { title = "Light and Shadow", description = "There are two herbs that I am missing. \n\nThe first is Arathor's Spear, and the second, and far more rare, would be Orbinid.\n\nNow I know what you are thinking: these are both rare. Yes, to a point, but I am not asking for many and the pay is well worth it.\n\nWhat do you think? Can I trust you for the task?", objectives = "" }
WordHunterWoW_QuestEN[82966] = { title = "Hillhelm Family: Unusual Potato", description = "<This potato has such an unusual shape. It almost resembles a famous person. Aliya Hillhelm will definitely want to see this!>", objectives = "" }
WordHunterWoW_QuestEN[82967] = { title = "Hillhelm Family: The Ear", description = "<A most disturbing discovery, you should show this to Aliya Hillhelm at Hillhelm Stead.>", objectives = "" }
WordHunterWoW_QuestEN[82968] = { title = "Hillhelm Family: The Plowhead", description = "<A plowhead in pristine condition. Aliya Hillhelm at Hillhelm Stead could probably make use of this.>", objectives = "" }
WordHunterWoW_QuestEN[82969] = { title = "Stone Tracing", description = "Couldn't help overhearing. Not to brag, but goblins are specialists in the field of rampaging robots.\n\nIf that golem's as unstable as Danagh says, it'll be leaking all sorts of energy. Take this, run a few scans, and you'll find it. Oh, and be careful. Animals tend to go a little cuckoo when you power this thing on.\n\nNo charge--a murderous golem's bad for business. And I kinda feel bad making you work just to find a dead guy.", objectives = "" }
WordHunterWoW_QuestEN[82970] = { title = "A Bloom and a Blossom", description = "Hi, you there!\n\nI have a task for you.\n\nI require a handful of Mycobloom and some Blessing Blossoms. There is a nice payment for them if you are up for the task.", objectives = "" }
WordHunterWoW_QuestEN[82971] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82972] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82973] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82974] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82975] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82976] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82977] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82978] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82979] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[82980] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[82990] = { title = "Undoing the Damage", description = "Apologies. Arbauch was not here for repairs--he stole that golem.\n\nArbauch and I worked alongside it for years in the darkest reaches of the Deeps. The work took its toll on the golem. It became erratic, dangerous even. We planned to decommission it, but when the time came, Arbauch couldn't bear it. He'd become attached. Before it could be destroyed, he took it and fled.\n\nIt must be found, but the damage to this substation is catastrophic. With your help, I will attempt repairs.", objectives = "" }
WordHunterWoW_QuestEN[82992] = { title = "Stormcharged Goods", description = "Greetings my friend!\n\nI am looking for someone who is willing to run a quick errand. I am running out of goods and I have not heard from my leather supplier for quiet some time. If I can not supply skins and leathers, the leatherworker will not be able to produce apparels.\n\nI will reward you if you can bring me several Stormcharged leathers.", objectives = "" }
WordHunterWoW_QuestEN[82993] = { title = "From Shadows", description = "Hello there!\n\nI have heard of fantastic materials that can be thread and put together from some... peculiar materials.\n\nIf you are the type who enjoys travelling through the last sunny parts of Khaz-Algar, will you be kind enough to gather Kaheti Swarm Chitin and Sunless Carapace for me? I will reward you nicely if you can supply me with some samples.", objectives = "" }
WordHunterWoW_QuestEN[82995] = { title = "Nerubian Device", description = "A strange device of Nerubian origins. Aevery Flamestonge at Hillhelm Stead might be intrigued by this.", objectives = "" }
WordHunterWoW_QuestEN[83023] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[83024] = { title = "The Stormrider's Bond", description = "So, you think yourself worthy of a Stormrider's armor?\n\nWe Stormriders were titan-made to fight and to ride stormrooks. Even so, we must prove our competence in battle before we gain clearance to wear Stormrider armor. I see no reason why you should not undergo the same challenges.\n\nGo. Show me you have the power of the storm within you.", objectives = "" }
WordHunterWoW_QuestEN[83025] = { title = "A Sacred Connection", description = "I may have granted you clearance to wear our armor, but to focus the storm's power through it as the greatest Stormriders do...\n\nThe greatest Stormriders in our order do not merely possess the power of the storm. They have mastered it. And this mastery is forged over many battles.\n\nIt is time to prove yourself as one of our best.", objectives = "" }
WordHunterWoW_QuestEN[83031] = { title = "The Hardest Part", description = "<Aethas sighs heavily, his voice tinged with sorrow.>\n\nDalaran... once a symbol of unity and arcane mastery, now reduced to rubble and ash. Again.\n\nSo much loss and so much pain. Friends and comrades gone in an instant, their voices silenced by Xal'atath. \n\n<He takes a deep breath, steeling himself against the overwhelming grief.>\n\nBut now is the time for action--not grief. We must regroup with the remaining Kirin Tor.\n\nHowever, the right words do not come easily.", objectives = "" }
WordHunterWoW_QuestEN[83040] = { title = "DO NOT USE", description = "", objectives = "" }
WordHunterWoW_QuestEN[83057] = { title = "Setting Boundaries", description = "Vi'azl has undergone a level of torture that I was unaware of. We cannot help Vi with his fear until Vi is actually safe.\n\nWhenever possible, I advocate friendship, recovery, and reconciliation. I ask others to act with compassion and empathy. Everyone deserves a chance to recover. I dedicate my life to this.\n\nBut hearing and seeing what is happening to Vi'azl... I think I've changed my mind. Enough is enough. We must act.", objectives = "" }
WordHunterWoW_QuestEN[83071] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[83072] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[83073] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[83074] = { title = "Queue Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[83075] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[83076] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[83077] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[83081] = { title = "Not Enough Minerals", description = "I did nae think the Opalcreg would be under attack! I'm sure Brinthe did nae either.\n\nPeacekeeper Hektare will nae let me fight, but maybe she will let you.\n\nI'll stay here an' tend to this earthen. I know a trick or two after bein' in Dornogal.\n\nOh, but... Brinthe really needed those opals...", objectives = "" }
WordHunterWoW_QuestEN[83082] = { title = "The Opalfront", description = "I'm a city guard, not a soldier! But these people need our help!\n\nThere are too many nerubians for us to clear out. We can only keep this chokepoint and hope the miners make their way to us.\n\nThat one was too small. But you look like a fighter. Help us!", objectives = "" }
WordHunterWoW_QuestEN[83083] = { title = "A Place Forgotten", description = "There is... a place behind Dornogal that I cannot go.\n\nAnd I am not the only one. Something--a force, most likely titan in origin--keeps the earthen from investigating a small portion of the island behind the city.\n\nThis, of course, fires my curiosity. But for thousands of years I have dutifully kept away. It seemed the titans' will.\n\nThe site emits a faint signal like the one from this device. Perhaps it is \"the key\" in a literal sense to what lies there.\n\nWe will see.", objectives = "" }
WordHunterWoW_QuestEN[83084] = { title = "The Old Orders", description = "Long ago, there were once plans to build a tunnel through the mountain into Dornogal. \n\nBefore excavation could begin, the surrounding area was suddenly abandoned. \n\nThere is no record of what happened. Only a... deterrence--the field--that keeps earthen away from this region.\n\nEvery part of my cognitive matrix is pressing for me to leave. But we must persist. \n\nThe device's signal indicates something lies within the nearby tower.", objectives = "" }
WordHunterWoW_QuestEN[83087] = { title = "The Old Guard", description = "Dornic... Galan... I've heard those names at the Proscenium!\n\nBut who was speakin'? They were nae happy with Galan. All those earthen bodies...\n\nRepurposed... like reprogrammed? Tae protect what?\n \nLet's chase the other signal. Looks like it leads up ahead intae the hills.\n\nI'm goin' to stay here with Brinthe an' investigate this tower further. You take the device.", objectives = "" }
WordHunterWoW_QuestEN[83088] = { title = "Caustic Collectables", description = "Boxenkle is my boss--and my mentor. Best slimediver there ever was! Until now...\n\nIt's not him--slimediving isn't what it used to be! The slimes have gotten more toxic over time. \n\nI think it's gotten so bad that we all should be wearin' eye protection--not just me. But ol' Enkle's a traditionalist. It'll take more than a few red eyes to convince him.\n\nThat's where you come in. If you can get residue samples from the really nasty slimes, maybe I can make a compelling case for ol' Enkle!", objectives = "" }
WordHunterWoW_QuestEN[83089] = { title = "Giving Goblins Goggles", description = "My mentor Enkle may be the loudest voice around here, but he's not the only one who needs help.\n\nOur whole crew only listens to him! Which means no one's wearing proper protective equipment.\n\nTake these goggles and convince everyone to take 'em on a trial run. Maybe if they all start changing their minds, Enkle will listen.", objectives = "" }
WordHunterWoW_QuestEN[83091] = { title = "Shield Your Eyes", description = "Causticaria? Is he crazy? No one has ever been able to process that monster!\n\nWe have to stop Enkle before he gets himself hurt!\n\nCausticaria lurks down this canal. Grab your goggles and follow me!", objectives = "" }
WordHunterWoW_QuestEN[83092] = { title = "An Igneous End", description = "When the magma transport pipe failed, our workers rushed down to begin repairs.\n\nThe elementals caught us unawares, rising up and attacking with great gouts of lava.\n\nFortunately, we earthen are made of stern stuff and a little magma is hardly going to be the end of us. Unfortunately, the cooling magma has hardened into stone shells, entombing our repair crews where they stood.\n\nSmash their stony prisons and free my workers!", objectives = "" }
WordHunterWoW_QuestEN[83096] = { title = "Welcome to Undermine", description = "There ya are! I'm Grimla. Welcome to Undermine. If you wanna get up to speed with the current situation, you've come to the right goblin. Pamsy vouched for you, that's good enough for me.\n\nI've got a coupon you can use at the Incontinental Hotel. We'll start there.\n\nLet's take a ride in \"Gramps,\" my hot rod! Hop in when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[83097] = { title = "Cinder and Storm", description = "The wild creatures here have stunning properties. I wonder what might happen if I combine them?\n\nBe on the lookout for Bottled Storm and Burning Cinderbee Setae. I'll reward you generously if you can bring me some samples. Oh, and if you gather them yourself, mind that you don't get burned. Or zapped. Or both.", objectives = "" }
WordHunterWoW_QuestEN[83098] = { title = "Snap and Crackle", description = "Do you have a moment?\n\nI'm looking for some materials with an edge. Something sharp and with a bit of sizzle. If you can find me Honed Bone Shards and Thunderous Hide, I'd be more than happy to compensate you.", objectives = "" }
WordHunterWoW_QuestEN[83099] = { title = "Mergers and Acquisitions", description = "When the nerubians launched their attack on my meadery, they left it a burnt-out husk. Adelgonn promised to rebuild it, but I got impatient and accepted the Venture Co.'s offer to help with its \"restructuring.\" \n\nBut now, it's clear they had their own agenda. Blasted goblins have taken over, and they're driving the place into the ground. They've ramped up production to unsafe levels, pushing the cinderbees and our equipment to their limits.\n\nPlease help fix this, {name}.", objectives = "" }
WordHunterWoW_QuestEN[83100] = { title = "Cracking the Shell", description = "Welcome!\n\nYou wouldn't believe the amount of materials we go through up here, and not just the rare stuff! We could always do with more Gloom Chitin. If you find some, bring it to me. I'll see to it you get paid.", objectives = "" }
WordHunterWoW_QuestEN[83102] = { title = "Bismuth is Business", description = "Do you know the backbone of a good mining operation? It's not the rare, flashy ores. It's good, common Bismuth.\n\nAnd we don't have nearly enough! Wherever you go, keep an eye out for Bismuth. Bring me as much as you can. \n\nCompensation is assured.", objectives = "" }
WordHunterWoW_QuestEN[83103] = { title = "Acquiring Aqirite", description = "You there!\n\nHave you heard of Aqirite? Valuable, versatile, very often surrounded by nerubians.\n\nI need that ore, and I don't care how you get it. If a nerubian does try to stop you, give them a whack for me.", objectives = "" }
WordHunterWoW_QuestEN[83104] = { title = "Identifying Ironclaw", description = "I sent a team to mine some Ironclaw Ore, they said they didn't see any. Can you believe that? It's a blasted great claw coming out of the ground!\n\nI'm not sending them again. I trust you'll know Ironclaw Ore when you see it. Bring it to me, and you'll be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[83105] = { title = "Rush-order Requisition", description = "Good to see you, I've got work.\n\nThe blacksmiths just sent a last-minute requisition for rare ores. Gravel-munching hammer-heavers, would it kill them to plan ahead? Well, I'm sure you can handle it.\n\nLooks like you'll need to track down Aqirite and Ironclaw Ore.", objectives = "" }
WordHunterWoW_QuestEN[83106] = { title = "Null Pebble Excavation", description = "Ever seen a Null Stone? Well, you will. They're rare, but we know how to put them to good use. Don't worry, I only need a couple.\n\nWhile you're at it, pick up any Bismuth you find. You can never have enough Bismuth.", objectives = "" }
WordHunterWoW_QuestEN[83108] = { title = "Daily Diagnostics", description = "It is my duty and honor to take diagnostic readings every day. I determine the output and efficiency of the Stonevault's great machines. The burden is mine.\n\nDescribing complication: now that skardyn have overrun the Stonevault, I cannot reach my machines!\n\nSolution proposed: I have heard that you are a hero of great renown. Please go in and gather today's readings for me. Timing will be critical in the event anything goes wrong. Awaiting confirmation.", objectives = "" }
WordHunterWoW_QuestEN[83109] = { title = "The Grimla Express", description = "Next stop, Tailgate Park. Bilgewater Cartel used to be in charge there, but Gallywix had other plans. Now the Darkfuse act like they own the place and the Bilgewater... Well, they do the best they can. \n\nI'm not sure who runs it now, if anyone does.", objectives = "" }
WordHunterWoW_QuestEN[83110] = { title = "Deliver Equipment", description = "Deliver safety equipment to Steamwheedle goblins to allow them to perform black blood experiments more safely.", objectives = "" }
WordHunterWoW_QuestEN[83113] = { title = "Recover Tools", description = "Kill black blood slimes and recover tools absorbed by the slimes.", objectives = "" }
WordHunterWoW_QuestEN[83114] = { title = "Red Tape", description = "First it was just Black Blood, now ethereals?\n\nI don't know how all this squares, but we need help if we wanna find out.\n\nOrweyna left to get Alleria a while ago. We should head over to Slam Central Station to see if they've made it down here yet.", objectives = "" }
WordHunterWoW_QuestEN[83115] = { title = "In the Mix", description = "I don't like thinkin' that Noggenfogger's part of this, but the only way we'll know is if we go and talk to him.\n\nSteamwheedle's headquarters is probably a good place to start lookin' for him.\n\nWe'll give him a chance to explain himself. If it's a misunderstanding, or he's just gotten himself into trouble, I need to know.", objectives = "" }
WordHunterWoW_QuestEN[83116] = { title = "Potion Commotion", description = "It really is great to see you and Gazlowe! I was just thinkin' about how much I wanted to see you both on my birthday.\n\nA day when I'm under no forms of duress or coercion whatsoever! N-None at all.\n\n<Cautiously, he glances at the Darkfuse guards, then whispers to you.>\n\nI'll tell you whatever I can if you get rid of them.\n\n<He nods subtly towards his alchemy station.>", objectives = "" }
WordHunterWoW_QuestEN[83117] = { title = "Chasing a Lead", description = "Venture doesn't exactly have a history of being an upstanding cartel. Their loyalties can be bought cheap, and they don't got qualms about means justifyin' ends.\n\nWe knew they was working with Gallywix, we just didn't know how deep they were in with him.\n\nLet's go check out those kaja'mite supply lines. No time to lose.", objectives = "" }
WordHunterWoW_QuestEN[83118] = { title = "Check the Schedule", description = "If there's one thing Venture does keep in order, it's their paperwork. They're real particular with dividing their workforce and keepin' everything on schedule. They're efficient, I'll give 'em that.\n\nUp ahead is one of their scrapyards. They should have schedules posted around the place for Venture employees to record their hours worked and see what they got comin' up.\n\nGrab as many as you can find. We'll check out Venture's headquarters in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[83119] = { title = "It's Worth a Shot", description = "Venture Co. has a pretty bad track record, but not everyone workin' for the cartel is bad news. Some of us are tryin' to make ends meet.\n\nMaybe we can talk sense into some of 'em. Less Venture workers means less people doin' Gallywix's dirty work.\n\nVenture Co. employs a lot of non-goblins, so no one will question you bein' around as long as you've got a uniform on. I've got a spare that will probably, mostly, sorta fit you.\n\nSee if you can get 'em to quit. If they start a fight, do what you gotta do.", objectives = "" }
WordHunterWoW_QuestEN[83120] = { title = "Stealing the Keys", description = "If you gotta get to a confidential work site like the Kaja'Coast, you gotta check out a punch card from Krome's office up here.\n\nLead Foreman Krome is one of the big bosses who organizes how Venture's workforce gets split up. \n\nShould be easy enough for Renzik to slip in and grab the punch card, but you'll need to take care of Krome and his guard hyena. If we're gettin' to the Kaja'Coast, let's do it without becomin' chew toys first, yeah?", objectives = "" }
WordHunterWoW_QuestEN[83121] = { title = "Asset Management", description = "I took a quick look inside that mine up ahead while you were gone. Looks like they've got Venture Co. mining out all the kaja'mite and bringin' it down to the beach. It's gettin' packaged up down there, but I couldn't tell where it was goin' afterward.\n\nWe need to cut off the supply at the origin. Deal with the supervisors in the mine, and I'm willin' to bet their workers will have enough sense to run afterward.", objectives = "" }
WordHunterWoW_QuestEN[83122] = { title = "Crashing the Market", description = "When I left the Bilgewater Cartel in charge of the kaja'mite mining in Zuldazar, it was clean and safe. Well, cleaner and safer. We made a lot of deals with the Zandalari to secure that. So not only is Gallywix steppin' on our territory, but he's threatenin' the respect and trust we earned by letting Venture make a mess of this operation.\n\nBlow up the kaja'mite stockpiles you find in that mine. I don't want any dishonest kaja'mite goin' anywhere, no matter who's buyin' or sellin'.", objectives = "" }
WordHunterWoW_QuestEN[83123] = { title = "A Miner Mistake", description = "<On the corpse of the Venture Co. employee, you find a crumpled piece of paper stuffed into an envelope. It appears to be a paystub from a kaja'mite depot in the Venture Co. area of Undermine.\n\nBelow the full address of the employer, there is a header stamped in red ink.>\n\nGALLYWIX'S SECRET KAJA'MITE WAREHOUSE - INTERNAL ONLY DO NOT ACTUALLY PRINT THAT\n\n<A note from Gallywix is poorly taped to the back of the paystub.>", objectives = "" }
WordHunterWoW_QuestEN[83124] = { title = "B.I.R.D. Watching", description = "I took those parts you collected and hotwired the components into some new machinery, then stuffed it back into the bot. Now it can be piloted usin' this remote control. The remote also lets us see and hear anything the bot does.\n\nI don't think we're gonna learn what we need to just by killin'. We're gonna need to beat Gallywix at his own game and spy on his workers.\n\nYou wanna do us the honors, {name}? I'll talk you through it.", objectives = "" }
WordHunterWoW_QuestEN[83125] = { title = "Price Hike", description = "So Noggenfogger wasn't lyin'. Darkfuse strongarmed Steamwheedle into figurin' out how to make kaja'mite contain Black Blood. Looks like that's how they've been gettin' it into weapons without blowin' themselves up--or worse.\n\nThese stakes are higher than I thought, and I get the feeling this goes even deeper. I need to get Noggenfogger somewhere safe. You and Renzik take out that overseer, then meet us back at Steamwheedle.", objectives = "" }
WordHunterWoW_QuestEN[83126] = { title = "Ethereal Invasion", description = "Just moments ago, these ethereals appeared out of nowhere. They attacked Noggenfogger and attempted to haul him off. I made short work of the first attackers, but they keep coming.\n\nNow they're searching every building and killing anyone who stands in their way.\n\nI don't know what they're looking for, but we can't allow them to continue this slaughter.\n\nLet's teach them a lesson.", objectives = "" }
WordHunterWoW_QuestEN[83127] = { title = "Racing the Clock", description = "We were out of time before, but now we're REALLY out of time.\n\nThe ethereals are gonna beat us to the warehouse, but we might still be able to beat them to the Dark Heart.\n\nC'mon!", objectives = "" }
WordHunterWoW_QuestEN[83128] = { title = "Get Our People Out", description = "While Alleria looks for the Dark Heart, we need to look for the hostages. Here's hoping they're still safe.\n\nThey left some ambushers behind, but we got the best of SI:7 on our side. You think you see one of them hidin', point them out to Renzik. He'll toss a smoke bomb. That'll flush 'em out and stun 'em, so we can turn the tables.", objectives = "" }
WordHunterWoW_QuestEN[83129] = { title = "Nowhere Left to Hide", description = "This barricade looks intentional. Hobart said Gallywix went off to a cave, and I'd say this sure looks like one.\n\nGallywix has to have the Dark Heart in there. Help me blast this barricade open and get ready to fight.", objectives = "" }
WordHunterWoW_QuestEN[83130] = { title = "Sour Victory", description = "That's it. It's over. We're done.\n\nGallywix lost, but the ethereals got the Dark Heart.\n\nAlleria needs to track them down. We need to check on everyone back at Bilgewater Flats, and then we need to go. There's nothin' else in this town for us.", objectives = "" }
WordHunterWoW_QuestEN[83137] = { title = "When Opportunity Explodes", description = "There ya are, {name}! Have you heard the latest news? There's a big hole blown in the side of the mountain out by Opportunity Point in the Ringing Deeps.\n\nThere were opportunistic folks taking it over, and now there's even more. We'd better hurry over there.", objectives = "" }
WordHunterWoW_QuestEN[83138] = { title = "End of the Day", description = "Sprinkle and Seahorn are fine. Marin and Hobart are recoverin'. We didn't stop Gallywix, but at least the Dark Heart is... well, it's not in his hands.\n\nWhich means we can leave. Nothin' left for us to do here.\n\nFinish up whatever business you've got in Undermine. I need to get out of this damn place.", objectives = "" }
WordHunterWoW_QuestEN[83139] = { title = "Mixed Messages", description = "Lots of these workers are headed to a Venture camp just down the road. That's a great first stop for information. We'll pay the tollbooth fee. It's best to just play along for now.", objectives = "" }
WordHunterWoW_QuestEN[83140] = { title = "Hostile Work Environment", description = "Bigger and more dangerous than Opportunity Point? These south mines sound real bad, even if ya have a high tolerance for bad working conditions. But what are they mining? Something here is worth big money. We'll need to check it out.\n\nI'll head past the big Darkfuse camp with Renzik, stealth mode. Make a big distraction for us, will ya? I'm sure you can slow down production while you're over there.", objectives = "" }
WordHunterWoW_QuestEN[83141] = { title = "Miner Investigations", description = "What \"riches\" are they mining out of the earth? Could this deep digging be related to my visions? Surely these goblins would not find value in something like Black Blood.\n\nWe must get a closer look. Together we will gain insight into their operation.", objectives = "" }
WordHunterWoW_QuestEN[83142] = { title = "Order of Magnitude", description = "<This document requires anyone with information about who opened the western wall to bring the information to their supervisor. \n\nIt details the reward: a promotion to working inside Undermine. It also includes a promise of the favor and \"appreciation\" of Gallywix.\n\nGazlowe will want to know about this.>", objectives = "" }
WordHunterWoW_QuestEN[83143] = { title = "Good Honest Work", description = "You're new here, right? I can tell by your questions. But don't worry, Zirdo's your best pal!\n\nI'll give you a personalized tour. Gutterville, the Venture Company town, is just south down the road. It'll be informative and interactive. You can't ask for a better experience, trust me!", objectives = "" }
WordHunterWoW_QuestEN[83144] = { title = "Bloodletting", description = "The land aches underfoot. These pipes carry Black Blood north in a massive volume!\n\nI've never seen the land become infected this rapidly. Clear away the rot--perhaps we can save it yet.\n\nI'll go after the structures. Point out weak spots as you find them and I will focus our assault!", objectives = "" }
WordHunterWoW_QuestEN[83145] = { title = "Paranoia Prevention", description = "What information is Gallywix after here in Gutterville? Let's see if some of these goblins will give us a hint. \n\nLet's start with any Bilgewater goblins we can find.", objectives = "" }
WordHunterWoW_QuestEN[83146] = { title = "Pamsy's Prized Pump", description = "I got a team of engineers. All of them got families. They keep having horrible accidents and infections from the Black Blood. I just couldn't stand another death. I opened the wall. I wanted it to bring us some hope.\n\nYou show up and want to stop the Black Blood. It doesn't do anythin' good to stop these pipes up here. We gotta get to the pump station.\n\nSo, my crew and the pumps? They're all at the same station. But we should hurry.", objectives = "" }
WordHunterWoW_QuestEN[83147] = { title = "Bloody Business", description = "The horrors of the Black Blood here cannot be underestimated. The strength of it in this place is causing my visions to feel distant, like odd whispers.\n\nKill the manifestations of this rot, before they grow stronger.", objectives = "" }
WordHunterWoW_QuestEN[83148] = { title = "X-Treme Chill", description = "Pamsy and I came up with an idea. Since we can't access the controls, and we can't blow it up, what if we freeze the pump station?\n\nStay with me!\n\nPamsy mentioned that a lot of the machines up north are overheating lately, because all the coolant is being used down south. And it's even harder to get, because the blood slimes eat it. What if we found all of that coolant supply and dumped it into the pump station? \n\nWe put the whole operation on ice, and it'd take ages to fix!", objectives = "" }
WordHunterWoW_QuestEN[83149] = { title = "Avenge Them", description = "I followed Zirdo's trail south. I found a nasty piece o' work named Gozzic Cogcrane pushin' workers around and talking about \"another lesson.\" Zirdo must have snitched to this Gozzic guy, but I need to confirm it. I think this Gozzic will have the proof on him.\n\nGozzic could've given the orders, but lookin' at that bloody shredder and the marks on Pamsy's crew, I'm sure he got involved personally. You should do the same. Kill Gozzic and check him for any sign Zirdo got word to him.", objectives = "" }
WordHunterWoW_QuestEN[83150] = { title = "Expanding the Plan", description = "Here's the plan. If we just freeze the outside, it'll all melt in a bit and go back to normal. But we got Orweyna. She can target cracks and leaks in the pipes so the coolant can get inside and really muck things up.  \n\nSince you gathered all the canisters, I think you should get the honor of freezing the pipe solid.\n\nPamsy has a rocketboard, and you'll be able to dispense icy justice down upon the station's key areas. Follow Orweyna!", objectives = "" }
WordHunterWoW_QuestEN[83151] = { title = "Down Undermine", description = "We've done what we could here. It's time to get a look at Undermine.\n\nPamsy's got a contact, a Venture goblin named Grimla. We can start there when we arrive.\n\nLet's get Gazlowe and get going. Undermine's not the kinda problem you solve with a knife. We need someone like Gazlowe on board for this. You know, the builder and leader type.", objectives = "" }
WordHunterWoW_QuestEN[83152] = { title = "Magmanagement", description = "As if the pipe going down wasn't enough, a horde of magmatic elementals burst out when it failed.\n\nWe can't risk sending anyone else down to attempt repairs while the area is overrun, but that magma is vital to powering the whole Deeps.\n\nIf you are capable, clear them out so we can get that magma flowing again.", objectives = "" }
WordHunterWoW_QuestEN[83153] = { title = "Sampling Steam", description = "The effects of the magmatic buildup are clear to see, but what we still do not understand is the root cause.\n\nIn order to determine it, and prevent it in the future, I need samples of the volcanic gases you can see bursting from the ground.\n\nFresh samples. Very fresh.\n\nYou're going to have to stand in them as they erupt in order to gather what I need.", objectives = "" }
WordHunterWoW_QuestEN[83154] = { title = "Knicknack's Knickknacks", description = "Not fair! Not fair! Knicknack collect many shiny things over long life. But now stupid wax for brains Candleclaws push out Knicknack and family. Shiny things all left behind!\n\nHere, goblin friend helped made list of all my treasures inside Darkflame Cleft. You go take back!", objectives = "" }
WordHunterWoW_QuestEN[83155] = { title = "Tired of Tripping", description = "All that's between us and the juiciest excavation site I've ever seen is a couple of moles and a leggy deer. Sorry, getting ahead of myself.\n\nSee these shredders? State of the art in the field of maiming and killing. And they keep getting stuck in holes!\n\nListen, I'm as ecologically conscientious as the next goblin, but these moles have got to go. I'm gonna need you to give these hardheads a hard time. And if you see any of my crew, help 'em out, wontcha?", objectives = "" }
WordHunterWoW_QuestEN[83159] = { title = "A Little Off the Top", description = "Ever seen a deepstrider before? This one sure ain't happy to see us. Made quick work of the shredders that made it past the moles. Real shame, those pilots are gonna have to work overtime to pay off the damages.\n\nNow if someone were to take care of it and bring back something as proof, well, I'm sure there'd be a nice payday.", objectives = "" }
WordHunterWoW_QuestEN[83160] = { title = "Cinderbrew Reserve", description = "Trade may have been restricted, but I'll calcify before I let my Cinderbrew Reserve fall into the hands of these stripped screws or go up when some elemental looks at it funny.\n\nThe inspectors are watching me, stranger, so I can't go fetch it myself, but they won't be paying any special attention to you.\n\nI left it behind the desk in my old office, down below.\n\nJust don't get too close to an enforcer or they'll confiscate any cinderbrew you're carrying and I'll be left with nothing to drink.", objectives = "" }
WordHunterWoW_QuestEN[83162] = { title = "Put it Back, Put it Back!", description = "It's going to ruin everything! Who wants to visit a resort with a thirty-foot tall ghost-deer? Ok, no need to panic. It's probably just a little miffed you took its skull.\n\nFirst, you gotta get rid of some of these slimes. Then, get that skull out of here. The farther the better.\n\nOh man, they're gonna get ectoplasm in the hot pools!", objectives = "" }
WordHunterWoW_QuestEN[83163] = { title = "Split Venture", description = "We're headed to my home turf next, Venturewood. It's next to the Heaps.\n\nThe Venture Company is mostly on board for Gallywix. That means a lot of the top brass are as dirty as him. Watch your step.\n\nBut there are some good folks there too. Like Pamsy and her crew. The little guy at Venture gets it rough. Everyone thinks of Venture Co. as just the baddies, so no one looks after them. But I gotta try right?\n\nHop in the hot rod, I'll show you what I mean.", objectives = "" }
WordHunterWoW_QuestEN[83164] = { title = "City of Threads: Splice the Splicer", description = "\"Ascension\" is no true evolution. It is defilement. It is doom. And Ansurek further etches that doom in stone with each passing day.\n\nIf we bring down the Transformatory, then we can potentially rid Azj-Kahet of these abominations for good.\n\nIzo the Grand Splicer is Ansurek's chosen overseer of the Ascension process. Cut that wretch's head from her body, and perhaps these mutations will cease.", objectives = "" }
WordHunterWoW_QuestEN[83165] = { title = "Badly Behaved Bot", description = "Go ahead, laugh. I would be as well if I didn't have such pressing business. My bot's foot clipped a nearby rock, spilled me out and then righted herself. Without me in the cockpit! \n\nI'm grounded while she floats there quite cheerfully. Can you believe it? \n\nListen, if you are heading up to Shadowvein Point, will you let Kagfritha know that I'll be late for my shift? I need to wait for this hunk of metal to run out of fuel and dip low enough for me to get back in the driver's seat.", objectives = "" }
WordHunterWoW_QuestEN[83166] = { title = "Ara-Kara, the City of Echoes: Harvest's End", description = "You've seen it yourself, haven't you? The \"Black Blood,\" as we call it.\n\nWe will not stand idle any longer. Not while Ansurek mutilates, drills, and exsanguinates our precious land for the last, fetid dribbles of the old gods' death rattle. \n\nSeek out the old city beneath us--Ara-Kara, The City of Echoes. You will receive a handsome bounty should you slay the crony in charge of the excavation. Her people call her Ki'katal, the Harvester.", objectives = "" }
WordHunterWoW_QuestEN[83167] = { title = "Eyes from Above", description = "That was rough, with Nikki. And worse, those Darkfuse spy-copters saw everything. Feels like we can't get away from all the spies, don't it?\n\nThe last thing Venture needs is Gallywix thinking these workers ain't loyal 'cause they got caught on footage during one of Nikki's tantrums. We don't want a repeat of what happened to my last crew. \n\nGo take the footage from the spy-copters. They usually lurk around the workshops, or follow Venture workers around.", objectives = "" }
WordHunterWoW_QuestEN[83168] = { title = "A Trail of Black Blood", description = "While you have been getting familiar with the state of Undermine, I have been tracking our prey. The presence of Black Blood is everywhere, hidden behind noisy distractions.\n\nBut this city cannot fool me. I discovered a Black Blood shipment at a place called Hovel Hill, but there were machines guarding it. We should go together.", objectives = "" }
WordHunterWoW_QuestEN[83169] = { title = "Long Way from Booty Bay", description = "There is no doubt about it. These shipments have Blackwater Cartel written all over them... literally. The Black Blood comes in here and then Blackwater takes it somewhere in the city by couriers.\n\nSo if we want to find out where, we go right to the top--Baron Revilgaz. Grimla mentioned Revilgaz has a temporary set up nearby, here in Hovel Hill. Let's go pay him a visit.\n\nThe ethereal thing will have to wait.", objectives = "" }
WordHunterWoW_QuestEN[83170] = { title = "Not Again!", description = "The Darkfuse are moving into Hovel Hill. It's the same thing they did at Blackwater Marina. Once they move in, they start pushing the locals around. Sometimes they just make 'em go away. It ain't right. I want to fight back, but my hands are tied.\n\nIf an outsider showed up and started making trouble, that'd be a different story.", objectives = "" }
WordHunterWoW_QuestEN[83171] = { title = "Eye Sores for Sore Eyes", description = "They call them recruitment posters, but that ain't all they're for. They're there to remind everyone the Darkfuse are in charge and can do whatever they want. If me or one of the locals rip 'em down, it goes bad for us. \n\nBut the Darkfuse hate you anyway. \n\nIf you torched all the posters, I would owe you one.", objectives = "" }
WordHunterWoW_QuestEN[83172] = { title = "Black Blood Baton Pass", description = "Blackwater is just one step on the journey, and they like to keep this stuff moving. Revilgaz has his people take it from the station, hide it for a bit, then deliver it to the drop sites. The drop sites change, but the current one is a depot in the Heaps.\n\nWe're gonna check it out and find out where the Black Blood goes from there.\n \nHe says it's guarded, so look for us out near the edge.", objectives = "" }
WordHunterWoW_QuestEN[83173] = { title = "Clearing Out the Depot", description = "The Heaps are crawling with guards. We've got an opportunity to disrupt the Black Blood operation in Undermine and we should take it.\n\nWe can't stop all the Black Blood from getting around the city, but we can clear out some guards and smash some shipments. Mess them up enough to disrupt things. Every little bit helps.", objectives = "" }
WordHunterWoW_QuestEN[83174] = { title = "Our Good Pal", description = "Our old pal Zirdo's back. It looks like he's been promoted to Overseer of the Heaps, keeping track of the Black Blood shipments.\n\nWe owe him some payback for sellin' us out in Gutterville. He got a lot of good goblins killed to get on Gallywix's good side. Give the little snitch what he deserves.", objectives = "" }
WordHunterWoW_QuestEN[83175] = { title = "Another Piece of the Puzzle", description = "<The ledger has longwinded ramblings about Zirdo's achievements, but also contains various deliveries of Black Blood across Undermine. Multiple entries in the ledger stick out as odd:\n\n- One thousand units for Secret Project, Deliver to Secret Project Site.\n- Twenty units for Developmental Ammunition, Deliver via Courier.\n\nTransfers approved by Noggenfogger of Steamwheedle.>", objectives = "" }
WordHunterWoW_QuestEN[83176] = { title = "Just a Hunch", description = "It's time to sort out what to do next. This Noggenfogger business has Gazlowe on edge and we gotta move quickly to find out what's going on. \n\nSomething's got me on edge too. We should get outta the Heaps fast. But let's make sure Gazlowe's on board.", objectives = "" }
WordHunterWoW_QuestEN[83177] = { title = "Socialized Medicine", description = "It has come to my attention that the most downtrodden residents of the Burrows have fallen prey to some sort of malady.\n\nTake this potion and dose the sick. This will strengthen the citizens and curtail further outbreak.", objectives = "" }
WordHunterWoW_QuestEN[83178] = { title = "Rules and Consequences", description = "I fear I have grown too brazen in my offerings of succor as of late. I seem to have attracted some untoward eyes.\n\nBe on guard. A veiled threat looms.", objectives = "" }
WordHunterWoW_QuestEN[83181] = { title = "Best Friends, Same Ends", description = "I saw the shipwright leave the cave and head down to the beach. She was accompanied by a formidable looking nerubian.\n\nThe shipwright is the mastermind behind this entire operation. She knows precisely how the lumber is to be cut and what lumber is needed for their airships.\n\nThe nerubians know this and likely assigned one of their best to protect her.\n\nIf we can eliminate the shipwright, we can bring all of their carefully laid plans to ruin.", objectives = "" }
WordHunterWoW_QuestEN[83182] = { title = "A Bloody Inheritance", description = "When the kobyss killed my parents, they stole some of their most cherished things. \n\nNot me, obviously. Cherished items. \n\nWhile we are murdering kobyss, let's find them.", objectives = "" }
WordHunterWoW_QuestEN[83194] = { title = "Under Fire", description = "I'm only standing here because of Renzik. He didn't even think about it--he just...", objectives = "" }
WordHunterWoW_QuestEN[83195] = { title = "Rally the People", description = "No one's been stepped on harder by Gallywix than the Bilgewater Cartel. Plenty already want to rise up, but that ain't enough. We gotta show them what Gallywix has done and convince them that now is the time.\n\nLet's start with a headline. C'mon, pitch me. A big shot like you carries our message better than anyone else.", objectives = "" }
WordHunterWoW_QuestEN[83196] = { title = "Disperse!", description = "Gallywix can't hide the truth, but he can beat us down until folks have no choice but to accept it. We ain't lettin' that happen again.\n\nYou see someone hurting a Bilgewater goblin, return the favor.", objectives = "" }
WordHunterWoW_QuestEN[83197] = { title = "Who Owns the Streets?", description = "Her! Nikki the Fixer, Venture Company's top enforcer. Renzik's blood is on her hands.\n\nI can't worry if she's got another bullet. We gotta go after her. You with me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[83198] = { title = "Backyard Navy", description = "Gallywix and his crew have been meddling in our business for too long. Look at what they're doing to my marina! So comfortable with their holdings that they're doing donuts on jetskis!\n\nIt's time we introduce them to a little high seas firepower.\n\nTake this cannon and blow those Darkfuse vessels skimming our waters sky-high. After that, do me a favor and check up on the big guy, won't ya?", objectives = "" }
WordHunterWoW_QuestEN[83199] = { title = "Been Savin' This One", description = "Listen {name}, Sprinkle's been cooking something for a long time that I'm finally ready to cash in. A little alchemist's secret ingredient. Citrus! Delivers twice the kick of Noggenfogger's Restorative Elixirs at half the speed. Strengthens your bones, grows your muscles, does your taxes. The whole nine yards!\n\nProblem is, I've got nothing of the sort on hand. These resort types may have what you need. We've been saving this recipe for a heavy hitter. Make sure Seahorn's alright before cooking it up, yeah?", objectives = "" }
WordHunterWoW_QuestEN[83200] = { title = "A Vast, Ye Swabs", description = "Urgh. I've been locked up for so long. In my anger, I got reckless.\n\nWhatever Noggenfogger gave ya, I promise not to squander. Get me back in the fight and we'll bring the full swell of Blackwater's might down on these invaders.", objectives = "" }
WordHunterWoW_QuestEN[83201] = { title = "Expedited Delivery", description = "Blackwater can take the marina from here. But the people aren't safe with Black Blood that's already out there.\n\nThose flying transports must be taking the Black Blood somewhere under Venture Co. control. Commandeer one, and you might find Grimla. She was headed in that direction when we split up, shouting that a friend of hers was on the way.", objectives = "" }
WordHunterWoW_QuestEN[83202] = { title = "Punching Up", description = "The time for talking out our differences is over. I'm done second-guessing who is still standing with Gallywix.\n\nSome of Nikki's people are keeping these new weapons in production. So, we take them out. It makes cleaning up Venture Co. after all this is done way simpler too. \n\nJust be careful. Nikki won't stick her neck out for her lieutenants, but she'll take the chance to rig a fight against you.", objectives = "" }
WordHunterWoW_QuestEN[83203] = { title = "Weapons Hot", description = "The destructive impulses of those who harvest Azeroth for their own profit never cease to horrify me. But these weapons are like nothing that has come before.\n\nAll containers of Black Blood must be overturned and destroyed. Weapons fueled by it crushed and dismantled. Those who wield it against others, put down. The people of this city, and this world, won't be safe until we do.", objectives = "" }
WordHunterWoW_QuestEN[83204] = { title = "The Thingamajig", description = "Nikki's tech is powered by Black Blood. I know that because I worked on half of it. That also means I have an idea on how we might knock her out of the sky for long enough to take her out. \n\nNo time for pre-production. We gotta build.\n\nRemember our flashy little hoverboard adventure? Ice is nice, eh? I'm thinkin' of a similar principle--the trash heap oughta have all the salvage we'll need to build this hypothetical thingamajig.", objectives = "" }
WordHunterWoW_QuestEN[83205] = { title = "Production Halted", description = "<Orweyna rubs her palms with dirt, then cracks her knuckles.>\n\nNow, we teach those who toy with Black Blood nature's wrath. I am eager to call upon the roots twisting through Azeroth.\n\nJoin me. Unleash nature's fury as we did before. Let us destroy their prized stockpiles of Black Blood.", objectives = "" }
WordHunterWoW_QuestEN[83206] = { title = "We Own the Streets", description = "The trade princes ain't exactly been fair to the goblins here, so this can't be just another cartel war. The crowd needs to know they ain't fighting for Bilgewater or Steamwheedle. \n\nThey're fightin' for Undermine. \n\nWe need someone who ain't a cartel big shot to help rile 'em up and keep 'em safe. Do whatever it takes to get them to the Gallagio and show these goblins this is their city.", objectives = "" }
WordHunterWoW_QuestEN[83207] = { title = "My Top Gal", description = "We've got Gallywix backed against the wall. Seeing Undermine and its people he's kept under his thumb finally rising up.\n\nHe thinks this \"Fixer\" of his will keep him safe. Let's show Gallywix, Nikki, and everyone else that things are different this time.\n\n<Gazlowe looks over the thingamajig he's just finished jury-rigging.>\n\nWatch this.", objectives = "" }
WordHunterWoW_QuestEN[83240] = { title = "The Theater Troupe", description = "Since you're an honorary member of the theater troupe, {name}, what do you think about playing a part in our plays?\n\nNo big parts--I don't want to upset the rest of the troupe by taking away their limelight. You know how they are.\n\nAre you available, say, once a week?", objectives = "" }
WordHunterWoW_QuestEN[83247] = { title = "Suspicious Minds", description = "For many years, the only non-Arathi we ever saw in Hallowfall were trying to kill us. Nerubians, shadow creatures, beasts. So, forgive me if I view your sudden arrival with suspicion.\n\nHowever, my better half would urge me to be more welcoming... and I want to try to be better. For her.\n\nSome of the salamanthers in Rumshackle have been bothering us. Kill them and bring me proof.", objectives = "" }
WordHunterWoW_QuestEN[83271] = { title = "There's Always Another Secret", description = "After me da' did whatever he did, the titans' machines are back online--even the ones here in Dornogal.\n\nDagran was havin' enough fun with Brinthe askin' her a thousand questions, but now he's helpin' her sort through the Archive.\n\nAn' now he wants your help. He was too excited to tell me why, but he wanted ye to meet him in the Archive.", objectives = "" }
WordHunterWoW_QuestEN[83275] = { title = "Gear Enchanting", description = "Hello, outlander!\n\nI've heard of your exploits since your dramatic arrival on our shores. We earthen welcome your aid.\n\nI can teach you how to enchant your gear with resources from my land. To defeat our enemies, every bit of power helps.", objectives = "" }
WordHunterWoW_QuestEN[83276] = { title = "Saving Private Spindle", description = "One of my weave-rats has failed to check in for an unusually long time. I sent Spindle to retrieve information we could use against one of Ansurek's favored wretches, but she has not returned from her assignment.\n\nMeesk the Venomtongue is a wretch and a sycophant, but he is dangerous all the same. While I have much trust in my dear Spindle's abilities, I fear what a malefactor such as Meesk would do to one of my little ones should he find them.\n\nFind Spindle. Make sure she is well.", objectives = "" }
WordHunterWoW_QuestEN[83277] = { title = "Personal Pilfering", description = "<The little spider looks around the room, each of her eyes narrowing.\n\nYou recall The Weaver telling you to retrieve evidence to blackmail Meesk.\n\nBut it appears as though ransacking Meesk's storage is now personal for Spindle.>", objectives = "" }
WordHunterWoW_QuestEN[83278] = { title = "Hillhelm Family: A Lost Shoe", description = "<A shoe in the style worn by members of the Hillhelm family.  Maybe Aliya Hillhelm can shed some light on it.>", objectives = "" }
WordHunterWoW_QuestEN[83279] = { title = "Prove One's Mettle", description = "Yes, you helped us out with these pests, but it is not enough. I need more.\n\nOne of the areas near our town has been overrun by shadow. If you are truly not being controlled by your... strange background, you would have no problem destroying the source of this danger, would you?", objectives = "" }
WordHunterWoW_QuestEN[83282] = { title = "Hillhelm Family: A Clutch of Eggs", description = "<A clutch of chicken eggs, they must have come from a nearby farm.  Maybe Aliya Hillhelm can shed some light on it.>", objectives = "" }
WordHunterWoW_QuestEN[83283] = { title = "For Morale", description = "Please excuse my husband's rudeness. When we signed up for our expedition, we expected to be away from our families for a few years at worst. Instead, we settled here as we guard against--well, against the end, against Renilash. Who knows when our watch will end?\n\nI've been stockpiling a cache of wine from our church vineyards to share with everyone when tensions got high. My hiding place, Rumshackle, has been overrun by creatures. Can you get the wine for me?", objectives = "" }
WordHunterWoW_QuestEN[83285] = { title = "The Ancient Scroll", description = "A haze seems to obscure the details of the scroll at first. As you concentrate on making out the scroll's features, the haze briefly dissipates revealing a pristine scroll made of the finest vellum, with a seal that looks so fresh the wax doesn't even seem set yet. In a blink, the scroll feels dangerously brittle, and the seal so delicate it could crack at any moment. As the haze begins to form again, you see the scroll shimmer through all possible points between these two extremes.", objectives = "" }
WordHunterWoW_QuestEN[83286] = { title = "What's Hidden Beneath Dornogal", description = "Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence.\n\nDagran's query may have to wait.\n\nI have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal.\n\nPerhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.", objectives = "" }
WordHunterWoW_QuestEN[83306] = { title = "Where the Wild Things Camp", description = "Some of my people found a few haranir setting up one of their camps to the southwest. They were missing some vital supplies, so my people offered to help out. However, I worry about how they're all getting along over there.\n\nCould you check in on them? Make sure we're being good hosts to the haranir... and that nobody has inadvertently offended anyone. Please.", objectives = "" }
WordHunterWoW_QuestEN[83315] = { title = "Preparing for the Unknown", description = "This will be a long process. Longer, I fear, than Dagran can stay here in the Isles.\n\nBut perhaps... \n\nThere are many titan relics I can use as \"keys\" to unlocking information in the mainframe or to repair it. That may make the process go more quickly.\n\nOnly time will tell.\n\nYou have helped us enough, {name}. Go back to Moira and tell her what we have discovered.", objectives = "" }
WordHunterWoW_QuestEN[83321] = { title = "Strange Bats", description = "Hey. Her ladyship has a lead on some really strange bat that was flying around the Wormlands. \n\nThe spies reported it behaving more like a person than a bat. We think we might have a druid out there, but it ain't revealin' itself to the nerubians on purpose.\n\nYou have one of those faces that make people hesitate before punching. Head out there and take a look.", objectives = "" }
WordHunterWoW_QuestEN[83322] = { title = "The Dawnbreaker: The Christening", description = "The flagship of the Arathi armada is the Dawnbreaker. She is a marvel of Arathi engineering and faith in the Sacred Flame. Her presence in the Hallowfall sky will help us push back the nerubians when next they dare launch another assault on our lands.\n\nAs someone who has helped us so much in the past, you are cordially invited to the christening ceremony of the Dawnbreaker. If you could make sure it goes off without a hitch, you will have my personal gratitude.", objectives = "" }
WordHunterWoW_QuestEN[83324] = { title = "A Silken Thread", description = "You looking for work or something? <Linny squints her eyes at you.> If you're just hanging around I've heard some whispers from the capital. An associate of the Weaver is looking into some business in the Silken Ward.\n\nThe new ward is supposed to be a fresh start for citizens of the capital but the Queen's Pale Weavelashers have been treating it like a military camp. This isn't sittin' well with the populace.\n\nMeet with a nerubian named Sum'latha outside the ward. She can fill you in on the details.", objectives = "" }
WordHunterWoW_QuestEN[83325] = { title = "Bountiful Beetles", description = "General Anub'azal has great plans in motion for the swarmery, Rak-Ush. He intends to return it to working order, to support his war campaign.\n\nHowever... I have my reservations about the two he left in charge. \n\nKish'nal seems to have a good head on his shoulders, but Vix'aron? Volatile is an understatement. They may require some... prodding.\n\nSeek out Kish'nal at Rak-Ush and follow up on Anub'azal's orders.", objectives = "" }
WordHunterWoW_QuestEN[83326] = { title = "The Final Candle", description = "You are good candle-taker. \n\nWe have one last job for you, your waxiness! One more job! Then no more sticky business. \n\nBIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. \n\n<There's an awkward pause.>\n\nNothing rhymes with kobolds, hm. \n\nGet us big candle!", objectives = "" }
WordHunterWoW_QuestEN[83328] = { title = "The Analysis Interface", description = "This is the Analysis Interface. \n\nIn order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. \n\nAlthough Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully.\n\nProceed when ready.", objectives = "" }
WordHunterWoW_QuestEN[83331] = { title = "Preserve and Pretend", description = "Chive dig for history. You help find? \n\nGot history detector from goblin. Said it finds history underground! You use. Chive dig.", objectives = "" }
WordHunterWoW_QuestEN[83333] = { title = "Gearing Up for Trouble", description = "Greetings friend,\n\nThe machine is once again in disrepair and requires restoration. \nI am in need of your expertise to successfully perform maintenance.\n\nA reward shall be provided for well-executed assistance.", objectives = "" }
WordHunterWoW_QuestEN[83334] = { title = "The Wealth of an Empire", description = "", objectives = "" }
WordHunterWoW_QuestEN[83335] = { title = "Wanted: The Boroughbreaker", description = "<This note is nailed into the post with a small chitinous plate.>\n\nFor crimes impeding the Edicts of Dornogal, the Council has deemed a reward be yielded to any who slays the chitinous beast known as Stik'kar.\n\nA sample of Stik'kar's armor is attached. If you are unable to damage it, you are urged to carry on in your duties and leave this task for another.", objectives = "" }
WordHunterWoW_QuestEN[83336] = { title = "The Earthwound", description = "<Etterca grumbles as you approach.>\n\nGround is shaking. 'Tis no good.\n\nTroubles are awakening the elements again. Stirs rot in them. Danger to us all. Bring them to heel and give its heart here.\n\nOnly then the earth can begin to heal. Only then can Etterca do her duties.", objectives = "" }
WordHunterWoW_QuestEN[83337] = { title = "Stormscarred", description = "Take a look around this beautiful town. What do you see? Ranchers 'n' their mosswools. But where  is this rancher's flock? In the guts of a beast, they are. Stormscar they call 'im. \n\nStormscar, whose howl is as the thunder. Whose bite is lightning. Whose belly is full of my life's work. \n\nI came here to buy weapons and all we have is ranching equipment. You look strong. Would you put an end to Stormscar's reign in our pastures?", objectives = "" }
WordHunterWoW_QuestEN[83338] = { title = "The Mage Slayer", description = "I confess I have come here with reason. There is one entity that may be out there still that cannot be allowed its freedom.\n\nA prisoner from the Violet Hold that we begrudgingly know as the Mage Slayer. I had come to request aid from these people, but they are farmers and ranchers. I hope you are better equipped for a challenge.\n\nSeek out this fiend and put an end to its existence.", objectives = "" }
WordHunterWoW_QuestEN[83339] = { title = "The Spirebreaker", description = "We are no strangers to nerubian attacks. The Kirin Tor is well equipped to handle such a threat. Dalaran...\n\nWas equipped. I cannot fend off all of this town's foes, but you might be able to. I spotted an ambush near the road on the way here. An all too familiar tactic of an all too familiar foe. Go spring the trap and slay the  monster that lurks below.", objectives = "" }
WordHunterWoW_QuestEN[83417] = { title = "Out-laws", description = "We're a traditional goblin family, an' my sweetie's intended's from one too. Young people start work on a contract, an' buy each other out when they get hitched so they can get time off.\n\nI've got the cash for my sweetie to buy her intended's contract out, but it would be... embarrassin' if her intended didn't have the moolah for my perfect peach's contract, ya know?\n\nGo talk to that kid and make sure he's set for the big day. And if he's not? Fix it.", objectives = "" }
WordHunterWoW_QuestEN[83418] = { title = "The Perfect Coat", description = "My princess deserves only the very best Azeroth has to offer--and that goes double for her clothes. How else are people supposed'ta know how incredible I think she is?\n\nI got a guy who's hooked me up with an amazin' and rare pelt for my little girl to turn into a fabulous coat. Go meet the guy and bring back the goods. And you better not get anythin' on it.", objectives = "" }
WordHunterWoW_QuestEN[83419] = { title = "The Perfect Guest List", description = "The perfect weddin' has the perfect guest list!\n\nBut I'm still waiting on some RSVPs. Papa said he'd make sure they showed up, so that means you gotta remind them they'd love to come to my weddin'. It's gonna be the biggest bash this town has ever seen! Why wouldn't they want to come? We're family! Mostly.\n\nAnyway, get everyone on this list to agree to come to my weddin'. Remind them Papa said \"or else.\"", objectives = "" }
WordHunterWoW_QuestEN[83420] = { title = "Catering to Perfection", description = "My perfect day needs the perfect food! I've been looking at things on Gobstagram, and Chef Hardslice is my one and only choice for catering. Papa promised I'd have the best, and he's good to his word!\n\nI need you to make sure that everything on my menu makes it to the table for picture perfection. Everyone needs to see how fabulous my wedding is. \n\nAhh! I am so excited! I can't wait to see Chef Hardslice's creations on my table at my wedding!", objectives = "" }
WordHunterWoW_QuestEN[83421] = { title = "The Perfect Wedding", description = "I hired some goons to crash the wedding. Only the best weddings get crashed, right?\n\nBut, I don't want to lose my deposit on this here venue. So, I need you to stop my crashers from getting too crashy, ya know?", objectives = "" }
WordHunterWoW_QuestEN[83432] = { title = "The Rookery", description = "My contacts around Dornogal have told me to keep this a secret, but I trust you mainly because I need someone to do the job.\n\nWe have a problem within the Rookery's walls--a skardyn outbreak.\n\nI need someone to clear the Rookery of skardyn, find the source of the outbreak, and drop the boulder on it.\n\nOnce you complete the mission, come back to me for your reward.\n\nAnd remember... this stays between us.", objectives = "" }
WordHunterWoW_QuestEN[83436] = { title = "Cinderbrew Meadery", description = "Word has come from a contact of mine named Wenbrandt. You may have heard of him. He runs the Cinderbrew Meadery.\n\nHe says that goblins affiliated with an organization calling itself Venture Co. are trying to take over the meadery. We cannot have that. I need you to get into the meadery and remove that threat.\n\nCinderbrew is an earthen product and should be under earthen control. Wenbrandt will teach them this lesson--but until then, I will count on you to finish the job.", objectives = "" }
WordHunterWoW_QuestEN[83442] = { title = "Tossed and Torqued", description = "All my notes. My plans!\n\n<Snap is shaking with anger.>\n\nI just know it was Mite Sparkcog who tossed my apartment. He's my work rival and probably wanted my newest invention for himself--the Smellersweller 5000!\n\nIt's an attachment for the grills we design. I'd just finished the schematic for our boss when I stepped out for some grub. By the time I got back...\n\nMaybe he didn't find it. Help me look first, then we can deal with Mite.", objectives = "" }
WordHunterWoW_QuestEN[83443] = { title = "Darkflame Cleft", description = "A new ally of ours, a kobold from the Ringing Deeps named Skitter, has contacted me.\n\nI need you to go to Darkflame Cleft and remove a certain threat--something that Skitter called The Darkness.\n\nHow can a kobold be afraid of the darkness when they spend most of their time underground? It makes no sense to me. But kobolds will be kobolds, and I will not busy myself with understanding.", objectives = "" }
WordHunterWoW_QuestEN[83445] = { title = "Something Smells", description = "Ooh! That Mite makes me so mad! He even took credit for it. An' I was right. He's going to present the Smellersweller to our boss!\n\nIn fact, he's probably presenting it right now!\n\nThat gives me an idea though. We may not have the schematic, but Mite won't know how to operate it. If we can show the boss it's not Mite's design, maybe I'll still get credit!\n\nHow good are you at pressing buttons? Will you help me present the prototype?", objectives = "" }
WordHunterWoW_QuestEN[83446] = { title = "Cease and Desist", description = "Our presentation showed that we were the ones that could actually operate the device! If Sammy weren't so focused on the documentation bein' in Mite's hands... Anyone else could clearly see we had made the thing even if we didn't have the schematics!\n\nBut this ain't over. You saw how Mite overloaded the Smellersweller? We can do that too! Punch a bunch of buttons all at once and we can exploit his half-baked, all-stolen idea!\n\nWe go in, we mess up the prototype, an' we set production back months!", objectives = "" }
WordHunterWoW_QuestEN[83457] = { title = "The Stonevault", description = "I have a job for you from High Speaker Brinthe herself.\n\nThe skardyn corruption is taking over the Stonevault. To contain the panic, High Speaker Brinthe has asked us for help. I told her she could trust us like we trust the bedrock under our feet.\n\nGo to The Stonevault and remove the skardyn corruption. Let me know when the job is done.", objectives = "" }
WordHunterWoW_QuestEN[83458] = { title = "Priory of the Sacred Flame", description = "Good to see you, {name}. I have a job just for you.\n\nSister Etna Blayze of the Arathi is convinced that something is wrong within the Sacred Flame Priory. She did not expand on the matter at hand.\n\nPlease head out to the Priory of the Sacred Flame and join the sister. A stomach pebble tells me she might be right and will need your help.", objectives = "" }
WordHunterWoW_QuestEN[83459] = { title = "The Dawnbreaker", description = "I have received word from General Steelstrike of the Arathi. She asked for you to attend a ceremony aboard The Dawnbreaker.\n\nBy attending, she means she needs an extra pair of eyes--maybe two or five. Have you ever secured a ceremony before? It feels like a puddle of sticky mud down in the Forgegrounds.\n\nI'm sorry, but General Steelstrike asked, and I replied with a simple \"yes.\" As the saying goes, not every hill is going to be exciting.", objectives = "" }
WordHunterWoW_QuestEN[83465] = { title = "Ara-Kara, City of Echoes", description = "Tulumun, an agent of a new contact known as the Vizier, has approached us.\n\nI never expected a nerubian to come to us for help, but what they brought to our attention could threaten us all.\n\nI will need you to descend into Azj-Kahet and infiltrate Ara-Kara, the City of Echoes. If what Tulumun told me is true, we cannot let whatever they have woven down there escape.\n\nPut an end to their operation. Bring back evidence of what you find.", objectives = "" }
WordHunterWoW_QuestEN[83469] = { title = "City of Threads", description = "Tulumun, our Nerubian ally, contacted us once again. He spoke of a place called the Transformatory where horrific experiments take place.\n\nI will need you to infiltrate the city and then rendezvous with the Vizier himself for the rest of the mission. \n\nEliminate the Vizier's enemies, end the threat, and return to me for your payment.", objectives = "" }
WordHunterWoW_QuestEN[83484] = { title = "Oh, Rats!", description = "Okay, scout's honor this ain't a joke. I need help because... \n\nI turned my best friend into a rat.\n\nMy friend Allie is the cook here. She tries her best but she's... no good. She's got a bum sniffer. So, I bought her a potion that would make her smell better!\n\n...I mean, improve her sense of smell. But it turned her into a rat! Then she ran off!\n\nYa gotta find her for me. Dealer had another potion to understand rats. I'm too afraid to drink it though.\n\nCan you use it an' find her?", objectives = "" }
WordHunterWoW_QuestEN[83485] = { title = "Potent Potables", description = "<sniff> <sniff>\n\nThis potion has the scent of the Vatworks on it. There's a vendor at the northern edge there who sells potions. It must be from him. If you can find him, maybe you can get him to hand over an antidote.\n\nPlease help. You're the only one who can understand me!", objectives = "" }
WordHunterWoW_QuestEN[83486] = { title = "Remote Work", description = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. \n\nIf you're here to collect on a debt, you are TRESPASSING and must disregard this note.\n\n-Getry", objectives = "" }
WordHunterWoW_QuestEN[83487] = { title = "Occupational Hazard", description = "<You surmise that collecting enough redberries and returning them to Humphrey should allow Alice to turn back into her usual goblin self.>", objectives = "" }
WordHunterWoW_QuestEN[83489] = { title = "Gathering All Gladiators!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", objectives = "" }
WordHunterWoW_QuestEN[83492] = { title = "Warbands: Warbanding Together", description = "{name}, some adventurers have gotten together to form a warband and could use your help.\n\nFind Blue and her group in Gadgetzan.", objectives = "" }
WordHunterWoW_QuestEN[83493] = { title = "Warbands: Rift Reader", description = "I bet you're wondering what we're working on, huh? We're going to make our Warband Bank accessible from anywhere!\n\nRivet's calling it a Warband Bank Distance Inhibitor until I can think of something more fun, but we need a little help to get it over the finish line.\n\nIf we're going to make sure we can access our shared stash from multiple locations, we're going to need portals! And we tracked some doozies down out here.\n\nIf you could get us some scans of the local anomalies, it'd be a big help!", objectives = "" }
WordHunterWoW_QuestEN[83494] = { title = "Warbands: Space Ghosts by the Coast", description = "There are an awful lot of half-teleported things wandering around the desert not too far from here. Really, any at all would be a surprising amount, but there are a bunch of them for some reason!\n\nThey don't seem particularly nice, but I bet we could learn from their predicament to ensure the Warband Bank Distance Inhibitor doesn't teleport our sweet loot into a tree!\n\nSee if you can find anything that might help us figure out what went wrong. It's not like people randomly teleport around, right?", objectives = "" }
WordHunterWoW_QuestEN[83495] = { title = "Warbands: Twinsposition", description = "We're on a roll! We picked up an even more anomalous anomaly while you were out and tracked it down to just west of town.\n\nWe've got a brand-new Transpositional Signal Recombobulatron already set up out there, but I didn't want to start without you. You've been a big help, after all.\n\nAll you have to do is dial it in and throw the switch! Easy as pie, which I'm told is very easy.\n\nRivet says that the odds of something cataclysmic happening are pretty good, so I know nothing bad can happen!", objectives = "" }
WordHunterWoW_QuestEN[83496] = { title = "Warbands: Spacetime is Money", description = "Now that we've got all the transpositional data we could ever hope for, all we need to do is set up a wormhole in a suitable banking establishment and we'll be dropping gear into each other's pockets from the field in no time!\n\nAnd there just happens to be a bank right here in Gadgetzan!\n\nYou can even attune your own portal at the same time so you can access your own Warband Bank from anywhere. It's going to be so convenient!", objectives = "" }
WordHunterWoW_QuestEN[83497] = { title = "A Concerned Friend", description = "Ah, {name}, there you are! Great Kyron was asking after you and your friend Anduin. \n\nI think they want to talk to you about Faerin. Nothing urgent mind you, she probably just needs some good company. But we're all a bit worried about her.\n\nCheck in with Kyron when you have a moment, will you?", objectives = "" }
WordHunterWoW_QuestEN[83499] = { title = "Arcane Wasteland", description = "Kirin Tor survivors have been hesitant to return to this area. A great deal of energy was dispelled before and after Dalaran's crash. An invisible yet tangible miasma lingers in the area for those who are sensitive to it.\n\nIt is unclear if the site is hazardous or if other more corporeal dangers still lurk here.\n\nI can protect us, but I expended all my reagents at the Proscenium. Will you aid me in procuring more?", objectives = "" }
WordHunterWoW_QuestEN[83500] = { title = "Zekvir, Hand of the Harbinger", description = "We'll have tae watch out for Zekvir as we go exploring into delves. I don't think we're strong enough tae take him on just yet, but we will be!\n\nLet's keep explorin' and gettin' treasure until we're tough enough tae track down his lair and defeat him.", objectives = "" }
WordHunterWoW_QuestEN[83502] = { title = "Lessons in Defensive Magic", description = "The spell for the barrier is ready, but I must channel it and define its perimeter. \n\nWhile I channel the spell, take these wards and place them at the edges of our would-be barrier.\n\nWe will empower the spell when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[83503] = { title = "Return to Dornogal", description = "The battle is finally over and I suppose it's time we lick our wounds. \n\nHead back to Dornogal, Champion. \n\nI'll be right there as soon as Khadgar is healthy enough to withstand travel.", objectives = "" }
WordHunterWoW_QuestEN[83519] = { title = "But What About the Casino?", description = "Times are a changing. Now that ol' Jastor is kaput, the cartel heads are chomping at the bit to settle the fate of Undermine's crown jewel: the Gallagio.\n\nThere's a court proceeding tomorrow to make a final determination, but luckily the deed is squarely in the hands of someone I trust. \n\nTheir name: Rosebud Gallywix.\n\nI know. I know. But Rosey is a good egg. I'll introduce you to him later on.\n\nFirst, do me a favor. Ask the power players here at the party how they feel about the new owner.", objectives = "" }
WordHunterWoW_QuestEN[83521] = { title = "Little Help, Please?", description = "So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light.\n\nI just got that fixed. I swear it!\n\nWould you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it.\n\nShouldn't be more than a minute. Two at most!", objectives = "" }
WordHunterWoW_QuestEN[83522] = { title = "Debting For A Living", description = "First of Rosebud's Chiefs on our list are the genius gaming duo: Kayjay and Fantastic Davey.\n\nNow, I heard from my wife's brother that Venture Co. bought up all the debt those boys got. Happened the minute Rosebud was done in.\n\nDid they murder him? Not a great motive if their debt was sky high, but you never know whose pocket a goblin is in either. \n\nBest we see how comfortable they are here at the ol' Venturewood landfill. If they don't want to sign the new deed, we might have our culprits!", objectives = "" }
WordHunterWoW_QuestEN[83524] = { title = "Gold In Them There Trash", description = "Kayjay and Davey are indeed masters of creating games. They've created a new one for me that's been an absolute hit.\n\nIf you're willing to accept the risk, then I will give you the chance to win their employment, and debt, from me.\n\nGrab a pickaxe, and enter the landfill. When the whistle blows, you'll compete against all my other \"employees.\"\n\nWin by the final bell, and I'll let these two go. Lose, and I'll own you.\n\nIt's called Slot Mining. And it will indebt you to me for life.", objectives = "" }
WordHunterWoW_QuestEN[83527] = { title = "Winning is for Losers, Anyway", description = "This is the worst job I've ever had. And I used to work Turtle Toss at Darkmoon Faire.\n\nWe're not imprisoned here physically with shackles, but Tarbonara owns all of our debts. He imprinted the information on Debt Markers, which his goons hold on to in case any of us want to know where we stand.\n\nBut if you get a hold of those markers, we're all free. You'd have to crack some skulls to get them though, so I'll give you points for each of his goons bring down.\n\nYou like collecting points, don'tcha?", objectives = "" }
WordHunterWoW_QuestEN[83528] = { title = "All Part of the Game", description = "Look. I know we're the ones that incurred our own debts, but Rosebud believed in us! With him, there was a light at the end of the casino floor.\n\nWith him gone... We're just two halves of a gaming genius, working for hire instead of salary.\n\nBut Zoomcart told us there's still a chance we could work the Gallagio. Is that true? If it is, Davey and I are in.\n\nProblem is that Davey and I's Debt Markers are held by the gaming commissioner himself: Kudd Milktooth. And he's deep in Tarby's pocket.", objectives = "" }
WordHunterWoW_QuestEN[83529] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "" }
WordHunterWoW_QuestEN[83530] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "" }
WordHunterWoW_QuestEN[83531] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "" }
WordHunterWoW_QuestEN[83532] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "" }
WordHunterWoW_QuestEN[83534] = { title = "Ain't No Warm Up Act", description = "Can't believe Revilgaz scheduled us first! No one shows up for the first band!\n\nWhatever. You the one that oldhair Marty mentioned? He already gave me the lowdown on your plan to keep the Gallagio from going to auction. Seems ridiculous. Which makes it our kinda plan.\n\nLet's make a deal. Our manager dumped us when the casino deal went south, so YOU are gonna fill in for her today. Don't worry, couldn't be worse than any other job you've done.\n\nFirst thing on your list: gather us a crowd.", objectives = "" }
WordHunterWoW_QuestEN[83535] = { title = "Plunder Party Rockin' Rumble", description = "Here! Take this Mecha-Trianbell!\n\nI don't care that you can't play an instrument because you WILL be playing this one.\n\nWhile we're jamming, members of rival bands will storm the stage to stop us. \n\nNot only will the Trianbell ring out in perfect pitch, it'll also blast anyone not in our band all the way to the cheap seats.", objectives = "" }
WordHunterWoW_QuestEN[83539] = { title = "Feeling Blue", description = "I fear... that it may just be me that remains, {name}. Or that the others are too far away to receive my missive.\n\nIt may be up to us to build an outpost here and see to the cleansing of the crash site.\n\nSo be it. It is just as well...", objectives = "" }
WordHunterWoW_QuestEN[83540] = { title = "Work the Line", description = "Not sure if your schnoz picked up what mine did on the drive over, but there were some delightful smells coming from the street below. \n\nProblem was, the crowds were too thick for me to find Gobdre anywhere.\n\nThat's where Noggy comes in. He's a pretty important fella these days, so I figure he'd have some sorta in for us.\n\nHe's generally an unfeeling scientist-type who doesn't spill secrets. But his pride is also fragile as my wife's Rumble figurines. \n\nGive it a poke and he should spill.", objectives = "" }
WordHunterWoW_QuestEN[83541] = { title = "Review Bombed", description = "Show me you ain't just talk.\n\nI give Diner Cards to each customer. They're supposed to fill it out with their reviews on my menu, and return it here. But I haven't seen any yet. \n\nFishy much? Definitely. And not the kind I like.\n\nGo. Fetch. Get my reviews back. I ain't budging an inch in the Gallagio's direction without them.", objectives = "" }
WordHunterWoW_QuestEN[83542] = { title = "Quick Gills for Gold Now", description = "Ah, crabs... I knew this would happen.\n\nThe diners overwhelmingly scored one dish above all others: pan-seared deepwalker thigh with blood-spiced confit algarian orbinid.\n\nLong name, right? I was hoping that would dissuade the customers from writing it on their cards.\n\nTrouble is that I can't make pan-seared anything without a pan, now can I? And I sold my best pan when the Gallagio deal fell through.\n\nWant me back on board? Then get my pan. Those deepwalker thighs ain't gonna sear themselves.", objectives = "" }
WordHunterWoW_QuestEN[83543] = { title = "Adventuring in Khaz Algar", description = "We've got scouts in every corner o' Khaz Algar, an' they all report the same thing: trouble.\n\nSeems we got here just in time, eh?\n\nCheck the scouting map on the table behind ye and lend a hand where ye can.", objectives = "" }
WordHunterWoW_QuestEN[83546] = { title = "Responsibility", description = "Today's the day for shiny shoes, {name}!\n\nWe've got our deed signatures. We've got support from the cartels. And we've got... my kids.\n\nMy wife was supposed to come with us today as well, but she slipped in the shower! Can you believe that? She'll be at the chiropractor all morning. I feel awful for her. Absolutely awful.\n\nWelp! Her loss! Let's pack up what we need and I'll drive us all over to the court room!", objectives = "" }
WordHunterWoW_QuestEN[83547] = { title = "Welcome to the Neighborhood", description = "<A letter has been left in your mailbox. The handwriting is neat and smoothly flowing.>\n\nWelcome to Borogrove, {name}! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood.\n\nOnce you've settled in, please come see me at Town Hall.", objectives = "" }
WordHunterWoW_QuestEN[83548] = { title = "Isle of Dorn", description = "Survivors from the attack on Dalaran are beset by nerubians led by Queensguard Zirix.\n\nLend your aid to protect whomever remains.", objectives = "" }
WordHunterWoW_QuestEN[83550] = { title = "The Ringing Deeps", description = "Speaker Brinthe has gone to The Ringing Deeps to see how the Machine Speakers have fared while she was away.\n\nShe has asked for adventurers to join her at the bottom of the Coreway.", objectives = "" }
WordHunterWoW_QuestEN[83551] = { title = "Hallowfall", description = "Anduin Wrynn hopes to gain the trust and aid of the Arathi in Hallowfall.\n\nHe will need help to win over these potential allies.", objectives = "" }
WordHunterWoW_QuestEN[83552] = { title = "Azj-Kahet", description = "An Arathi airship is stranded in Azj-Kahet following a vicious nerubian ambush.\n\nAid the survivors as they withstand the nerubian assault.", objectives = "" }
WordHunterWoW_QuestEN[83553] = { title = "Magic-stealing Kobolds", description = "I'm afraid that our \"clean up\" of Dalaran extends far from the shores of the Isle of Dorn.\n\nIn my attempts to find you, I circled this island many times. During my flight, I sensed the magic of many familiar items--items that were formerly housed in Dalaran.\n\nDangerous items.\n\nSomeone or something has taken them who knows where. We must find these objects before innocent bystanders come to harm.\n\nFollow me.", objectives = "" }
WordHunterWoW_QuestEN[83554] = { title = "Trinkets, Curios and Other Powerful Objects", description = "The kobolds here could get up to untold mischief with the items they have stolen.\n\nTake what you can back from them by... whatever means you see fit.\n\nWhile you deal with the kobolds around Mourning Rise's grave sites, I will go underground and search Kriegval's Rest and do the same.\n\nMeet me near Kriegval's Rest when you have secured the Kirin Tor artifacts the kobolds stole.", objectives = "" }
WordHunterWoW_QuestEN[83555] = { title = "Mysterious Necklace", description = "<The gem pulses with arcane energy, hinting at ancient magic woven into its very core.>", objectives = "" }
WordHunterWoW_QuestEN[83556] = { title = "Maybe You Shouldn't Touch That", description = "This necklace...\n\nIt is clearly full of powerful magic, but... it is elusive--as if it is hiding its origin from me.\n\nYou take another look. Maybe there's something obvious I'm missing.", objectives = "" }
WordHunterWoW_QuestEN[83558] = { title = "Casino Court", description = "I'm all set to make our case. Just one tiny, little, minor thing to let you know about...\n\nThere's a bomb under my desk here.\n\nDon't be alarmed! It ain't the first time this has happened. But there's a lot of people here, and I'd hate to interrupt the proceeding for one little explosive.\n\nTake this X-Plo-Dar 64k. Use it to trace the bomb's signature back to the goblin with the trigger.\n\nMy lawyer's instinct is telling me that the culprit behind this explosive is also Rosebud's killer. Just a hunch.", objectives = "" }
WordHunterWoW_QuestEN[83563] = { title = "Coffee is for Closers", description = "You've got us the hard evidence we needed. All that's left to do is reveal Rosebud's killer to the judge.\n\nI imagine Tarbonara won't go down lightly, so be prepared for one of any number of goblin-like reactions.\n\nYou know what I mean. Explosions or cannons or crying or casino heists or whatever. I'm not worried though, you seem capable.", objectives = "" }
WordHunterWoW_QuestEN[83565] = { title = "Weekly Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83566] = { title = "Oh, That Casino!", description = "You'd make a good lawyerer, you know that?\n\nHah! Just kidding! The real industry secret is that there's no such thing as a good lawyerer!\n\nWhy don't you join me at the Gallagio's entrance? It'll be a nice send off for the kids who are gonna run this place now.\n\nNot to mention that we should actually hand them the notarized deed!", objectives = "" }
WordHunterWoW_QuestEN[83569] = { title = "Death and Taxes", description = "He just... exploded...\n\nIf a goblin's gotta go, that's the way. All I can say for poor Rosey. And that I'm gonna miss him. AND that we're gonna find out who did this!\n\nBut the more immediate pickle is this: Who owns the Gallagio now?\n\nIt's time to turn to an expert on legal mumbo jumbo. The State of Undermine assigned a public defender to us for the court case tomorrow, a fella named Zoomcart. He's all we got.\n\nTake what's left of the deed to his office in Hovel Hill, and sort this out.", objectives = "" }
WordHunterWoW_QuestEN[83587] = { title = "Our Chance to Strike", description = "<The child-like spider presents you with a sealed scroll. The sealed letter bears the markings of the Vizier.>\n\nThe balance of power is shifting in Azj-Kahet. The Queen grows more unstable by the day and I fear we must act before our opportunity to stop her slips from our grasp. \n\nMeet me at the Royal Apothecary when you receive this letter.", objectives = "" }
WordHunterWoW_QuestEN[83616] = { title = "The Entrenched", description = "And now the other piece to this coup.\n\nI've been operating under Grand Overspinner Antourix's mandibles for a while now. She's entrenched in Rak-Ahat, and thinks nothing can touch her at the top. She has already refused to submit to Ren'khat.\n\nEven she knows that if Ren'khat has the backing of the throne then it is only a matter of time. Let us expedite her attempts to oust this upstart.\n\nSee how quickly they turn on each other.", objectives = "" }
WordHunterWoW_QuestEN[83627] = { title = "The Beginning of Something Beautiful", description = "<This seems like it would be of interest to a nerubian alchemist. \n\nAscension is their specialty, and this may be key to understanding more about the process.>", objectives = "" }
WordHunterWoW_QuestEN[83628] = { title = "Tense Recovery", description = "Things with these strangers are... tense. We do appreciate being allowed to take cover here in their camp. But they only seem to tolerate us at best. We offered to share our supplies, but that offended them, somehow.\n\nMy sister is gravely wounded. I can see herbs I could use to help her in that tent over there, but that giant snail is blocking the entrance. I can't get to them.\n\nI asked the guard on the hill for aid, but all he did was glare. I don't know what to do! Perhaps he'll listen to you?", objectives = "" }
WordHunterWoW_QuestEN[83629] = { title = "Ancient Respite", description = "This was once a great lake. Over time the roots ruptured its floor, and drained the water away. I have lived here for all of my lifetime and witnessed it all. But now, darker changes have come.\n\nSometimes changes comes with death. Decay is natural.\n\nBut the mites that feed upon my people are not. They spread an odd infestation that makes my bark feel like it crawls from my body.\n\nDestroy these mites, so that I may rest without fear of their mouths upon my sleeping form.", objectives = "" }
WordHunterWoW_QuestEN[83632] = { title = "Rings of Memory", description = "I appreciate what you have done. Do not worry--I am not finished yet.\n\nIf you please, take this root to those who sent you. They can read the history of my life within the rings of wood therein. My life is one of many in the tapestry, but we are all intertwined. \n\nThese strangers you encountered may be reclusive--secretive even--but they understand this tapestry like no other, and guard it with their lives.", objectives = "" }
WordHunterWoW_QuestEN[83639] = { title = "Open Communications", description = "You understand that others lead lives different to your own. Our ways restrict us. Our traditions are not for the ears of strangers. I have only spoken to you at all due to Orweyna's word. But I can feel On'hiea's disapproval from here.\n\nIt is uncomfortable to have mysteries at times. It is why so many fear the dark. It is unknown.\n\nI know I must seem cryptic. But our ways do not mean we are offended by the Arathi. They are creating tension where it does not exist for us.", objectives = "" }
WordHunterWoW_QuestEN[83641] = { title = "Trapped Between Life and Death", description = "A pocket dimension. This is old magic.\n\nMalygos used pocket dimensions on occasion when he did not wish to be disturbed.\n\nThey were mainly used by mages as research spaces or for testing dangerous spells. Or if a mage wanted to hide what they were doing...\n\nI wonder who made this one? I suppose it doesn't matter. We need to get out. \n\nThankfully, every pocket dimension has an exit. Though, it is normally well hidden.\n\nLet's find it.", objectives = "" }
WordHunterWoW_QuestEN[83643] = { title = "Somehow We Survived", description = "What we experienced in Kel'Thuzad's pocket dimension is a timely reminder of what can happen when magic is used without regard to ethics or regulation.\n\nTo me, this underlines the importance of the Kirin Tor.\n\nBut, on the other hand, Kel'Thuzad was Kirin Tor. It is also a reminder of how power corrupts.\n\nNow that we have made sure these artifacts will not cause anyone else to go on an unexpected trip... Let's return to Aethas. \n\nPerhaps now more have responded to his letter.", objectives = "" }
WordHunterWoW_QuestEN[83711] = { title = "Weapons of Conquest", description = "Tales of your prowess have reached even me, hero. If you fight as well as they say you do - then I reckon you would be even better with one of my creations. Write your name in history. Return when you've proven yourself both skilled and honorable.", objectives = "" }
WordHunterWoW_QuestEN[83716] = { title = "Beneath the Roots", description = "I am glad to see you are well, {name}. I have recently received word that a number of the Aeroknights have taken shelter in a camp close to where the airship was seized in mid-air. \n\nWould you check on them?", objectives = "" }
WordHunterWoW_QuestEN[83719] = { title = "Those Are Chitin Words", description = "Well now, this is certainly an interesting specimen. It seems the original creator who worked on this creature made grave errors in balancing the genetic materials. No wonder the creature you encountered was an abomination. What terrible technique!\n\nWith the right materials however, I may just be able to perfect it. Siesbarg here will be our test-subject. Perhaps his Ascension will finally catch the attention of those in charge of administering promotions!", objectives = "" }
WordHunterWoW_QuestEN[83720] = { title = "Venom? More Like Get 'Em", description = "Now that we've acquired enough chitin samples to splice into the perfect armor, we need the perfect venom. Don't look at me like that. Our forms should always be powerful and capable of defending themselves!\n\nI'll begin incorporating the new carapace requirements for Siesbarg's Ascension while you harvest what I need. Do keep in mind though, it must be nerubian venom, specifically. I'm afraid beetles and spiders simply won't do this time around. \n\nAs for where you find it, well that's up to you.", objectives = "" }
WordHunterWoW_QuestEN[83721] = { title = "A Small Ocean's Worth of Blood", description = "Excellent! The end draws near! But although we near completion, we cannot go without the most important part of this genetic equation--the blood. We need a small ocean's worth of nerubian blood. \n\nHowever, to make this new form foolproof, the blood must come from the strongest nerubians to exist. Whether skyrazor or Ascended, it doesn't matter. This will guarantee we have the best genetic material available.\n\nThe kind of material that Siesbarg deserves!", objectives = "" }
WordHunterWoW_QuestEN[83722] = { title = "Consolation Flies", description = "Well... that's unfortunate.\n\nIt appears my experiment has failed and Siesbarg paid the price. Still, I am optimistic for the future I am destined to acquire. It's only a matter of time until I perfect my process. When I do, perhaps I shall engineer my own Ascension!\n\nWhile his physical form isn't what I intended, it appears Siesbarg's mind is intact. I'm certain he can still be of use. Take him. His new form can provide better service on the field of battle than in my tiny shop.", objectives = "" }
WordHunterWoW_QuestEN[83723] = { title = "A Helping Hand", description = "Kalecgos's hypothesis that Dalaran's debris interferes with long-range teleportation seems correct.\n\nMage portals have appeared along the shore, but no one has stepped through them. There are likely mages trapped within the portals.\n\nOr, something mana hungry--like felhunters--may be being lured here by the release of Dalaran's power.\n\nWe must investigate. Mages of the Kirin Tor may be in danger. The felhunters are an acceptable risk.\n\nLet us not waste any more time.", objectives = "" }
WordHunterWoW_QuestEN[83742] = { title = "Call to Attention", description = "Hail, soldier. General Anub'azal requests your presence at Siegehold immediately. He requires your expertise in the investigation of a sensitive matter.\n\nI am not at liberty to say more here. Seek out the General for further briefing.\n\nFor Azj-Kahet.", objectives = "" }
WordHunterWoW_QuestEN[83743] = { title = "Arcane Cold War", description = "A few mages have come but... I expected more to act on Aethas's call to action.\n\nBut perhaps that was wishful thinking.\n\nWe need more help despite what you and Kalecgos did at Mourning Rise. Aside from Kel'Thuzad's pendant, the kobolds' plunder was middling-powered artifacts.\n\nMeanwhile, there have been reports of powerful magical objects filtering through Azj-Kahet, meaning the nerubians must have scavenged Dalaran's crash first!\n\nWe must find these artifacts before they are used against us.", objectives = "" }
WordHunterWoW_QuestEN[83749] = { title = "Delves: The Waterworks", description = "What a trip! Can ye believe how much exists below the depths here? \n\nThe Machine Speakers were telling me of problems they're having over at a place called the Waterworks. Sounds like kobolds are making trouble again. They're also storing some treasure deeper within the place.\n\nWhat do ye say? Let's go on an adventure and help out these folks!", objectives = "" }
WordHunterWoW_QuestEN[83750] = { title = "Wanted: Zuramat the Obliterator", description = "_", objectives = "" }
WordHunterWoW_QuestEN[83752] = { title = "Threats of Zekvir", description = "Someone's watchin' us, {name}. They put this chest here for us to find.\n\nLet me know when you're ready. I'll trigger the trap here to see just what exactly is going on.", objectives = "" }
WordHunterWoW_QuestEN[83753] = { title = "Cannon Karma", description = "This is gettin' serious, {name}! Those pirate goons have a cannon and are threatenin' to blow us outta the sky!\n\nBut this may also be an opportunity.\n\nIf youse get rid of the monkey firin' the cannon, we maybe can get control of it for ourselves for some payback!", objectives = "" }
WordHunterWoW_QuestEN[83755] = { title = "Delves: Nightfall Sanctum", description = "Good tae see you again! I've run into a bit of a mess since we last met.\n\nSome nerubian called \"Zekvir\" wants the expedition to stop explorin' this land. You know what that means. We've got to explore even more!\n\nThese Order of Night cultists might have information regarding Zekvir. Let's go to Nightfall Sanctum and see what we can find out.", objectives = "" }
WordHunterWoW_QuestEN[83758] = { title = "Delver's Call: Fungal Folly", description = "We've got more reports of fungarians returning to a place we've dubbed \"Fungal Folly.\"\n\nExplore the cave and eliminate any threats you find.", objectives = "" }
WordHunterWoW_QuestEN[83759] = { title = "Delver's Call: Kriegval's Rest", description = "HELP WANTED\n\nKriegval's Rest has become overrun by kobolds! This once sacred resting place of the earthen must be restored.", objectives = "" }
WordHunterWoW_QuestEN[83761] = { title = "Delves: The Underkeep", description = "Who would've thought I'd be cozying up in a nerubian's lair!\n\nThere's a nasty named Zekvir threatening folks trying to explore the island. I've been asking the Weaver for any information she's got.\n\nSupposedly, there's a place called the Underkeep that might have records on him. Let's check it out and see what we can find!", objectives = "" }
WordHunterWoW_QuestEN[83762] = { title = "Critical Mass", description = "This is exactly what I had feared.\n\nThalen Songweaver's notes on the mana bomb he devised to devastate Theramore were under guard in Dalaran. Few knew of this.\n\nI argued they should be destroyed. But others argued if such a bomb was again created, we would need them to disarm it.\n\nAnd now those notes are both the problem and the solution. \n\nThankfully, I have read these notes, {name}. I will walk you through disarming the mana bomb.", objectives = "" }
WordHunterWoW_QuestEN[83763] = { title = "Preserve the Legacy", description = "The larger threat has been contained, {name}, but I believe there are still other artifacts important to our legacy--good and bad--here in Azj-Kahet.\n\nWhile they are still dangerous, their knowledge may benefit us in the long run. And, we must not allow the nerubians to profit from what they and Xal'atath did to Dalaran.\n\nLeave no dark corners here in the Breathing Pit unexplored, {name}.", objectives = "" }
WordHunterWoW_QuestEN[83764] = { title = "Too Powerful, Too Dangerous", description = "Some of the relics the nerubians now possess were housed in carefully-designed containment vaults on Dalaran. That is how dangerous and powerful they are.\n\nWith those vaults gone, the only course of action we can take is to destroy them.\n\nIn hindsight, it seems a grave mistake to have gathered so many powerful artifacts in one place--even if that place was Dalaran.\n\nI would trust no one else with this task, {name}. Find and destroy those artifacts.", objectives = "" }
WordHunterWoW_QuestEN[83766] = { title = "Delver's Call: Dread Pit", description = "Two things are bad for business. Earnest competition and the Dread Pit caves. We need someone to deal with the latter!\n\nSomething bad is going on here. We lost a bunch of workers in this cave.\n\nWe need you to deal with the threat, so we can keep business booming!", objectives = "" }
WordHunterWoW_QuestEN[83767] = { title = "Delver's Call: The Sinkhole", description = "We have reports of large amounts of kobyss gathering towards a lair called the Sinkhole. There are concerns they plan to attack the smaller coast villages when they get the chance.\n\nThere's a hefty reward for anyone who can go into the Sinkhole and stop whatever they're planning!", objectives = "" }
WordHunterWoW_QuestEN[83768] = { title = "Delver's Call: The Skittering Breach", description = "Call For Any Who Can Swing a Sword or Sling a Spell!\n\nThe nerubians perform foul rituals in the shadow of our once beautiful Aegis Wall. Word is that a dark temple dedicated to their cursed gods rests beneath the ground. \n\nSomeone must investigate this foul place and put an end to their schemes.", objectives = "" }
WordHunterWoW_QuestEN[83769] = { title = "Delver's Call: Mycomancer Cavern", description = "Spice Help Needed!\n\nFungarians in the Mycomancer Caverns have been raiding spice crates bound for Lorel's Crossing. Someone needs to go into those caverns and push back the fungarian menace! \n\nWill pay well.", objectives = "" }
WordHunterWoW_QuestEN[83770] = { title = "Delver's Call: Spiral Weave", description = "A lot of us survivors have heard stories about the Spiral Weave. Seems like it's a place where the nerubians have some heavy military operations going on.\n\nTaking the fight to them would help put a serious dent in the nerubians' war plans.", objectives = "" }
WordHunterWoW_QuestEN[83771] = { title = "Delver's Call: Tak-Rethan Abyss", description = "WEAVER'S ORDERS\n\nThe Tak-Rethan Abyss continues to be a place of great unrest and trouble.\n\nSomeone must keep the threats in check before they interfere with our plans.", objectives = "" }
WordHunterWoW_QuestEN[83773] = { title = "Farewell, City of Magic", description = "Not all the Kirin Tor's issues can be solved in one day.\n\nBut one way we can act is to honor those who have fallen. After speaking with everyone here, we have cobbled together a ceremony to send off those we have lost... and Dalaran.\n\nWe would be honored if you would join us and participate in remembering our fallen comrades in the Kirin Tor.", objectives = "" }
WordHunterWoW_QuestEN[83775] = { title = "Infinite Growth II", description = "", objectives = "" }
WordHunterWoW_QuestEN[83776] = { title = "Infinite Growth III", description = "", objectives = "" }
WordHunterWoW_QuestEN[83777] = { title = "Infinite Growth IV", description = "", objectives = "" }
WordHunterWoW_QuestEN[83794] = { title = "Soggy Celebration Crate", description = "<The crate is pretty wet and smells a bit fishy, but looks to be mostly sealed tight. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[83825] = { title = "Restoring A Grand Tale", description = "It was terrible! My book was shredded, and the pages flew everywhere! \n\nI saw some caught in the sand devils that went down the tunnel, others caught on adventurers heading out to face the big monsters in Tanaris, and others are scattered around here. Maybe that bird thing of yours could find them?\n\nPlease help me get the pages back so I can restore my book!\n\nOh, and watch out for that shady Cravitz Lorent. He's selling new copies for a hundred gold under the Fashion Frenzy stage. Robbery!", objectives = "" }
WordHunterWoW_QuestEN[83827] = { title = "Silence the Song", description = "The sirens... they're out there! And I wonder... was it the crystal or these creatures that the Kul Tirans named this isle after?\n\nWhichever it may be, these sirens' call has lured many of our forces to their doom.\n\nOur goblin allies have prepared a device to remove the control they have over our troops.\n\nEliminate these \"sirens\" and dispel the charm that holds our troops captive.", objectives = "" }
WordHunterWoW_QuestEN[83832] = { title = "Torn Dreams", description = "Hello again! I could really use your help here. \n\nA visitor by the name of Addie Fizzlebog had a book damaged by some time devils that swept through here last night. I am still dealing with all the other problems they caused and was hoping you could help Addie with her issue.", objectives = "" }
WordHunterWoW_QuestEN[83931] = { title = "Battered Celebration Crate", description = "<The crate is pretty battered. It looks like at least one wolf chewed on its corner. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[83932] = { title = "Historical Documents", description = "Imagine having the chance to accompany Sky-Captain Elaena Lancekat on such a great adventure. This is the opportunity of a lifetime!\n\nBut if I'm going to write a book about this journey, I need to gather some historical information about this island.\n\nPerhaps you could collect any notes or documents that you find? Anything might be useful and tell us about the history of this place!", objectives = "" }
WordHunterWoW_QuestEN[83933] = { title = "The Kaja'Coast", description = "Alright, we got the punch card to the Kaja'Coast and a pretty good reason to believe Venture's shmoozin' up to Gallywix a lot more than we thought.\n\nNoggenfogger said we'd find answers at those mines, and that means goin' down to the Kaja'Coast for a look.\n\nLet's go. We'll meet you over at Slam Central.", objectives = "" }
WordHunterWoW_QuestEN[84001] = { title = "Cart Blanche", description = "Our mining team is making great progress. All our carts have already been loaded with ore samples and sent back to camp. \n\nThere's a problem though...\n\nNone of the carts made it to camp due to trouble on the tracks!\n\nPlease repair the tracks and collect any lost ore if you can so we can get those samples to camp.", objectives = "" }
WordHunterWoW_QuestEN[84020] = { title = "A Mech in Need", description = "This mechsuit has seen better days. Maybe a skilled Machine Speaker could assist you. \n\nI know Speaker Jurlax has been assigning machinists to mechsuit maintenance lately. He probably has some advice for you.", objectives = "" }
WordHunterWoW_QuestEN[84021] = { title = "Machine Without Cogs", description = "Diagnosis: This machine's movement is impaired.\n\nWe must get it moving again. I'm going to need some replacement parts. The gears must keep grinding.", objectives = "" }
WordHunterWoW_QuestEN[84022] = { title = "Uniting Severed Threads", description = "You have done well to ally Anub'azal and Nizrek to our cause.\n\nIt is time that we solidify this triumverate relationship between us all. We will conference via shadecasters. Activate them when you're ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[84023] = { title = "Orienting Ourselves", description = "The machine moves without intent.\n\nLet us guide it toward purpose.\n\nDeliver direction unto this device.", objectives = "" }
WordHunterWoW_QuestEN[84024] = { title = "Clutching Control", description = "The machine breathes without life.\n\nWe must provide ours.\n\nFind a conduit for the will of the divine.", objectives = "" }
WordHunterWoW_QuestEN[84025] = { title = "Repurposed, Restored", description = "", objectives = "" }
WordHunterWoW_QuestEN[84084] = { title = "Just a Pinch", description = "Dust is the foundation of the art of enchantment. Where novice enchanters turn up their noses at such a common material, a master understands its versatility.\n\nBring me Storm Dust. No matter our expertise, we must always return to the fundamentals.", objectives = "" }
WordHunterWoW_QuestEN[84085] = { title = "The Power of Potential", description = "As enchanters, we do not merely trade in runes or wands. Our true commodity is potential. We take the power of possibility and infuse it into tangible forms.\n\nFor this, Gleaming Shards are essential. I require several to continue my work.", objectives = "" }
WordHunterWoW_QuestEN[84086] = { title = "A Rare Necessity", description = "Occasionally, we are called upon to provide our greatest and most powerful boons. For these, I require a Refulgent Crystal.\n\nTrue, such crystals are rare, but necessary for us to reach the heights of our art. Worry not, it will not be squandered.", objectives = "" }
WordHunterWoW_QuestEN[84121] = { title = "A Little Insurance", description = "There are too many Darkfuse guardin' this place for us to sneak around them. We're gonna have to thin 'em out the old fashioned way.\n\nTake out as many Darkfuse as you can. Me and Gazlowe will do some reconnaissance.", objectives = "" }
WordHunterWoW_QuestEN[84122] = { title = "Cut the Cameras", description = "Gallywix ain't an idiot. He's got those surveillance birds keepin' an eye on this entire area.\n\nWe're gonna need to bring 'em offline if we wanna keep a low profile--and by that, I mean smash 'em to itty bitty pieces.\n\nIf you need help grabbin' them outta the air, use this auto-grappler. Oh, and scoop some of their parts up for me when you're done. I've got an idea.", objectives = "" }
WordHunterWoW_QuestEN[84123] = { title = "Test", description = "Test", objectives = "" }
WordHunterWoW_QuestEN[84127] = { title = "Blacksmithing Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84128] = { title = "Engineering Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84129] = { title = "Inscription Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84130] = { title = "Jewelcrafting Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84131] = { title = "Leatherworking Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84132] = { title = "Tailoring Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84133] = { title = "Alchemy Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", objectives = "" }
WordHunterWoW_QuestEN[84140] = { title = "Can-Do Caddy", description = "So, my \"company\" was subcontracted to provide services for the golf course here.\n\nOnly, it turns out the materials we used in our patented, explosive-proof grass has drawn a swarm of coursehares. Which is inconvenient 'cause they're the only type of rodents that can eat the grass.\n\nI need a can-do caddy I can sub-subcontract out the elimination of this threat to my business. So tell me, can you?", objectives = "" }
WordHunterWoW_QuestEN[84141] = { title = "Scam Cans", description = "Look, I run a clean business here... when I'm paid to.\n\nBut, I've gotta swathe of cheatin' no gooders tryin' to plant scam cans in the holes. The things cause the balls of cheaters to get drawn into 'em, cheapenin' the game.\n\nCan't have that. \n\nGet out there, find the scam cans, and get them gone.", objectives = "" }
WordHunterWoW_QuestEN[84142] = { title = "The Hole Deal", description = "Okay, well now that's settled, how about you get a free go, eh?\n\nHere at...\n\n<Ripsnoodle pauses to look at notes he digs out of his pocket.> \n\nEmerald Hills Golf Course, we pride ourselves on everyone gettin' a hole-in-one!\n\nEspecially since our boomballs explode after the first swing. So make 'em count.\n\nGo take a few balls out and give the course a whack.", objectives = "" }
WordHunterWoW_QuestEN[84143] = { title = "Lost and Busy", description = "Thank the Light, an adventurer!\n\nPlease, you must help me. Event coordination is a harrowing profession in the best of circumstances. I am drowning in crises!\n\nThere was a small tuskarr child in need of assistance, but I have my hands full here. I last saw her headed to Leeroy's Chicken.", objectives = "" }
WordHunterWoW_QuestEN[84144] = { title = "Tat Big Meanie", description = "Tat big meanie stole my brovver's sleufing fingy! We need to find who it was and make them give it back!\n\nI fink it was lost past da potty over there.\n\nHere, my unco has this old bird idol that can look for clues! You can borrow it 'cause you look helpy.", objectives = "" }
WordHunterWoW_QuestEN[84214] = { title = "The Job", description = "Want money? Good at smashing stuff? Not afraid of a little morally grey wealth acquisition?\n\nWell then Entrepreneur Inc. has a gig for you!\n\nCome on down to our headquarters in the Heap and speak with Skedgit Cinderbangs for more details.", objectives = "" }
WordHunterWoW_QuestEN[84215] = { title = "The Crew", description = "You are hired!\n\nOkay, this heist I got planned is gonna make us a lot of money, but requires a crew and a bunch of planning.\n\nI'll take care of the planning, you get the crew. \n\nWe need Goldmine. Outside of Venture Co., he's one of the fastest drivers out there. Because he's outside of Venture Co., he can't be traced back to me.\n\nWe also need a face that no bruiser can say no to. We need Handsome Crog.\n\nOh, and I need my cousin Ripsnoodle. He's not the best mage, but he's family... and my boss.", objectives = "" }
WordHunterWoW_QuestEN[84216] = { title = "The Play", description = "I'm gonna go over the details of the plan.\n\nHowever, here is the too-long-didn't-listen version: \n\nWe meet in front of the Airship Station in Bilgewater's district.\n\nHandsome Crog helps get us past the guards to the airship supply balloon there.\n\nWe steal that balloon and use it to board the airship over the arena where the safe with all that loot is.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[84217] = { title = "The Highst", description = "Okay, we got this.\n\nMe, you, and loudmouth here are going to hop this service balloon and get up to that airship over the arena.\n\nThat is where they are keeping the loot. Once we get aboard, fighting space will be tight. I got us some uniforms so we'll look like people who work there but try not to start anything.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[84218] = { title = "The Getaway", description = "Okay... um... I \"may\" have lied about the loot.\n\nYou can be mad at me all you want but we need to get away now. \n\nGet in the car! We have to gun it!", objectives = "" }
WordHunterWoW_QuestEN[84220] = { title = "Passage to the Ringing Deeps", description = "", objectives = "" }
WordHunterWoW_QuestEN[84221] = { title = "Paperwork Makes the Mine Go Under", description = "Name is Marty. Marty Zoomcart. Marty Zoomcart, public defender, and agent assigned to the Gallagio's case for State of Undermine.\n\nWhat a mouthful... Just call me Marty.\n\nSo the deed holder, Rosebud Gallywix, is dead? And no one knows whodunnit. And some nobody, you, has the deed? Frankly, it's a common occurrence. Plenty of precedent. Just no time...\n\nHere's the skinny: if we don't attach some new legal owners to the deed, it's getting put up on the auction house like a pair of decade-old pants.", objectives = "" }
WordHunterWoW_QuestEN[84222] = { title = "Secure the Perimeter", description = "A veritable menagerie of dangerous creatures have attacked us since we set up our encampment.\n\nWhile my troops can manage most threats, some of the more powerful creatures may require your expertise.\n\nScour the island and eliminate any powerful entities that might jeopardize our operations here.", objectives = "" }
WordHunterWoW_QuestEN[84223] = { title = "Survivor's Guilt", description = "We have all suffered from Xal'atath's deeds, some more than others.\n\nI am glad to be alive, even if I now feel as old as I look.\n\n<Khadgar tries to laugh but coughs instead. He waves off your worry.>\n\nDon't worry about me. But Aethas... \n\nI've heard he went back to Dalaran's crash site. And that he hasn't slept or eaten since we arrived.\n\nHe wants my help, but I haven't been able to bring myself to visit the crash site.\n\nWill you go in my stead?", objectives = "" }
WordHunterWoW_QuestEN[84224] = { title = "To Delves!", description = "There's more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", objectives = "" }
WordHunterWoW_QuestEN[84225] = { title = "Eggstinction", description = "We should really get outta here, but...  \n\nDo you see those eggs over there? If those monsters hatch them all, this place will be swarming with crabs when the storm clears.\n\nUgh, there's just too many to destroy by hand. We're gonna need some help!\n\nSuzie's got a lot of helpful items back at the camp... or maybe my broiler will work? I dunno, champ. Grab somethin' to get rid of those eggs!", objectives = "" }
WordHunterWoW_QuestEN[84236] = { title = "The Great Detective", description = "Adventurer, thank the Light you are here. We have a missing guest.\n\nThere was a detective who was investigating the case, but I have not heard back. Could you please check in with him?", objectives = "" }
WordHunterWoW_QuestEN[84237] = { title = "The \"Great\" Detective", description = "The missing guest? Yes, some Herrkrop fellow. Not to worry, I've already solved the case.\n\nHe probably just got lost. Relax, {class}. Enjoy the festivities! Our missing guest will show up soon enough.\n\nIf you don't believe me, go... I don't know... solve it yourself. Interrogate someone or other.", objectives = "" }
WordHunterWoW_QuestEN[84241] = { title = "Shoreline Stand", description = "This storm will not drive me from my sacred duty. This cave must be defended at all costs!\n\nThis new crystal may still be shrouded in mystery, but we will never understand its secrets or its relation to Beledar if we allow it to fall into the grasp of these wretches who crawl from the ocean's abyss.\n\nStand with me, {name}. Together, we shall defend this shoreline to our final breath.", objectives = "" }
WordHunterWoW_QuestEN[84242] = { title = "Diving into the Heaps", description = "Our first marks are the dynamite duo of gaming: Kayjay and Fantastic Davey.\n\nBeen a few years since I was hustling macaroons in the electro-billiards halls. I wasn't bad, but those two cleaned the house out whenever they showed.\n\nThey don't just win games either. They make them! Real artist-types, you know?\n\nBut with great gaming, comes great debt. And it's usually to Venture Co.\n\nMeet me at the Heaps. If Rosebud's death means they're outta work, I'd bet money Venture scooped 'em up again.", objectives = "" }
WordHunterWoW_QuestEN[84244] = { title = "Blackwater Beach Blast", description = "You've done good work with Jojo. Real good. \n\nI'll stick around, seal the deal, then meet you over at Blackwater Marina for the final signature. \n\nHad my radio turned to WGOB 101.1 FM while dropping off the fifteen landfill-scented individuals earlier. DJ B. B. Rev announced there would be a battle of the bands at the marina today. \n\nWouldn't you know it, Rosebud's Chief Executive of Entertainment is playing! The band you're looking for is the Cellar Gnomes.", objectives = "" }
WordHunterWoW_QuestEN[84246] = { title = "Witnessing Brilliance", description = "The time has finally come and the moment could not be more exhilarating. It's time to get to work.\n\nJoin me outside, let's observe the fruits of our labor.", objectives = "" }
WordHunterWoW_QuestEN[84248] = { title = "A Ritual of Runes", description = "I went to investigate a cave nearby, and I came across some Bloodwake vrykul that were conjuring something... something that activated my threat mitigation protocols.\n\nI calculate that if they complete their ritual, it would be disastrous for the island.\n\n{name}, please assess the cave and stop their ritual before something terrible occurs!", objectives = "" }
WordHunterWoW_QuestEN[84249] = { title = "A Vat in the Pan", description = "Our next mark is Jojo Gobdre, in the Vatworks. \n\nShe was a big time chef. The real deal. And running cuisine at the Gallagio woulda meant franchise opportunities. Is there a reason she'd want Rosebud dead?\n\nEither way, we need a lead on where she's cooking these days. Luckily, I got an ol' pal who should have info. He's a little bit of a big shot for Steamwheedle, but we should be able to find him on his rooftop hideaway.\n\nWe'll meet there. Come hungry.", objectives = "" }
WordHunterWoW_QuestEN[84252] = { title = "Peak Precision", description = "Flying? It ain't for me.\n\nSally Boltwrench wanted me to activate a bunch of survey machines to monitor the wind currents, but it's too rough up there and the heights give me the heebie jeebies. \n\nAn' I get sick every time I try.\n\nUse the Go-Pack to activate the machines for me. I'll owe ya one!", objectives = "" }
WordHunterWoW_QuestEN[84253] = { title = "[depreciated] Blacksmithing Orders Requested", description = "", objectives = "" }
WordHunterWoW_QuestEN[84254] = { title = "Meet and Greet", description = "Greetings, salutations, and happy anniversary!\n\nI am Yllana, the conductor of this symphony of celebration. I trust you are itching for fun and entertainment? Well do not fret, for there is much to do and plenty of time to do it.\n\nI've marked your map with the locations of my gleeful greeters who will tell you all about the activities in store for you. \n\nOnce you've talked to them, return to me for a gift that will maximize your merriment. After all, what's a celebration without presents?", objectives = "" }
WordHunterWoW_QuestEN[84260] = { title = "Crafting to Order", description = "Hello, greetings, and welcome to the Crafter's Enclave.\n\nAccording to Market Reeve Vokgret, we are now operating with the Artisan's Consortium to accommodate the needs of both the earthen and the outlanders.\n\nPlease speak to Ardran or Pordaz to view and place crafting orders.", objectives = "" }
WordHunterWoW_QuestEN[84274] = { title = "Crafting Orders: Blacksmithing", description = "So you are a blacksmith? You should have mentioned that earlier!\n\nLet me send you to Darean, a blacksmith of great renown, who has her shop within the Forgegrounds. I will mark it on your map. \n\nDarean has her very own Blacksmith's table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "" }
WordHunterWoW_QuestEN[84278] = { title = "Tracking Quest", description = "Good news! We have a lead. Rexxar has agreed to help us find Scrapes. If anyone can track down that undead murderer, it's him.\n\nRexxar has followed the scent to the Borean Tundra. He left this note for you.", objectives = "" }
WordHunterWoW_QuestEN[84279] = { title = "Crafting Orders: Jewelcrafting", description = "So you are a jewelcrafter? You should have mentioned that earlier!\n\nLet me send you to Makir, a jewelcrafter of great renown, who has a shop on the southern part of the Forgegrounds. I will mark it on your map. \n\nMakir has his very own jeweler's bench where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "" }
WordHunterWoW_QuestEN[84280] = { title = "Crafting Orders: Leatherworking", description = "So you are a leatherworker? You should have mentioned that earlier!\n\nLet me send you to Marbb, a leatherworker of great renown, who has her shop on the eastern side of the Forgegrounds. I will mark it on your map. \n\nMarbb has her very own leatherworker's bench where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guilds. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "" }
WordHunterWoW_QuestEN[84281] = { title = "Crafting Orders: Tailoring", description = "So you are a tailor? You should have mentioned that earlier!\n\nLet me send you to Kotag, a tailor of great renown, who has their shop on the eastern side of the Forgegrounds. I will mark it on your map. \n\nKotag has their very own tailoring table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guilds. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "" }
WordHunterWoW_QuestEN[84285] = { title = "Crafting Orders: Engineering", description = "So... you are an engineer, hmm?\n\nYou should meet Machinist Arhdas in the Forgegrounds. I will mark his location on your map. \n\nArhdas has an engineering table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guilds. If you are lucky, you might come across an order from a renowned person which offers some extra rewards--or so I hear.", objectives = "" }
WordHunterWoW_QuestEN[84287] = { title = "Crafting Orders: Inscription", description = "So you are an inscriber? I know one of the best inscribers in Dornogal.\n\nYou should look for Brrigan on the southern edge of the Forgegrounds. \n\nBrrigan owns a drafting table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "" }
WordHunterWoW_QuestEN[84288] = { title = "Crafting Orders: Alchemy", description = "So you are an alchemist? I see.\n\nYou should visit Tarig. She's an alchemist like you. \n\nTarig has her alchemist lab bench set up in the southern part of the Forgegrounds. From there, she can help you review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might receive an order from renowned persons offering extra rewards.", objectives = "" }
WordHunterWoW_QuestEN[84296] = { title = "The Trail's Gone Cold", description = "I've tracked the scent of Scrapes as far as here, but this cold air smothers our lead. I found a couple scraps of notes. Nothing useful yet, but he seems to have left a paper trail in his hurry.\n\nLook for clues that may indicate where our villain's lair is hidden. I will mark what I found on your map.\n\nTake Spirit's whistle. Call upon us when you are in need of assistance.", objectives = "" }
WordHunterWoW_QuestEN[84298] = { title = "HELP WANTED: Kaja'Curiosity", description = "<This listing is new, posted by the Bilgewater Cartel.>\n\nDo you like kaja'mite? Are ya ready to get your intellectual fix under some tropical sun? Want to develop cutting-edge tools that will only explode when we tell them to? Hop on a rocket drill to the Kaja'Coast!\n\nNo prior experience required. Combat capabilities extremely welcome. Contractors are liable for their own safety. Compensation and working hours negotiable on-site. \n\nPlease seek Jazz Mokkitz on the Kaja'Coast for more information.", objectives = "" }
WordHunterWoW_QuestEN[84299] = { title = "Pirate Plunder", description = "We got a good thing here, but these pirates are bad for business! They're stealin' all the special gems, an' they even made off with our Kaja'Cola stash!\n\nGet rid of these pirate losers and recover any of the stuff they took from us!", objectives = "" }
WordHunterWoW_QuestEN[84300] = { title = "Refine, Repair, Repeat", description = "<Jazz holds up a well-polished crystal of kaja'mite.>\n\nMost materials aren't ready to use straight outta the ground--kaja'mite included. I've got a few refined crystals to tinker with, but I'll need more.\n\nI rigged up some refiners on the slope, but halfway through the cycle elementals started beatin' on 'em pretty hard. \n\nCould you see if you could get 'em goin' again? You look like you could handle those angry rocks, and my wife likes it when I come home without injuries.", objectives = "" }
WordHunterWoW_QuestEN[84301] = { title = "Mineral Madness", description = "With all these elementals wreakin' havoc, it's impossible to work out here! How are we supposed to gather raw material when they're swingin' at us with the stuff?\n\n<Jazz stops, eyes lighting up.>\n\n{name}, those elementals ARE our raw material. Smashin' 'em up is our best bet--though, you'll have to do that for me. \n\nNow, keep it movin'! Time is money, and I ain't one to waste perfectly good research funding.", objectives = "" }
WordHunterWoW_QuestEN[84302] = { title = "Creative Iteration", description = "Alright, {name}, time for this to get serious. You got the crystals, and I've got our parts to work with!\n\nKaja'mite is good for containin' volatile energy. I think we can do better than Darkfuse weaponry, but first, we need a proof of concept.\n\nI've got this old, glitchy, junk shrink ray. The kaja'mite should stabilize it. If it does, we've got a potential breakthrough!\n\nI need an extra set of hands to tinker on this thing. Just follow my instructions and you'll stay in one piece. Probably.", objectives = "" }
WordHunterWoW_QuestEN[84303] = { title = "Experimental Application", description = "<Jazz shoves the shrink ray into your hands.>\n\nOnly thing left to do is test the prototype, {name}. Try using it on the elementals! If it can work on those, it'll work on anything, probably. \n\nDon't expect the effects to last, though. It's only a first iteration! And keep contained to the mines. Just in case we need to bury any problems.  \n\nOh, don't give me that look. I built this originally to make spiders easier for my wife to handle. I promise, there's at least ONE functional failsafe.", objectives = "" }
WordHunterWoW_QuestEN[84304] = { title = "A Gem-Splitting Headache", description = "Hey, {name}, I'm not usually one for revenge, but I've got an idea.\n\nThat big guy who tossed us around ran up this way. I'll bet you good money it's in the mines somewhere, and I bet we could get a giant sample off its body. That'd set me up real nice for future tinkering.\n\nBesides, taking it out means it won't come back, and I'd like to finish this gig intact. I've got bills to pay, and kids to feed! \n\nTry the shrink ray on that hunk o' rock. Show it who's boss! For science, of course.", objectives = "" }
WordHunterWoW_QuestEN[84305] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84306] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84307] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84308] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84310] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84311] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84313] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84314] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84315] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84316] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[84334] = { title = "Warn the Detective", description = "Welcome back, {name}.\n\nI saw the detective headed west. Hurry up and warn him before the shapeshifter comes for him too!", objectives = "" }
WordHunterWoW_QuestEN[84336] = { title = "Spot the Difference", description = "Look, I'm the real detective. You believe me, right?\n\nI know--ask me anything. The good people here will be able to corroborate my story and we'll prove that I'm me.", objectives = "" }
WordHunterWoW_QuestEN[84352] = { title = "No More Walkin' Here", description = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at the Caddy Shack and see if she'll lend you some wheels.", objectives = "" }
WordHunterWoW_QuestEN[84363] = { title = "Tweasure Hunt", description = "I know! We could use da stick to look for tweasures!\n\nYou and Enzo go check da other ruins. Find somefing really cool!\n\nI'll meet you back at da parties.", objectives = "" }
WordHunterWoW_QuestEN[84365] = { title = "Something on the Horizon", description = "Brann's scouts have reported sightings of reinforcements approaching the shores of Khaz Algar.\n\nHe's put out the call for adventurers to join him in Dornogal.", objectives = "" }
WordHunterWoW_QuestEN[84367] = { title = "A Time to Come Together", description = "We ought tae be getting a whole fleet o' reinforcements soon. Just in time, I hear Alleria and Anduin are back in Dornogal.\n\nIf I know Moira, she'll already be workin' with 'em tae figure out our next move. She knows how tae lead like a gryphon knows how tae fly. Best go find her before she comes looking for ye.", objectives = "" }
WordHunterWoW_QuestEN[84370] = { title = "The Key to Success", description = "<A Cipher Key? Elise Starseeker might know what to do with this.>", objectives = "" }
WordHunterWoW_QuestEN[84371] = { title = "Lorewalking: The Blade and the High Priest", description = "Xal'atath, the Harbinger of Void, is a cunning and dangerous foe. She has been careful to make her presence known only to a precious few.\n\nWe first learned of her during the Legion's third invasion of Azeroth, but whispers say she has been around since long, long before that. \n\nThis is a story of power, darkness, and deceit. Join me and I will tell you the tale of Xal'atath's mysterious past.", objectives = "" }
WordHunterWoW_QuestEN[84376] = { title = "Property Devalued", description = "<You come across a wanted poster that has been nailed on top of a for rent sign.>\n\nWANTED: Seeking able-bodied adventurer to work as security for local apartment complex.\n\nMust be capable of not dying.\n\nREWARD: Free room and board in exchange for services rendered.\n\nInterested parties should inquire upstairs at the nearby Barrelbottom Apartments for further details.", objectives = "" }
WordHunterWoW_QuestEN[84378] = { title = "Renter's Insurance", description = "It's bad enough that the old skinflint landlord is letting this place slowly fall apart, but now we got even bigger problems. \n\nRecently, those would-be gangsters up the road, the Underriders, went from petty theft and noise complaints to being a heavily armed menace. They've started trashing the place, and even attackin' us directly!\n\nWhat's worse, anyone who can't afford to move out are evicted for the damage those thugs caused instead.\n\nYou keep us safe, you can crash here free of charge.", objectives = "" }
WordHunterWoW_QuestEN[84379] = { title = "Tenant Trouble", description = "<Gabi waves you over urgently.\n\nThe small goblin wrings her hands together nervously trying to find the words to explain her concern.>\n\nSome goblins aren't moving out--they're being kidnapped. I know it. \n\nMy friends wouldn't have moved. They wouldn't.\n\n<Gabi looks up at you imploringly with misty eyes.>\n\nPlease help, {class}. Please?", objectives = "" }
WordHunterWoW_QuestEN[84380] = { title = "Weapons Cash", description = "<Inside the weapons crate you find a crumpled note written to the Underriders.>\n\nGood to see you're putting your new toys to good use. These little squatters are leaving in droves thanks to you guys!\n\nKeep up the good work and there's more where this came from. Just try not to burn the whole place down. Can't rent out an empty lot, haha!\n\nSigned,\nM.B.B.", objectives = "" }
WordHunterWoW_QuestEN[84381] = { title = "Renegotiations", description = "That settles it! I think we both know who's responsible for this mess. It's that bastard landlord, Moz Barrelbottom!\n\nSoon as the Underriders were dealt with, he sent his goon Jarvis on a rampage. Looks like if he can't scare us out, he's going to force us out!\n\n<Keara spits on the ground in disgust.>\n\nHe won't scare us so easily.\n\nYou're pretty tough, {name}. Moz's office is just across the street. Go show him he's messin' with the wrong goblins!", objectives = "" }
WordHunterWoW_QuestEN[84392] = { title = "Hungry in Hollow", description = "Hey. You looking for a great meal?\n\nWilling to wade through the mud to get it?\n\nGo see Dolena. She'll sort you out. Don't bother trying to convince her to leave that hollow, though. Believe me--we've all tried. Why someone would leave the safety of the light for that...\n\nShe seems to do alright, though.", objectives = "" }
WordHunterWoW_QuestEN[84393] = { title = "Da Stick of Revealing", description = "Awwight, it's time to try da Stick of Reveawing!\n\nFowwow me.", objectives = "" }
WordHunterWoW_QuestEN[84403] = { title = "A Small Bundle of Goods", description = "", objectives = "" }
WordHunterWoW_QuestEN[84404] = { title = "A Small Bundle of Goods", description = "", objectives = "" }
WordHunterWoW_QuestEN[84419] = { title = "To da Ruins!", description = "You found my brovver's sleufing fingy!\n\n<Maru holds it up with reverence.>\n\nDa Stick of Reveawing! Dis fing can turn on da lights, melt stuff, and even unlock ANSHENT TWEASURE. And all you gotta do is hold it up!\n\nWe wuz gonna try it on dis fing outside the Wuins of Uldum. Wanna come?", objectives = "" }
WordHunterWoW_QuestEN[84423] = { title = "Shaking the Dust Off", description = "Wow, you look really strong! Would you be able to help me?\n\nMy parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. \n\nCould you go get it for me?", objectives = "" }
WordHunterWoW_QuestEN[84424] = { title = "Forward, to Adventure!", description = "We are free, {class}. Free to do whatever it is we wish.\n\nThrough the portal lies the rest of your life.\n\nA member of the bronze dragonflight will help you on your journey.", objectives = "" }
WordHunterWoW_QuestEN[84426] = { title = "Waterlogged Celebration Crate", description = "<The crate is soaking wet, but the insides might be salvageable. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84430] = { title = "Crystal Crusade", description = "I swore my life to protect Beledar... and now a new star sings to us from the sea.\n\nI know not what this means for the Arathi, but I do know that letting these foul creatures of the deep snatch up pieces of it is likely to lead to ill. \n\nKill them with extreme prejudice and recover any pieces of the crystal in their possession.", objectives = "" }
WordHunterWoW_QuestEN[84432] = { title = "Longship Landing", description = "These Bloodwake vrykul have no regard for us or our research. Even when we tried to share our discoveries with them, we were attacked! \n\nThey do not care that we mean the isle no harm--they want us to leave.\n\nBut we cannot leave now. There is so much more to discover! Someone must show them that we're not going to go just yet and that they should leave us alone.\n\nWe need to show them we will fight back.", objectives = "" }
WordHunterWoW_QuestEN[84435] = { title = "Nola's Last Wish", description = "Greetings, {name}! Could you check in with Lashk?\n\nHe seemed upset about something.", objectives = "" }
WordHunterWoW_QuestEN[84438] = { title = "Easy Win", description = "", objectives = "" }
WordHunterWoW_QuestEN[84439] = { title = "Kaja'Conclusions", description = "You've really helped me out here, {name}, but I need one more teeny tiny favor from you. \n\n<Jazz hands over an envelope stuffed to the brim with schematics and paper reports.>\n\nCould ya get this to my contract agent, Kory Hoxx? He'll get it to HQ. You'll probably catch him in the Incontinental Hotel, putting up more gig sheets.", objectives = "" }
WordHunterWoW_QuestEN[84442] = { title = "Invitation to the Spirit Festival", description = "Greetings, {name}. It's been too long since I've returned to Shen-zin Su. I miss him... and I miss everyone that calls him home as well.\n\nWould you like to attend the Spirit Festival? Li Li asked for you specifically.\n\nI seem to remember she fought with her father during one year's festival. However, he's the one who extended the invitation to her this time. Perhaps he just wants to see her return home. \n\nJi will be coming along too! Join us!", objectives = "" }
WordHunterWoW_QuestEN[84444] = { title = "Invitation to the Spirit Festival", description = "Hey, {name}.  It's been a while since I've been back home, to Shen-zin Su. Remember that old turtle? Still wandering the Great Sea...\n\nLi Li asked me to pass along an invitation to the Spirit Festival. It's funny, I remember Li Li and her father had a huge fight about it one year.\n\nBut guess who the original invite's from? Her father! I guess they get along better these days. Or maybe he just wants her to come home. Who knows?\n\nAysa's coming along too. Will you join us?", objectives = "" }
WordHunterWoW_QuestEN[84446] = { title = "Renown of Khaz Algar", description = "There is still much we still need tae do to aid Khaz Algar.\n\nBut I dunnae know much about this land past the realms of earthen.\n\nI'll have to refer ye to Faerin Lothar tae see what Hallowfall may need.\n\nTalk to her an' see if she needs any help. Ye already are acquainted, aren't ye?", objectives = "" }
WordHunterWoW_QuestEN[84451] = { title = "The Wanderers", description = "{name}! I'm so happy you're here. My dad asked me to invite all my friends to the Spirit Festival. It feels a little strange that he cares about it this year. We haven't celebrated it since I was a cub!\n\nI suppose we should go, huh? See dad, see home? When's the last time you've been back, anyway? I finally have some free time. And... I'm really glad you're going with us.\n\n<Li Li smiles--half anxious, half something else.>\n\nLet's enjoy this together.", objectives = "" }
WordHunterWoW_QuestEN[84452] = { title = "The Wanderers", description = "{name}! I'm so happy you're here. My dad asked me to invite all my friends to the Spirit Festival. It feels a little strange that he cares about it this year. We haven't celebrated it since I was a cub!\n\nI suppose we should go, huh? See dad, see home? When's the last time you've been back, anyway? I finally have some free time. And... I'm really glad you're going with us.\n\n<Li Li smiles--half anxious, half something else.>\n\nLet's enjoy this together.", objectives = "" }
WordHunterWoW_QuestEN[84453] = { title = "To Dai-Lo Farmstead", description = "My brother Chon Po has been trying to rally everyone. He sent out handwritten invitations to each village. Can you believe that? He's a brewmaster--he should've sent brew!\n\nDai-Lo Farmstead was like a second home to us. Chon Po and I spent half our childhood there, helping with the harvests. It's where we made our very first drinks.\n\nLet's give the Dai-Lo villagers a big hit of nostalgia, and something new--as a teaser for what's to come at the festival.", objectives = "" }
WordHunterWoW_QuestEN[84454] = { title = "Tide of Virmen", description = "I was hoping for a heartier welcome when we arrived. Unfortunately, many of the villagers are occupied in the farmland. The harvest is in full swing, and so are the virmen.\n\nWe've fought these pests all my life. I don't know how they keep coming!\n\nChon Po and I are busy setting up the drink tasting. Can you take care of the problems in the field?", objectives = "" }
WordHunterWoW_QuestEN[84455] = { title = "Big Bertha", description = "I love Chen's idea to entice the villagers with a brew tasting. I'm surprised I didn't think of it first!\n\nMy friends were hoping to take a large portion of the harvest to the festival. But Big Bertha is missing! We need her if we ever hope to haul back all the food and drink in time.\n\nThe villagers say she suddenly broke from her cart and disappeared underground.\n\nI'm worried. She may be large, but she has a soft heart. Can you go find her?", objectives = "" }
WordHunterWoW_QuestEN[84456] = { title = "To Morning Breeze", description = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody has shown up.\n\nThat's very strange. They're usually the ones most excited about the Spirit Festival. They'll use any excuse to make and set off their fireworks!\n\nSomething must have happened. Let's go see.", objectives = "" }
WordHunterWoW_QuestEN[84457] = { title = "To Morning Breeze", description = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody showed up.\n\nThat's odd. They're usually the ones most excited about the Spirit Festival. Any excuse to make and set off their fireworks!\n\nSomething must be up. Let's find out.", objectives = "" }
WordHunterWoW_QuestEN[84458] = { title = "Devil's in the Details", description = "Let's investigate the village for signs of mischief. I don't believe that the fireworks were simply misplaced. Shisai is a watchful pandaren and this is his big contribution to the festival.\n\nThe theft must have happened recently. Someone must have seen something.", objectives = "" }
WordHunterWoW_QuestEN[84459] = { title = "Scamps Ain't It!", description = "Shisai said the fireworks were in a barrel... \n\n<Ji paws at his face.> \n\nAnd... he likely put them in the wrong barrel. Amidst the festival's extensive preparation, it'd be a miracle if none of the goods were crossed.\n\nWell then, let's search the barrels! It won't take long.", objectives = "" }
WordHunterWoW_QuestEN[84460] = { title = "Red Hand or Herring?", description = "Every clue points at the hozen stealing the fireworks! It is as Ji said. They've done it before--they'll do it again.\n\nLet us confront them right now.", objectives = "" }
WordHunterWoW_QuestEN[84461] = { title = "It's Not a Spirit Festival Without Spirits", description = "<The crane bears a letter. It's from Li Li.>\n\nSomething's wrong at the Temple of Five Dawns. I need your help. Please come as soon as you can!", objectives = "" }
WordHunterWoW_QuestEN[84462] = { title = "Patterns in Static", description = "I can't find any of the spirits in the temple. How are we going to have a Spirit Festival with no spirits?\n\nToday is a celebration for all four of the elemental spirits, but perhaps they also think today is just another day. We need to find them and tell them otherwise!\n\nLook, is this the wind spirit's trail? Maybe it will lead us to Dafeng... who can lead us to the others.", objectives = "" }
WordHunterWoW_QuestEN[84463] = { title = "Codependency", description = "Ah, {name}! Are you and Li Li back for the festival? My heart warms to see your return.\n\nNot all is well today, though. The spirits seem restless and have scattered. Dafeng and I have been looking for them everywhere.\n\nWell, I found Shu and Wuguo. Unfortunately, I found them... together. They got into a fight, and do you know what happens when you mix water and earth? A mud monster, that's what!\n\nWe must break them up. Fortunately, that's something I know plenty about.", objectives = "" }
WordHunterWoW_QuestEN[84464] = { title = "Lost My Spark", description = "Dafeng led me here, but then he flew away. I think he senses Huo, the spirit of fire, nearby.\n\nWhy are all the spirits in such a state today? The festival is for them, after all. I was anxious about returning home, but didn't know why. The spirits have always reflected the truth about the isle and its pandaren. If they're agitated, something must be wrong... or something has to change.\n\n<Li Li sighs and shakes her head.>\n\nFor now, we need to find Huo, and quickly. This steam trail must be his.", objectives = "" }
WordHunterWoW_QuestEN[84465] = { title = "Of Water and Blood", description = "Mr. Crane told me about your success in the other villages. Now that we've found the spirits, we can begin the festivities.\n\nBut before we go, {name}... will you come with me to the Wood of Staves? I'd love your help gathering flowers while we're there. I hear the woods are still crawling with scamps.\n\nIt's to see my... family. I'd like to pay them a visit, before the festival. Just for a moment.\n\nIt's been too long.", objectives = "" }
WordHunterWoW_QuestEN[84466] = { title = "Thousands of Years Ago...", description = "The world is changing as we speak. We've been through so much.\n\nBut it's like time skips this isle. Everything is exactly as I remembered... is that a good thing, {name}? Is it even possible?\n\nEven the ancients grow older. Shen-zin Su must be looking for something more, after all this time. Perhaps the spirits don't want this to just be another year.\n\nAnyway, we should head back to Wu-song Village before they start the festival without us. Let's not keep everyone waiting.", objectives = "" }
WordHunterWoW_QuestEN[84467] = { title = "This Was Home", description = "{name}!\n\nI cannot believe my eyes--Shen-zin Su, the Wandering Isle? Here?\n\nAnd his return to the shores of his birth coincided with the annual Spirit Festival? This cannot be a coincidence. You must have restored some sense of purpose and peace to him--and within everyone here as well.\n\nI have much to explore here. But first, we must celebrate this reunion! My dear friends!", objectives = "" }
WordHunterWoW_QuestEN[84468] = { title = "Brew You One Better", description = "Ready for the brew tasting? We've caught the attention of a small crowd already.\n\nI've got something that will send their heads spinning--ingredients they've never even heard of before, and impeccable technique...\n\n<With a flourish, Chen places a ribbon of cucumber on a drink.>", objectives = "" }
WordHunterWoW_QuestEN[84469] = { title = "Battle Pet Bingo", description = "Well, hi there! The grand master pet tamers from Pandaria have posted a challenge to find certain battle pets on this fancy-lookin' bingo card. \n\nAll we have to do is find the pet that goes to the riddle and note it down on our bingo cards, but I'm having a hard time with the last two. It's quite easy to spot the normal pets, but these bingo cards require us to find special versions of the creatures.\n\nHmm... They didn't say anything in the rules about getting outside help. Care to help a friend out?", objectives = "" }
WordHunterWoW_QuestEN[84470] = { title = "Dirt-Caked Celebration Crate", description = "<Though unearthed and dusted off, this crate still smells of death. Regardless, Alyx would likely appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84489] = { title = "Shopping Squee!", description = "Now that you have an idea of some of the main attractions, let's talk shopping.\n\nThe main pavilion here contains just a few of places where you can look for amazing new purchases. Do a loop and talk to the shopkeeps to see what they have to offer.\n\nOnce you are done, come back and let me know if anything caught your fancy.\n\nTa-ta!", objectives = "" }
WordHunterWoW_QuestEN[84490] = { title = "The Great Vault", description = "Many of Dornogal's systems have been dormant for millennia and are now back online. One that you might find useful, {race}, is the Great Vault.\n\nOnce, this cache of armor and weapons would have supported the earthen in their Oathsworn duty to protect Dornogal. Now it is extended to you with the expectation that you use what you find there to aid others along your quest.\n\nThe Vault is housed here in Dornogal within the Council's Treasury. The Councilward has granted you full access to its contents.", objectives = "" }
WordHunterWoW_QuestEN[84506] = { title = "Pet Pursuit", description = "Hello, adventurer!\n\nI spotted a group of battle pet tamers who were going on about a bingo game. Jepetto Joybuzz was among them and seemed to be in some distress over his progress.\n\nWhy don't you see if he could use some help?", objectives = "" }
WordHunterWoW_QuestEN[84519] = { title = "Ancient Curiosity: Combat", description = "<You hold the relic and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[84520] = { title = "Ancient Curiosity: Utility", description = "<You hold the relic and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[84521] = { title = "Thoughtful Pursuits", description = "Maru has been such a good junior sleuth that it's time to reward her with a Thinking Cap of her own!\n\nI can't just hand one over to her, though, so I've buried the parts she'll need to make one herself. I've hidden the coordinates for each part in riddles. Figure out the riddles to find the hiding places!\n\nWould you escort her to make sure she doesn't run into trouble? You can use my Thinking Cap to help. Also, I'll give you a special clue book that will reveal riddles as you progress.", objectives = "" }
WordHunterWoW_QuestEN[84542] = { title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "" }
WordHunterWoW_QuestEN[84547] = { title = "Redemption Guaranteed", description = "<Even an empty Kaja'Cola can still has value. Perhaps Blinky Greasefingers might want it.>", objectives = "" }
WordHunterWoW_QuestEN[84563] = { title = "Toy Trouble", description = "Adventurer, Maru is once again in need of your aid.\n\nShe has an urgent matter that she would like to discuss with you.", objectives = "" }
