WordHunterWoW_QuestEN[84583] = { title = "A Hozen On My Back", description = "Hello, {name}. I don't suppose I could trouble you again? A strange couple has been causing trouble near the edge of the petting area.\n\nPerhaps you could convince the hozen to stop shouting at our guests.", objectives = "" }
WordHunterWoW_QuestEN[84588] = { title = "Operation Toy Rescue", description = "Nooo! A sneaky thief has taken some of my friends' toys!\n\nYou're a good sleufer now, right? Can you halp my friend Yennu find his stolen toy? You'll find him on the Dragon Isles.", objectives = "" }
WordHunterWoW_QuestEN[84595] = { title = "The Case of the Fur-Getting Wikket", description = "Riko has had enough of these blikkety tik-digglers! All Kiryn wants is to be a furry-haver, and these mankers won't give any!\n\nKiryn says Riko needs to stop jabberings. Says taking their furries is \"stealing.\"\n\nYou a helpful wikket? Find Kiryn a furry friend! Better take notes so wikket don't get stuck.", objectives = "" }
WordHunterWoW_QuestEN[84616] = { title = "Celebrate Good Fun!", description = "Welcome to the Bronze Celebration! \n\nWe invite you to enjoy our myriad of events. You might choose to mirror your pet and run around our playground. \n\nYou could participate in one of our big events like Fashion Frenzy or Mount Mania. A different event begins every 15 minutes. \n\nOr you might fancy yourself a challenge. If so seek out Chromie as she cleans up her Codex to prepare for her tours. \n\nAny event will do, as long as you are having fun!", objectives = "" }
WordHunterWoW_QuestEN[84619] = { title = "Ooker Dooker Literature Club", description = "The hozen in the Bilge Rat crew are master scavengers. For years, they've been visiting this island, snatching up anything that might be of value.\n\nAmong their spoils are many research materials that could help unlock the history of this place.\n\nInfiltrate their camp, board their ships, and recover whatever books, scrolls, and documents you can find.", objectives = "" }
WordHunterWoW_QuestEN[84621] = { title = "Squire's Spurs", description = "You come to Campalot to pledge fealty? Become Knight of the Brown Table?\n\nNot have look of tenderfoot, but even bravest knight start as squire. Earn spurs. Learn humility.\n\nProve you have learned it in same way. See what can do to help around castle.\n\nMight be good example to other squires, too.", objectives = "" }
WordHunterWoW_QuestEN[84624] = { title = "Sandy Celebration Crate", description = "<This crate has certainly been on a journey! Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84625] = { title = "Surprisingly Pristine Celebration Crate", description = "<You found this crate of celebration supplies in the unmarked grave where you buried the bones in their place. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84627] = { title = "Three Heads of the Deep", description = "The reach of these creatures is truly frightening!\n\nI have encountered them countless times in the Imperial waters. I know their strategies well, and I have a plan to deal with them.\n\nMy scouts have pinpointed the location of three of their leaders. Eliminate them, and we'll seize the advantage.", objectives = "" }
WordHunterWoW_QuestEN[84638] = { title = "Trouble in the Highlands", description = "Both Geya'rah and Danath have received word of unrest in the Arathi Highlands--civil unrest in Stromgarde, and raids on Mag'har and Stromic outposts.\n\nDanath and Geya'rah are returning to their homes, Stromgarde and Hammerfall, to defuse tensions.\n\nI asked to accompany them. I have long wanted to reconnect myself and my people to the Arathi. I also want to learn more about the Horde.\n\nGeya'rah was willing, but... Danath took some convincing.\n\nThough, I may have implied you were joining me...", objectives = "" }
WordHunterWoW_QuestEN[84639] = { title = "Torches and Tar", description = "We've been attacked before. But this time... \n\n<Walker shudders.>\n\nThis was different.\n\nThey didn't want livestock, grain, or money. They took torches and some barrels of tar we use to fix our roofs.\n\nI don't know what they're going to do with it, but... I can guess. They're going to burn something down.\n\nYou need to stop them before they do another homestead harm!", objectives = "" }
WordHunterWoW_QuestEN[84640] = { title = "Emblematic of Things to Come", description = "<This Defias bandit was carrying a badge with an unfamiliar emblem.\n\nThe emblem looks like a rising sun with long rays emanating from it. The sun and rays are colored red.\n\nPerhaps Danath can identify it.>", objectives = "" }
WordHunterWoW_QuestEN[84641] = { title = "Ill Tidings", description = "A Defias attack. The theft of tar and torches. A group called the Red Dawn recruiting here in the heart of the Highlands...\n\nStromgarde was right to send a missive asking for my return. What is going on here?\n\nI placed Colonel Nials in charge after Marran's foolishness led to her imprisonment. I must head to Stromgarde and speak with Nials immediately.", objectives = "" }
WordHunterWoW_QuestEN[84643] = { title = "Curfew Kerfuffle", description = "I'm glad for your help. Between deployments to Khaz Algar, responding to threats in the Highlands, and desertion, we simply don't have enough soldiers to enforce order.\n\nMarran's supporters are causing trouble throughout the city. They're stealing supplies, harassing people--you name it. We've enacted a curfew, but Marran's supporters are openly defying it.\n\nAs my deputies, go around and tell the troublemakers to go home. If they get rowdy, you have my permission to teach them a lesson.", objectives = "" }
WordHunterWoW_QuestEN[84645] = { title = "Deputy Delivery", description = "Trade in Stromgarde has broken down. We're short on goods and workers because of the attacks.\n\nNials was too busy, so I took it upon myself to write official requests for aid.\n\nMost are simple and straightforward--writs for supplies and such for the Stromic army.\n\nThe desist writ for Joseph is different. He is loudly blaming everyone not human for our woes. Someone needs to officially tell him to shut his yap before he starts a riot.\n\nAs my deputies, would you enforce my requests for aid?", objectives = "" }
